{"command":"python3 - <<'PY'
import subprocess, json, os
def run(args):
    p=subprocess.run(["./executable"]+args, capture_output=True, text=True)
    return p.stdout, p.stderr, p.returncode

names=open("/tmp/names.txt").read().splitlines()
docs={}
for n in names:
    out,err,rc=run(["doc",n])
    docs[n]={"out":out,"err":err,"rc":rc}
open("/tmp/docs.json","w").write(json.dumps(docs,indent=2))
print("done")
# show few
for n in names[:3]:
    print("===",n)
    print(repr(docs[n]["out"]))
    print(repr(docs[n]["err"]), docs[n]["rc"])
# unknown doc
for args in [["doc","unknown"],["doc","appendassign"],["doc","appendAssign","extra"],["doc","-unknown"],["doc","--help"]]:
    out,err,rc=run(args)
    print(args, "rc",rc, "out",repr(out[:500]), "err",repr(err[:500]))
PY"}

