def lev(a,b):
    dp=list(range(len(b)+1))
    for i,ca in enumerate(a,1):
        ndp=[i]+[0]*len(b)
        for j,cb in enumerate(b,1):
            ndp[j]=min(dp[j]+1, ndp[j-1]+1, dp[j-1]+(ca!=cb))
        dp=ndp
    return dp[-1]
cmds=["check","doc","help","version"]
words=["chk","heck","elp","vers","ver","verson","hlp","d","oc","ck","ch","abc","hop","hock","cock","choc","c","v","ve","verb","helpme","help123","versioxx"]
for w in words:
    print(w, [(c,lev(w,c)) for c in cmds])
