package main

import (
	"fmt"
	"os"
)

const appVersion = "v0.0.0-SNAPSHOT"

const helpText = `Usage:

    go-critic <command> [arguments...]

The commands are:

    check             run linter over specified targets
    doc               get installed checkers documentation
    help              shows help message
    version           shows version of the application

Version: v0.0.0-SNAPSHOT

`

var commandNames = []string{"check", "doc", "help", "version"}

func main() {
	// The reference program performs some environment dependent
	// initialisation before dispatching a command.  It is not needed to
	// implement the checker set in this implementation except for a
	// small emulation in maybeFailEmbeddedLoad.
	maybeFailEmbeddedLoad()

	args := os.Args[1:]
	if len(args) == 0 {
		fmt.Fprintln(os.Stderr, "no args provided")
		return
	}
	// An empty first argument is silently ignored by the reference
	// command dispatcher.
	if args[0] == "" {
		return
	}
	switch args[0] {
	case "help":
		fmt.Print(helpText)
	case "version":
		fmt.Printf("go-critic version: %s\n\n", appVersion)
	case "doc":
		runDoc(args[1:])
	case "check":
		if code, doExit := runCheck(args[1:]); doExit {
			os.Exit(code)
		}
	default:
		name := args[0]
		if suggestion := suggestCommand(name); suggestion != "" {
			fmt.Printf("%q unknown command, did you mean %q?\n", name, suggestion)
		} else {
			fmt.Printf("%q unknown command\n", name)
		}
		fmt.Printf("Run \"go-critic help\" for usage.\n\n")
		fmt.Fprintf(os.Stderr, "no such command %q\n", name)
	}
}

func suggestCommand(name string) string {
	best := ""
	bestDist := 3 // only distances <= 2 are candidates; 3 acts as infinity
	for _, candidate := range commandNames {
		d := byteLevenshtein(name, candidate)
		if d < bestDist {
			bestDist = d
			best = candidate
		}
	}
	if bestDist <= 2 {
		return best
	}
	return ""
}

func byteLevenshtein(a, b string) int {
	//Classic dynamic programming Levenshtein over bytes (not runes).
	prev := make([]int, len(b)+1)
	cur := make([]int, len(b)+1)
	for j := range prev {
		prev[j] = j
	}
	for i := 1; i <= len(a); i++ {
		cur[0] = i
		for j := 1; j <= len(b); j++ {
			cost := 1
			if a[i-1] == b[j-1] {
				cost = 0
			}
			cur[j] = min3(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
		}
		copy(prev, cur)
	}
	return prev[len(b)]
}

func min3(a, b, c int) int {
	if a < b {
		if a < c {
			return a
		}
		return c
	}
	if b < c {
		return b
	}
	return c
}
