func runDoc(args []string) {
	fs := flag.NewFlagSet("go-critic", flag.ContinueOnError)
	if err := fs.Parse(args); err != nil {
		// The doc command prints the parse error a second time and
		// otherwise treats it as a successful invocation.
		fmt.Fprintln(os.Stderr, err)
		return
	}
	rest := fs.Args()
	switch len(rest) {
	case 0:
