		if !ok {
			fmt.Fprintf(os.Stderr, "checker with name %q not found\n", rest[0])
			os.Exit(1)
		}
		fmt.Print(doc)
	default:
		fmt.Fprintln(os.Stderr, "expected 0 or 1 positional arguments")
		os.Exit(1)
	}
}
