package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/ast"
	"go/build"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"runtime"
	"runtime/pprof"
	"sort"
	"strconv"
	"strings"

	"golang.org/x/tools/go/packages"
)

type checkerMeta struct {
	Name string
	Tags []string
}

type checkerParams struct {
	captLocalParamsOnly             bool
	commentedOutCodeMinLength       int
	elseifSkipBalanced              bool
	hugeParamSizeThreshold          int
	ifElseChainMinThreshold         int
	nestingReduceBodyWidth          int
	rangeExprCopySizeThreshold      int
	rangeExprCopySkipTestFuncs      bool
	rangeValCopySizeThreshold       int
	rangeValCopySkipTestFuncs       bool
	ruleguardDebug                  string
	ruleguardDisable                string
	ruleguardEnable                 string
	ruleguardFailOn                 string
	ruleguardFailOnError            bool
	ruleguardRules                  string
	tooManyResultsMaxResults        int
	truncateCmpSkipArchDependent    bool
	underefSkipRecvDeref            bool
	unnamedResultCheckExported      bool
}

type checkOptions struct {
	params              checkerParams
	checkGenerated      bool
	checkTests          bool
	concurrency         int
	cpuprofile          string
	disable             string
	enable              string
	enableAll           bool
	exitCode            int
	goVersion           string
	memprofile          string
	shorterErrLocation  bool
	verbose             bool
	targets             []string
}

const defaultEnabledCheckers = "appendAssign,argOrder,assignOp,badCall,badCond,captLocal,caseOrder,codegenComment,commentFormatting,defaultCaseOrder,deprecatedComment,dupArg,dupBranchBody,dupCase,dupSubExpr,elseif,exitAfterDefer,flagDeref,flagName,ifElseChain,mapKey,newDeref,offBy1,regexpMust,singleCaseSwitch,sloppyLen,sloppyTypeAssert,switchTrue,typeSwitchVar,underef,unlambda,unslice,valSwap,wrapperFunc"

type goVersion struct {
	major int
	minor int
}

func (v goVersion) isAtLeast(major, minor int) bool {
	if v.major != major {
		return v.major > major
	}
	return v.minor >= minor
}
func (v goVersion) lessThan(major, minor int) bool { return !v.isAtLeast(major, minor) }

func defaultGoVersion() goVersion {
	// runtime.Version looks like "go1.25.11" or a devel version.
	s := strings.TrimPrefix(runtime.Version(), "go")
	parts := strings.Split(s, ".")
	if len(parts) >= 2 {
		major, err1 := strconv.Atoi(parts[0])
		mn := parts[1]
		// Strip non-digits at the end of the minor part (devel strings).
		end := 0
		for end < len(mn) && mn[end] >= '0' && mn[end] <= '9' {
			end++
		}
		minor, err2 := strconv.Atoi(mn[:end])
		if err1 == nil && err2 == nil {
			return goVersion{major, minor}
		}
	}
	return goVersion{1, 21}
}

// setGoVersion mirrors the reference parser, including its panics.
func parseGoVersionFlag(v string, current goVersion) goVersion {
	s := strings.TrimPrefix(v, "go")
	if s == "" {
		return current
	}
	parts := strings.Split(s, ".")
	if len(parts) != 2 {
		panic("invalid Go version format: " + s)
	}
	major, err := strconv.Atoi(parts[0])
	if err != nil {
		panic(fmt.Sprintf("invalid major version part: %s: %s", parts[0], err))
	}
	minor, err := strconv.Atoi(parts[1])
	if err != nil {
		panic(fmt.Sprintf("invalid minor version part: %s: %s", parts[1], err))
	}
	return goVersion{major, minor}
}

type program struct {
	opts       checkOptions
	version    goVersion
	fset       *token.FileSet
	packages   []*packages.Package
	checkers   []enabledChecker
	foundIssue bool
	wd         string
}

type enabledChecker struct {
	meta    checkerMeta
	factory func(*checkerParams) checkerInstance
	inst    checkerInstance // per-package instance, set while a package is checked
}

func runCheck(args []string) (int, bool) {
	opts, err := parseCheckArgs(args)
	if err != nil {
		fmt.Fprintf(os.Stderr, "parse args: %s\n", err)
		return 1, true
	}
	prog := &program{opts: opts, version: defaultGoVersion()}
	if wd, err := os.Getwd(); err == nil {
		prog.wd = wd
	}
	if err := prog.loadProgram(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1, true
	}
	if err := prog.initCheckers(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1, true
	}
	prof := startProfiling(opts)
	prog.runCheckers()
	if err := prof.finish(); err != nil {
		fmt.Fprintf(os.Stderr, "finish profiling: %s\n", err)
		return 1, true
	}
	if prog.foundIssue {
		return opts.exitCode, true
	}
	return 0, false
}

func parseCheckArgs(args []string) (checkOptions, error) {
	var opts checkOptions
	fs := flag.NewFlagSet("go-critic", flag.ContinueOnError)
	p := &opts.params
	fs.BoolVar(&p.captLocalParamsOnly, "@captLocal.paramsOnly", true, "whether to restrict checker to params only")
	fs.IntVar(&p.commentedOutCodeMinLength, "@commentedOutCode.minLength", 15, "min length of the comment that triggers a warning")
	fs.BoolVar(&p.elseifSkipBalanced, "@elseif.skipBalanced", true, "whether to skip balanced if-else pairs")
	fs.IntVar(&p.hugeParamSizeThreshold, "@hugeParam.sizeThreshold", 80, "size in bytes that makes the warning trigger")
	fs.IntVar(&p.ifElseChainMinThreshold, "@ifElseChain.minThreshold", 2, "min number of if-else blocks that makes the warning trigger")
	fs.IntVar(&p.nestingReduceBodyWidth, "@nestingReduce.bodyWidth", 5, "min number of statements inside a branch to trigger a warning")
	fs.IntVar(&p.rangeExprCopySizeThreshold, "@rangeExprCopy.sizeThreshold", 512, "size in bytes that makes the warning trigger")
	fs.BoolVar(&p.rangeExprCopySkipTestFuncs, "@rangeExprCopy.skipTestFuncs", true, "whether to check test functions")
	fs.IntVar(&p.rangeValCopySizeThreshold, "@rangeValCopy.sizeThreshold", 128, "size in bytes that makes the warning trigger")
	fs.BoolVar(&p.rangeValCopySkipTestFuncs, "@rangeValCopy.skipTestFuncs", true, "whether to check test functions")
	fs.StringVar(&p.ruleguardDebug, "@ruleguard.debug", "", "enable debug for the specified named rules group")
	fs.StringVar(&p.ruleguardDisable, "@ruleguard.disable", "", "comma-separated list of disabled groups or skip empty to enable everything")
	fs.StringVar(&p.ruleguardEnable, "@ruleguard.enable", "<all>", "comma-separated list of enabled groups or skip empty to enable everything")
	fs.StringVar(&p.ruleguardFailOn, "@ruleguard.failOn", "", "Determines the behavior when an error occurs while parsing ruleguard files.\nIf flag is not set, log error and skip rule files that contain an error.\nIf flag is set, the value must be a comma-separated list of error conditions.\n* 'import': rule refers to a package that cannot be loaded.\n* 'dsl':    gorule file does not comply with the ruleguard DSL.")
	fs.BoolVar(&p.ruleguardFailOnError, "@ruleguard.failOnError", false, "deprecated, use failOn param; if set to true, identical to failOn='all', otherwise failOn=''")
	fs.StringVar(&p.ruleguardRules, "@ruleguard.rules", "", "comma-separated list of gorule file paths. Glob patterns such as 'rules-*.go' may be specified")
	fs.IntVar(&p.tooManyResultsMaxResults, "@tooManyResultsChecker.maxResults", 5, "maximum number of results")
	fs.BoolVar(&p.truncateCmpSkipArchDependent, "@truncateCmp.skipArchDependent", true, "whether to skip int/uint/uintptr types")
	fs.BoolVar(&p.underefSkipRecvDeref, "@underef.skipRecvDeref", true, "whether to skip (*x).method() calls where x is a pointer receiver")
	fs.BoolVar(&p.unnamedResultCheckExported, "@unnamedResult.checkExported", false, "whether to check exported functions")

	fs.BoolVar(&opts.checkGenerated, "checkGenerated", false, "whether to check generated files")
	fs.BoolVar(&opts.checkTests, "checkTests", true, "whether to check test files")
	fs.IntVar(&opts.concurrency, "concurrency", runtime.GOMAXPROCS(0), "how many concurrent checkers to run (default is runtime.GOMAXPROCS(0))")
	fs.StringVar(&opts.cpuprofile, "cpuprofile", "", "write CPU profile to the specified file")
	fs.StringVar(&opts.disable, "disable", "", "comma-separated list of checkers to be disabled. Can include #tags")
	fs.StringVar(&opts.enable, "enable", defaultEnabledCheckers, "comma-separated list of enabled checkers. Can include #tags")
	fs.BoolVar(&opts.enableAll, "enableAll", false, "identical to -enable with all checkers listed. If true, -enable is ignored")
	fs.IntVar(&opts.exitCode, "exitCode", 1, "exit code to be used when lint issues are found")
	fs.StringVar(&opts.goVersion, "go", "", "select the Go version to target. Leave as string for the latest")
	fs.StringVar(&opts.memprofile, "memprofile", "", "write memory profile to the specified file")
	fs.BoolVar(&opts.shorterErrLocation, "shorterErrLocation", true, "whether to replace error location prefix with $GOROOT and $GOPATH")
	fs.BoolVar(&opts.verbose, "v", false, "whether to print output useful during linter debugging")

	if err := fs.Parse(args); err != nil {
		return opts, err
	}
	opts.targets = fs.Args()
	return opts, nil
}

func splitCommaList(s string) (names map[string]bool, tags map[string]bool) {
	names = make(map[string]bool)
	tags = make(map[string]bool)
	for _, item := range strings.Split(s, ",") {
		if strings.HasPrefix(item, "#") {
			tags[item[1:]] = true
		} else {
			names[item] = true
		}
	}
	return names, tags
}

func (prog *program) initCheckers() error {
	enableNames, enableTags := splitCommaList(prog.opts.enable)
	disableNames, disableTags := splitCommaList(prog.opts.disable)
	var enabled []enabledChecker
	for _, meta := range checkerMetas {
		isEnabled := prog.opts.enableAll || enableNames[meta.Name]
		if !isEnabled && !prog.opts.enableAll {
			for _, tag := range meta.Tags {
				if enableTags[tag] {
					isEnabled = true
					break
				}
			}
		}
		if !isEnabled {
			if prog.opts.verbose {
				fmt.Fprintf(os.Stderr, "\tdebug: %s: not enabled by name or tag (-enable)\n", meta.Name)
			}
			continue
		}
		if disableNames[meta.Name] {
			if prog.opts.verbose {
				fmt.Fprintf(os.Stderr, "\tdebug: %s: disabled by name (-disable)\n", meta.Name)
			}
			continue
		}
		disabledByTag := ""
		for _, tag := range meta.Tags {
			if disableTags[tag] {
				disabledByTag = tag
				break
			}
		}
		if disabledByTag != "" {
			if prog.opts.verbose {
				fmt.Fprintf(os.Stderr, "\tdebug: %s: disabled by %q tag (-disable)\n", meta.Name, disabledByTag)
			}
			continue
		}
		factory := checkerFactories[meta.Name]
		if factory == nil {
			factory = func(*checkerParams) checkerInstance { return noopChecker{} }
		}
		enabled = append(enabled, enabledChecker{meta: meta, factory: factory})
	}
	if len(enabled) == 0 {
		return fmt.Errorf("init checkers: empty checkers set selected")
	}
	// Additional initialisation that can fail for particular
	// checkers (currently ruleguard rule loading).
	for i := range enabled {
		if enabled[i].meta.Name == "ruleguard" {
			if err := validateRuleguardInit(&prog.opts.params); err != nil {
				// Print the enabled list first if verbose?  The
				// reference initialises checkers after printing
				// the enabled set?  This is adjusted by tests
				// against the reference behaviour.
				_ = i
				if prog.opts.verbose {
					for _, e := range enabled {
						fmt.Fprintf(os.Stderr, "\tdebug: %s is enabled\n", e.meta.Name)
					}
				}
				return err
			}
		}
	}
	if prog.opts.verbose {
		for _, e := range enabled {
			fmt.Fprintf(os.Stderr, "\tdebug: %s is enabled\n", e.meta.Name)
		}
	}
	prog.checkers = enabled
	return nil
}

func (prog *program) loadProgram() error {
	prog.version = parseGoVersionFlag(prog.opts.goVersion, prog.version)
	prog.fset = token.NewFileSet()
	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedFiles | packages.NeedCompiledGoFiles |
			packages.NeedImports | packages.NeedDeps | packages.NeedTypes |
			packages.NeedSyntax | packages.NeedTypesInfo | packages.NeedTypesSizes | packages.NeedModule,
		Tests: true,
		Fset:  prog.fset,
	}
	pkgs, err := packages.Load(cfg, prog.opts.targets...)
	if err != nil {
		return fmt.Errorf("load packages: %w", err)
	}
	prog.packages = filterLoadedPackages(pkgs)
	return nil
}

func filterLoadedPackages(pkgs []*packages.Package) []*packages.Package {
	// Drop synthetic test-main packages.
	var stage []*packages.Package
	for _, p := range pkgs {
		if isTestMainPackage(p, pkgs) {
			continue
		}
		stage = append(stage, p)
	}
	// For a given package path keep a single package, preferring the
	// test-augmented variant (it has at least as many files).
	byPath := make(map[string]*packages.Package)
	order := []string{}
	for _, p := range stage {
		current, ok := byPath[p.PkgPath]
		if !ok {
			byPath[p.PkgPath] = p
			order = append(order, p.PkgPath)
			continue
		}
		if preferPackage(p, current) {
			byPath[p.PkgPath] = p
		}
	}
	out := make([]*packages.Package, 0, len(order))
	for _, path := range order {
		out = append(out, byPath[path])
	}
	// The reference iterates root packages ordered by their ID.
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

func isTestMainPackage(p *packages.Package, all []*packages.Package) bool {
	if !strings.HasSuffix(p.PkgPath, ".test") || p.Name != "main" {
		return false
	}
	base := strings.TrimSuffix(p.PkgPath, ".test")
	for _, q := range all {
		if q == p {
			continue
		}
		if q.PkgPath == base && strings.Contains(q.ID, "["+p.PkgPath+"]") {
			return true
		}
	}
	return false
}

func preferPackage(candidate, current *packages.Package) bool {
	candTest := candidate.ForTest != "" && candidate.PkgPath == candidate.ForTest
	curTest := current.ForTest != "" && current.PkgPath == current.ForTest
	if candTest != curTest {
		return candTest
	}
	if len(candidate.Syntax) != len(current.Syntax) {
		return len(candidate.Syntax) > len(current.Syntax)
	}
	// Prefer the bracketed (test variant) ID on a tie.
	candBracket := strings.Contains(candidate.ID, " [")
	curBracket := strings.Contains(current.ID, " [")
	if candBracket != curBracket {
		return candBracket
	}
	return false
}

func (prog *program) runCheckers() {
	for _, pkg := range prog.packages {
		prog.checkPackage(pkg)
	}
}

func (prog *program) checkPackage(pkg *packages.Package) {
	if len(pkg.Syntax) == 0 {
		return
	}
	if prog.opts.verbose {
		fmt.Fprintf(os.Stderr, "\tdebug: checking %q package (%d files)\n", pkg.ID, len(pkg.Syntax))
	}
	// Fresh checker instances for this package.
	instances := make([]enabledChecker, len(prog.checkers))
	copy(instances, prog.checkers)
	for i := range instances {
		instances[i].inst = instances[i].factory(&prog.opts.params)
	}
	ctx := &runCtx{
		prog:  prog,
		pkg:   pkg,
		fset:  prog.fset,
		info:  pkg.TypesInfo,
		types: pkg.Types,
		sizes: pkg.TypesSizes,
	}
	if ctx.sizes == nil {
		ctx.sizes = types.SizesFor(build.Default.Compiler, build.Default.GOARCH)
	}
	// Package-specific Go version hint from the module, if no
	// explicit version was requested.  (Kept in ctx for checkers.)
	ctx.effectiveVersion = prog.version
	if prog.opts.goVersion == "" && pkg.Module != nil && pkg.Module.GoVersion != "" {
		// Module versions look like "1.21".  Parse softly.
		func() {
			defer func() { _ = recover() }()
			ctx.effectiveVersion = parseGoVersionFlag(pkg.Module.GoVersion, prog.version)
		}()
	}
	for _, file := range pkg.Syntax {
		prog.checkFile(ctx, instances, file)
	}
	for i := range instances {
		if fin, ok := instances[i].inst.(packageFinisher); ok {
			ctx.currentChecker = instances[i].meta.Name
			ctx.file = nil
			fin.FinishPackage(ctx)
		}
	}
}

func (prog *program) checkFile(ctx *runCtx, instances []enabledChecker, file *ast.File) {
	filename := prog.fset.File(file.Pos()).Name()
	if !prog.opts.checkTests && strings.HasSuffix(filename, "_test.go") {
		return
	}
	if !prog.opts.checkGenerated && ast.IsGenerated(file) {
		return
	}
	ctx.file = file
	ctx.filename = filename
	ctx.src = readFileBytes(filename)
	ctx.fileStart = prog.fset.File(file.Pos()).Base()
	ctx.fileTok = prog.fset.File(file.Pos())

	// This channel mirrors the reference program's per-file
	// concurrency semaphore closely enough to reproduce its
	// behaviour for non-positive limits.
	sem := make(chan struct{}, prog.opts.concurrency)
	for _, ec := range instances {
		sem <- struct{}{}
		func(ec enabledChecker) {
			defer func() { <-sem }()
			ctx.currentChecker = ec.meta.Name
			ec.inst.CheckFile(ctx, file)
		}(ec)
	}
}

func readFileBytes(name string) []byte {
	data, err := os.ReadFile(name)
	if err != nil {
		return nil
	}
	return data
}

// --- profiling -----------------------------------------------------------

type profiler struct {
	cpuFile string
	memFile string
	buf     *bytes.Buffer
}

func startProfiling(opts checkOptions) *profiler {
	p := &profiler{cpuFile: opts.cpuprofile, memFile: opts.memprofile}
	if p.cpuFile != "" {
		p.buf = bytes.NewBuffer(nil)
		_ = pprof.StartCPUProfile(p.buf)
	}
	return p
}

func (p *profiler) finish() error {
	if p.cpuFile != "" {
		pprof.StopCPUProfile()
		if err := os.WriteFile(p.cpuFile, p.buf.Bytes(), 0666); err != nil {
			return fmt.Errorf("write CPU profile: %w", err)
		}
	}
	if p.memFile != "" {
		f, err := os.Create(p.memFile)
		if err != nil {
			return fmt.Errorf("create mem profile: %w", err)
		}
		runtime.GC()
		_ = pprof.WriteHeapProfile(f)
		_ = f.Close()
	}
	return nil
}

// --- warning locations ---------------------------------------------------

func (prog *program) formatPos(pos token.Pos) string {
	position := prog.fset.Position(pos)
	filename := position.Filename
	if prog.opts.shorterErrLocation {
		filename = prog.shortenFilename(filename)
	}
	if position.Line <= 0 {
		return filename
	}
	if position.Column > 0 {
		return fmt.Sprintf("%s:%d:%d", filename, position.Line, position.Column)
	}
	return fmt.Sprintf("%s:%d", filename, position.Line)
}

func (prog *program) shortenFilename(filename string) string {
	if filename == "" {
		return filename
	}
	// Working-directory relative form.  The reference replaces the
	// first occurrence of "<wd>/" anywhere in the string, not just
	// a prefix.
	if prog.wd != "" {
		pattern := strings.TrimSuffix(prog.wd, "/") + "/"
		if idx := strings.Index(filename, pattern); idx >= 0 {
			return filename[:idx] + "./" + filename[idx+len(pattern):]
		}
		if prog.wd == "/" {
			// strings.TrimSuffix above already yields pattern "/".
			// The Index branch handles it, this is unreachable.
		}
	}
	// $GOPATH before $GOROOT.
	type rootPair struct{ prefix, repl string }
	roots := []rootPair{
		{build.Default.GOPATH, "$GOPATH"},
		{build.Default.GOROOT, "$GOROOT"},
	}
	for _, root := range roots {
		if root.prefix == "" {
			continue
		}
		pattern := root.prefix
		if !strings.HasSuffix(pattern, "/") {
			pattern += "/"
		}
		if strings.HasPrefix(filename, pattern) {
			candidate := root.repl + "/" + filename[len(pattern):]
			if len(candidate) <= len(filename) {
				return candidate
			}
			return filename
		}
	}
	return filename
}

// Keep the filepath import used even on platforms where helper
// functions in other files might not need it.
var _ = filepath.Separator
