cat > astutil.go <<'EOF'
package main

import (
	"bytes"
	"go/ast"
	"go/format"
	"go/token"
	"go/types"
	"strings"
)

// canonical is a position-insensitive rendering of a node used for
// equality comparisons.
func canonical(node ast.Node) string {
	if node == nil {
		return ""
	}
	var buf bytes.Buffer
	if err := format.Node(&buf, token.NewFileSet(), node); err == nil {
		return buf.String()
	}
	return ""
}

func exprEqual(a, b ast.Expr) bool {
	if a == nil || b == nil {
		return a == b
	}
	return canonical(a) == canonical(b)
}

func stmtEqual(a, b ast.Stmt) bool {
	if a == nil || b == nil {
		return a == b
	}
	return canonical(a) == canonical(b)
}

func blockEqual(a, b *ast.BlockStmt) bool {
	if a == nil || b == nil {
		return a == b
	}
	return canonical(a) == canonical(b)
}

func unwrapParen(expr ast.Expr) ast.Expr {
	for {
		if p, ok := expr.(*ast.ParenExpr); ok {
			expr = p.X
			continue
		}
		return expr
	}
}

func identName(expr ast.Expr) string {
	if id, ok := unwrapParen(expr).(*ast.Ident); ok {
		return id.Name
	}
	return ""
}

// selectorName returns (package/object expression ident name, selector)
func selectorParts(expr ast.Expr) (string, string, bool) {
	sel, ok := unwrapParen(expr).(*ast.SelectorExpr)
	if !ok {
		return "", "", false
	}
	id, ok := unwrapParen(sel.X).(*ast.Ident)
	if !ok {
		return "", sel.Sel.Name, false
	}
	return id.Name, sel.Sel.Name, true
}

// importedName returns the actual package path and name for a selector
// rooted at an imported package, when the type checker tells us so.
// It returns ok=false for method expressions on values etc.
func (ctx *runCtx) importedPkg(sel *ast.SelectorExpr) (path string, ok bool) {
	id, isIdent := unwrapParen(sel.X).(*ast.Ident)
	if !isIdent || ctx.info == nil {
		return "", false
	}
	obj := ctx.info.Uses[id]
	if obj == nil {
		obj = ctx.info.Defs[id]
	}
	pkgName, isPkg := obj.(*types.PkgName)
	if !isPkg {
		return "", false
	}
	return pkgName.Imported().Path(), true
}

func (ctx *runCtx) isPkgCall(call *ast.CallExpr, pkgPath, funcName string) bool {
	sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
	if !ok || sel.Sel.Name != funcName {
		return false
	}
	path, ok := ctx.importedPkg(sel)
	if ok {
		return path == pkgPath
	}
	// Fall back to the local package name.  This matches behaviour on
	// ill-typed code for the package's conventional local name.
	local := pkgPath
	if idx := strings.LastIndex(pkgPath, "/"); idx >= 0 {
		local = pkgPath[idx+1:]
	}
	return identName(sel.X) == local
}

func (ctx *runCtx) calledObject(call *ast.CallExpr) types.Object {
	switch fun := unwrapParen(call.Fun).(type) {
	case *ast.Ident:
		return ctx.objectOf(fun)
	case *ast.SelectorExpr:
		return ctx.objectOf(fun.Sel)
	}
	return nil
}

func basicKind(t types.Type) (*types.Basic, bool) {
	if t == nil {
		return nil, false
	}
	b, ok := t.Underlying().(*types.Basic)
	return b, ok
}

func isStringType(t types.Type) bool {
	b, ok := basicKind(t)
	return ok && b.Kind() == types.String
}

func isBoolType(t types.Type) bool {
	b, ok := basicKind(t)
	return ok && b.Kind() == types.Bool
}

func isNumericType(t types.Type) bool {
	b, ok := basicKind(t)
	if !ok {
		return false
	}
	info := b.Info()
	return info&(types.IsInteger|types.IsFloat|types.IsComplex) != 0
}

func derefType(t types.Type) types.Type {
	for {
		if ptr, ok := t.(*types.Pointer); ok {
			t = ptr.Elem()
			continue
		}
		return t
	}
}

func namedType(t types.Type) *types.Named {
	if n, ok := derefType(t).(*types.Named); ok {
		return n
	}
	return nil
}

func namedTypeString(t types.Type) string {
	if n := namedType(t); n != nil && n.Obj() != nil {
		obj := n.Obj()
		if obj.Pkg() != nil {
			return obj.Pkg().Path() + "." + obj.Name()
		}
		return obj.Name()
	}
	return ""
}

func hasMethod(t types.Type, name string) bool {
	if t == nil {
		return false
	}
	methods := types.NewMethodSet(t)
	for i := 0; i < methods.Len(); i++ {
		if methods.At(i).Obj().Name() == name {
			return true
		}
	}
	return false
}

