package main

import (
	"go/ast"
	"go/token"
	"go/types"
	"strconv"
	"strings"
)

func init() {
	checkerFactories["assignOp"] = simple(checkAssignOp)
	checkerFactories["unslice"] = simple(checkUnslice)
	checkerFactories["newDeref"] = simple(checkNewDeref)
	checkerFactories["switchTrue"] = simple(checkSwitchTrue)
	checkerFactories["singleCaseSwitch"] = simple(checkSingleCaseSwitch)
}

// assignOp -------------------------------------------------------------

var assignOps = map[token.Token]bool{
	token.ADD: true, token.SUB: true, token.MUL: true, token.QUO: true,
	token.REM: true, token.AND: true, token.OR: true, token.XOR: true,
	token.AND_NOT: true, token.SHL: true, token.SHR: true,
}

func exprHasCall(expr ast.Expr) bool {
	found := false
	ast.Inspect(expr, func(n ast.Node) bool {
		if _, ok := n.(*ast.CallExpr); ok {
			found = true
			return false
		}
		return true
	})
	return found
}

func isIntOne(expr ast.Expr) bool {
	lit, ok := expr.(*ast.BasicLit)
	if !ok || lit.Kind != token.INT {
		return false
	}
	// Accept 01, 0x1, 1i? INT tokens here are integer literals.
	v, err := strconv.ParseInt(lit.Value, 0, 64)
	if err == nil {
		return v == 1
	}
	u, err := strconv.ParseUint(lit.Value, 0, 64)
	return err == nil && u == 1
}

func checkAssignOp(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		stmt, ok := n.(*ast.AssignStmt)
		if !ok || stmt.Tok != token.ASSIGN || len(stmt.Lhs) != 1 || len(stmt.Rhs) != 1 {
			return true
		}
		bin, ok := stmt.Rhs[0].(*ast.BinaryExpr)
		if !ok || !assignOps[bin.Op] {
			return true
		}
		lhs := stmt.Lhs[0]
		if exprHasCall(lhs) || !exprEqual(lhs, bin.X) {
			return true
		}
		lhsText := ctx.nodeText(lhs)
		var repl string
		if isIntOne(bin.Y) && (bin.Op == token.ADD || bin.Op == token.SUB) {
			suffix := "++"
			if bin.Op == token.SUB {
				suffix = "--"
			}
			repl = lhsText + suffix
		} else {
			repl = lhsText + " " + bin.Op.String() + "= " + ctx.nodeText(bin.Y)
		}
		ctx.warn(stmt, "replace `%s` with `%s`", ctx.nodeText(stmt), repl)
		return true
	})
}

// unslice --------------------------------------------------------------

func checkUnslice(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		sl, ok := n.(*ast.SliceExpr)
		if !ok || sl.Low != nil || sl.High != nil || sl.Max != nil || sl.Slice3 {
			return true
		}
		t := ctx.typeOf(sl.X)
		isUnsliceable := false
		switch tt := t.(type) {
		case *types.Slice:
			isUnsliceable = true
		case *types.Basic:
			isUnsliceable = tt.Kind() == types.String
		}
		if !isUnsliceable {
			return true
		}
		ctx.warn(sl, "could simplify %s to %s", ctx.nodeText(sl), ctx.nodeText(sl.X))
		return true
	})
}

// newDeref -------------------------------------------------------------

const panicStringMethod = "%!s(PANIC=String method: runtime error: invalid memory address or nil pointer dereference)"

// zeroValueString returns the suggested literal for *new(T).
// ok=false means the checker stays silent for this type (chan/func).
func zeroValueString(ctx *runCtx, typeExpr ast.Expr) (string, bool) {
	t := ctx.typeOf(typeExpr)
	typeText := ctx.prettyText(typeExpr)
	if t == nil {
		return panicStringMethod, true
	}
	switch u := t.Underlying().(type) {
	case *types.Basic:
		kindName := ""
		if id, ok := unwrapParen(typeExpr).(*ast.Ident); ok {
			kindName = id.Name
		}
		switch u.Kind() {
		case types.Bool:
			if kindName == "bool" {
				return "false", true
			}
			return typeText + "(false)", true
		case types.String:
			if kindName == "string" {
				return `""`, true
			}
			return typeText + `("")`, true
		case types.Int:
			if kindName == "int" {
				return "0", true
			}
			return typeText + "(0)", true
		case types.Float64:
			if kindName == "float64" {
				return "0.0", true
			}
			return typeText + "(0.0)", true
		default:
			info := u.Info()
			if info&types.IsInteger != 0 {
				return typeText + "(0)", true
			}
			if info&types.IsFloat != 0 {
				return typeText + "(0.0)", true
			}
			return panicStringMethod, true
		}
	case *types.Slice, *types.Map, *types.Interface:
		return conversionText(typeText, "nil"), true
	case *types.Pointer:
		return conversionText(typeText, "nil"), true
	case *types.Struct, *types.Array:
		return typeText + "{}", true
	case *types.Chan, *types.Signature:
		return "", false
	default:
		return panicStringMethod, true
	}
}

func conversionText(typeText, arg string) string {
	if strings.HasPrefix(typeText, "*") {
		return "(" + typeText + ")(" + arg + ")"
	}
	return typeText + "(" + arg + ")"
}

func checkNewDeref(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		star, ok := n.(*ast.StarExpr)
		if !ok {
			return true
		}
		call, ok := star.X.(*ast.CallExpr)
		if !ok || identName(call.Fun) != "new" {
			return true
		}
		// Deliberately index Args directly: the reference does the
		// same and panics on a (type-incorrect) empty new() call.
		arg := call.Args[0]
		if sug, ok := zeroValueString(ctx, arg); ok {
			ctx.warn(star, "replace `%s` with `%s`", ctx.prettyText(star), sug)
		}
		return true
	})
}

// switchTrue -----------------------------------------------------------

func checkSwitchTrue(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		stmt, ok := n.(*ast.SwitchStmt)
		if !ok {
			return true
		}
		if stmt.Tag != nil {
			if id, ok := stmt.Tag.(*ast.Ident); ok && id.Name == "true" {
				ctx.warn(stmt, "replace 'switch true {}' with 'switch {}'")
			}
		}
		return true
	})
}

func checkSingleCaseSwitch(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		stmt, ok := n.(*ast.SwitchStmt)
		if !ok || stmt.Body == nil || len(stmt.Body.List) != 1 {
			return true
		}
		clause, ok := stmt.Body.List[0].(*ast.CaseClause)
		if !ok {
			return true
		}
		if len(clause.List) == 0 {
			ctx.warn(stmt, "found switch with default case only")
		} else {
			ctx.warn(stmt, "should rewrite switch statement to if statement")
		}
		return true
	})
}
