package main

import (
	"go/ast"
	"go/token"
)

func init() {
	checkerFactories["elseif"] = func(p *checkerParams) checkerInstance {
		return funcChecker{fn: func(ctx *runCtx, file *ast.File) { checkElseif(ctx, file, p) }}
	}
	checkerFactories["defaultCaseOrder"] = simple(checkDefaultCaseOrder)
	checkerFactories["valSwap"] = simple(checkValSwap)
	checkerFactories["typeSwitchVar"] = simple(checkTypeSwitchVar)
	checkerFactories["unlambda"] = simple(checkUnlambda)
}

func checkElseif(ctx *runCtx, file *ast.File, p *checkerParams) {
	ast.Inspect(file, func(n ast.Node) bool {
		stmt, ok := n.(*ast.IfStmt)
		if !ok {
			return true
		}
		elseBlock, ok := stmt.Else.(*ast.BlockStmt)
		if !ok || len(elseBlock.List) != 1 {
			return true
		}
		inner, ok := elseBlock.List[0].(*ast.IfStmt)
		if !ok || inner.Else != nil {
			return true
		}
		if p.elseifSkipBalanced && stmt.Body != nil && len(stmt.Body.List) == 1 {
			if _, balanced := stmt.Body.List[0].(*ast.IfStmt); balanced {
				return true
			}
		}
		ctx.warn(elseBlock, "can replace 'else {if cond {}}' with 'else if cond {}'")
		return true
	})
}

func checkDefaultCaseOrder(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		stmt, ok := n.(*ast.SwitchStmt)
		if !ok || stmt.Body == nil {
			return true
		}
		for i, item := range stmt.Body.List {
			clause, ok := item.(*ast.CaseClause)
			if !ok || len(clause.List) != 0 {
				continue
			}
			if i != 0 && i != len(stmt.Body.List)-1 {
				ctx.warn(clause, "consider to make `default` case as first or as last case")
			}
		}
		return true
	})
}

func checkValSwap(ctx *runCtx, file *ast.File) {
	checkList := func(list []ast.Stmt) {
		for i := 0; i+2 < len(list); i++ {
			first, ok1 := list[i].(*ast.AssignStmt)
			second, ok2 := list[i+1].(*ast.AssignStmt)
			third, ok3 := list[i+2].(*ast.AssignStmt)
			if !ok1 || !ok2 || !ok3 {
				continue
			}
			if first.Tok != token.DEFINE || second.Tok != token.ASSIGN || third.Tok != token.ASSIGN {
				continue
			}
			if len(first.Lhs) != 1 || len(first.Rhs) != 1 || len(second.Lhs) != 1 || len(second.Rhs) != 1 || len(third.Lhs) != 1 || len(third.Rhs) != 1 {
				continue
			}
			tmpIdent, ok := first.Lhs[0].(*ast.Ident)
			if !ok {
				continue
			}
			_ = tmpIdent
			// tmp := a ; a = b ; b = tmp
			if !exprEqual(first.Rhs[0], second.Lhs[0]) {
				continue
			}
			if !exprEqual(second.Rhs[0], third.Lhs[0]) {
				continue
			}
			if !exprEqual(third.Rhs[0], first.Lhs[0]) {
				continue
			}
			aText := ctx.nodeText(second.Lhs[0])
			bText := ctx.nodeText(second.Rhs[0])
			ctx.warn(first, "can re-write as `%s, %s = %s, %s`", aText, bText, bText, aText)
		}
	}
	ast.Inspect(file, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.BlockStmt:
			checkList(node.List)
		case *ast.CaseClause:
			checkList(node.Body)
		case *ast.CommClause:
			checkList(node.Body)
		}
		return true
	})
}

func checkTypeSwitchVar(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		stmt, ok := n.(*ast.TypeSwitchStmt)
		if !ok || stmt.Body == nil {
			return true
		}
		exprStmt, ok := stmt.Assign.(*ast.ExprStmt)
		if !ok {
			return true
		}
		assert, ok := exprStmt.X.(*ast.TypeAssertExpr)
		if !ok || assert.Type != nil {
			return true
		}
		target := assert.X
		count := 0
		for _, item := range stmt.Body.List {
			clause, ok := item.(*ast.CaseClause)
			if !ok || len(clause.List) != 1 {
				continue
			}
			caseType := clause.List[0]
			found := false
			for _, bodyStmt := range clause.Body {
				ast.Inspect(bodyStmt, func(inner ast.Node) bool {
					if found {
						return false
					}
					ta, ok := inner.(*ast.TypeAssertExpr)
					if ok && ta.Type != nil && exprEqual(ta.X, target) && exprEqual(ta.Type, caseType) {
						found = true
						return false
					}
					return true
				})
				if found {
					break
				}
			}
			if found {
				count++
			}
		}
		if count == 1 {
			ctx.warn(stmt, "1 case can benefit from type switch with assignment")
		} else if count > 1 {
			ctx.warn(stmt, "%d cases can benefit from type switch with assignment", count)
		}
		return true
	})
}

func checkUnlambda(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		lit, ok := n.(*ast.FuncLit)
		if !ok || lit.Body == nil || len(lit.Body.List) != 1 {
			return true
		}
		ret, ok := lit.Body.List[0].(*ast.ReturnStmt)
		if !ok || len(ret.Results) != 1 {
			return true
		}
		call, ok := ret.Results[0].(*ast.CallExpr)
		if !ok {
			return true
		}
		// Callee: identifier or selector on an identifier.
		switch fun := call.Fun.(type) {
		case *ast.Ident:
		case *ast.SelectorExpr:
			if _, ok := fun.X.(*ast.Ident); !ok {
				return true
			}
		default:
			return true
		}
		// Collect parameter names.
		if lit.Type == nil || lit.Type.Params == nil {
			return true
		}
		type paramInfo struct {
			name     string
			variadic bool
		}
		var params []paramInfo
		for _, field := range lit.Type.Params.List {
			_, isEllipsis := field.Type.(*ast.Ellipsis)
			for _, name := range field.Names {
				params = append(params, paramInfo{name.Name, isEllipsis})
			}
			if len(field.Names) == 0 {
				return true
			}
		}
		if len(call.Args) != len(params) {
			return true
		}
		for i, arg := range call.Args {
			id, ok := arg.(*ast.Ident)
			if !ok || id.Name != params[i].name {
				return true
			}
		}
		isVariadicCall := call.Ellipsis.IsValid()
		if len(params) > 0 {
			if params[len(params)-1].variadic != isVariadicCall {
				return true
			}
		} else if isVariadicCall {
			return true
		}
		ctx.warn(lit, "replace `%s` with `%s`", ctx.prettyText(lit), ctx.prettyText(call.Fun))
		return true
	})
}
