func checkTypeSwitchVar(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		stmt, ok := n.(*ast.TypeSwitchStmt)
		if !ok || stmt.Body == nil {
			return true
		}
		exprStmt, ok := stmt.Assign.(*ast.ExprStmt)
		if !ok {
			return true
		}
		assert, ok := exprStmt.X.(*ast.TypeAssertExpr)
		if !ok || assert.Type != nil {
			return true
		}
		target := assert.X
		count := 0
		for _, item := range stmt.Body.List {
			clause, ok := item.(*ast.CaseClause)
			if !ok || len(clause.List) != 1 {
				continue
			}
			caseType := clause.List[0]
			found := false
			for _, bodyStmt := range clause.Body {
				ast.Inspect(bodyStmt, func(inner ast.Node) bool {
					if found {
						return false
					}
					ta, ok := inner.(*ast.TypeAssertExpr)
					if ok && ta.Type != nil && exprEqual(ta.X, target) && exprEqual(ta.Type, caseType) {
						found = true
						return false
					}
					return true
				})
				if found {
					break
				}
			}
			if found {
				count++
			}
		}
		if count == 1 {
			ctx.warn(stmt, "1 case can benefit from type switch with assignment")
		} else if count > 1 {
			ctx.warn(stmt, "%d cases can benefit from type switch with assignment", count)
		}
		return true
	})
}

func checkUnlambda(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		lit, ok := n.(*ast.FuncLit)
		if !ok || lit.Body == nil || len(lit.Body.List) != 1 {
			return true
		}
		ret, ok := lit.Body.List[0].(*ast.ReturnStmt)
		if !ok || len(ret.Results) != 1 {
			return true
		}
		call, ok := ret.Results[0].(*ast.CallExpr)
		if !ok {
			return true
		}
		// Callee: identifier or selector on an identifier.
		switch fun := call.Fun.(type) {
		case *ast.Ident:
		case *ast.SelectorExpr:
			if _, ok := fun.X.(*ast.Ident); !ok {
				return true
			}
		default:
			return true
		}
		// Collect parameter names.
		if lit.Type == nil || lit.Type.Params == nil {
			return true
		}
		type paramInfo struct {
			name     string
			variadic bool
		}
		var params []paramInfo
		for _, field := range lit.Type.Params.List {
			_, isEllipsis := field.Type.(*ast.Ellipsis)
			for _, name := range field.Names {
				params = append(params, paramInfo{name.Name, isEllipsis})
			}
			if len(field.Names) == 0 {
				return true
			}
		}
		if len(call.Args) != len(params) {
			return true
		}
		for i, arg := range call.Args {
			id, ok := arg.(*ast.Ident)
			if !ok || id.Name != params[i].name {
				return true
			}
		}
		isVariadicCall := call.Ellipsis.IsValid()
		if len(params) > 0 {
			if params[len(params)-1].variadic != isVariadicCall {
				return true
			}
		} else if isVariadicCall {
			return true
		}
		ctx.warn(lit, "replace `%s` with `%s`", ctx.prettyText(lit), ctx.prettyText(call.Fun))
		return true
	})
}
