{"command":"cat > checkers_comments.go <<'EOF'
package main

import (
	"go/ast"
	"go/token"
	"strings"
	"unicode"
)

func init() {
	checkerFactories["captLocal"] = func(p *checkerParams) checkerInstance {
		return funcChecker{fn: func(ctx *runCtx, file *ast.File) { checkCaptLocal(ctx, file, p) }}
	}
	checkerFactories["commentFormatting"] = simple(checkCommentFormatting)
	checkerFactories["deprecatedComment"] = simple(checkDeprecatedComment)
	checkerFactories["codegenComment"] = simple(checkCodegenComment)
}

// captLocal ------------------------------------------------------------

func isCapitalizedName(name string) bool {
	for _, r := range name {
		return unicode.IsUpper(r)
	}
	return false
}

func checkFieldNamesCapt(ctx *runCtx, fields *ast.FieldList) {
	if fields == nil {
		return
	}
	for _, field := range fields.List {
		for _, name := range field.Names {
			if isCapitalizedName(name.Name) {
				ctx.warn(name, "`%s' should not be capitalized", name.Name)
			}
		}
	}
}

func checkCaptLocal(ctx *runCtx, file *ast.File, p *checkerParams) {
	for _, decl := range file.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		if fn.Type != nil {
			checkFieldNamesCapt(ctx, fn.Type.Params)
			checkFieldNamesCapt(ctx, fn.Type.Results)
		}
		checkFieldNamesCapt(ctx, fn.Recv)
		if p.captLocalParamsOnly || fn.Body == nil {
			continue
		}
		ast.Inspect(fn.Body, func(n ast.Node) bool {
			switch node := n.(type) {
			case *ast.FuncLit:
				// The reference checker does not descend into
				// nested function literals.
				return false
			case *ast.TypeSwitchStmt:
				// Inspect Init and Body, but not the type-switch
				// guard assignment.
				if node.Init != nil {
					ast.Inspect(node.Init, func(m ast.Node) bool {
						checkCaptLocalNode(ctx, m)
						return true
					})
				}
				if node.Body != nil {
					ast.Inspect(node.Body, func(m ast.Node) bool {
						if _, isLit := m.(*ast.FuncLit); isLit {
							return false
						}
						checkCaptLocalNode(ctx, m)
						return true
					})
				}
				return false
			default:
				checkCaptLocalNode(ctx, n)
				return true
			}
		})
	}
}

func checkCaptLocalNode(ctx *runCtx, n ast.Node) {
	switch node := n.(type) {
	case *ast.AssignStmt:
		if node.Tok == token.DEFINE {
			for _, lhs := range node.Lhs {
				if id, ok := lhs.(*ast.Ident); ok && isCapitalizedName(id.Name) {
					ctx.warn(id, "`%s' should not be capitalized", id.Name)
				}
			}
		}
	case *ast.ValueSpec:
		for _, name := range node.Names {
			if isCapitalizedName(name.Name) {
				ctx.warn(name, "`%s' should not be capitalized", name.Name)
			}
		}
	}
}

// commentFormatting ----------------------------------------------------

func commentFormattingBad(text string) bool {
	if !strings.HasPrefix(text, "//") {
		return false
	}
	s := text[2:]
	if len(s) < 2 {
		return false
	}
	switch s[0] {
	case ' ', '\t', '/', '-', '+', '!', '#':
		return false
	}
	// A word followed by ':' (directive / label style comments).
	if idx := strings.IndexByte(s, ':'); idx > 0 {
		word := s[:idx]
		isWord := true
		for i := 0; i < len(word); i++ {
			c := word[i]
			if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_' || c == '-') {
				isWord = false
				break
			}
		}
		if isWord {
			return false
		}
	}
	lower := strings.ToLower(s)
	if strings.HasPrefix(lower, "nolint") {
		return false
	}
	if strings.HasPrefix(s, "export ") {
		return false
	}
	if strings.HasPrefix(s, "line ") {
		// Be permissive for a well-formed //line directive: the
		// remainder contains a ':'.
		if strings.Contains(s[len("line "):], ":") {
			return false
		}
	}
	return true
}

func checkCommentFormatting(ctx *runCtx, file *ast.File) {
	for _, group := range file.Comments {
		for _, comment := range group.List {
			if commentFormattingBad(comment.Text) {
				ctx.warnAt(comment.Slash, "put a space between `//` and comment text")
				break
			}
		}
	}
}

// deprecatedComment ----------------------------------------------------

func deprecatedBadLine(text string) (string, bool) {
	if !strings.HasPrefix(text, "//") {
		return "", false
	}
	s := strings.TrimSpace(text[2:])
	const commaPrefix = "Deprecated, "
	if strings.HasPrefix(s, commaPrefix) {
		return "use `:` instead of `,` in `Deprecated, `", true
	}
	const colonPrefix = "deprecated: "
	if len(s) > len(colonPrefix) && strings.EqualFold(s[:len(colonPrefix)], colonPrefix) {
		if s[:len(colonPrefix)] != "Deprecated: " {
			return "use `Deprecated: ` (note the casing) instead of `" + s[:len(colonPrefix)] + "`", true
		}
		return "", false
	}
	lower := strings.ToLower(s)
	for _, prefix := range []string{
		"deprecated use",
		"deprecated. use",
		"deprecated! use",
		"deprecated in",
	} {
		if strings.HasPrefix(lower, prefix) {
			return "the proper format is `Deprecated: <text>`", true
		}
	}
	return "", false
}

func checkDeprecatedComment(ctx *runCtx, file *ast.File) {
	var docs []*ast.CommentGroup
	seen := make(map[*ast.CommentGroup]bool)
	add := func(g *ast.CommentGroup) {
		if g != nil && !seen[g] {
			seen[g] = true
			docs = append(docs, g)
		}
	}
	ast.Inspect(file, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.FuncDecl:
			add(node.Doc)
		case *ast.GenDecl:
			add(node.Doc)
		case *ast.ImportSpec:
			add(node.Doc)
		case *ast.ValueSpec:
			add(node.Doc)
		case *ast.TypeSpec:
			add(node.Doc)
		case *ast.Field:
			add(node.Doc)
		}
		return true
	})
	// ast.Inspect visits declarations in source order, and the docs
	// are collected in that order.
	for _, group := range docs {
		for _, comment := range group.List {
			if msg, bad := deprecatedBadLine(comment.Text); bad {
				ctx.warnAt(comment.Slash, "%s", msg)
				break
			}
		}
	}
}

// codegenComment -------------------------------------------------------

var codegenSuspiciousPhrases []string

func init() {
	for _, noun := range []string{"file", "code"} {
		for _, verb := range []string{"was", "is"} {
