// appendAssign ---------------------------------------------------------

func appendSliceBase(expr ast.Expr) ast.Expr {
	for {
		if sl, ok := expr.(*ast.SliceExpr); ok {
			expr = sl.X
			continue
		}
		return expr
	}
}

func isAppendSliceArg(expr ast.Expr) bool {
	switch appendSliceBase(expr).(type) {
	case *ast.Ident, *ast.SelectorExpr, *ast.IndexExpr, *ast.IndexListExpr:
		return true
	}
	return false
}

func checkAppendAssign(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		stmt, ok := n.(*ast.AssignStmt)
		if !ok {
			return true
		}
		for i, rhs := range stmt.Rhs {
			if i >= len(stmt.Lhs) {
				break
			}
			call, ok := rhs.(*ast.CallExpr)
			if !ok || identName(call.Fun) != "append" {
				continue
			}
			lhs := stmt.Lhs[i]
			if id, ok := lhs.(*ast.Ident); ok && id.Name == "_" {
				continue
			}
			// As in the reference, this index is unchecked.
			first := call.Args[0]
			if !isAppendSliceArg(first) {
				continue
			}
			if exprEqual(lhs, appendSliceBase(first)) {
				continue
			}
			// Appending the assigned slice itself (as the spread
			// elements) is treated as an intentional use.
			usesLHS := false
			for _, arg := range call.Args[1:] {
				if exprEqual(lhs, arg) {
					usesLHS = true
					break
				}
			}
			if usesLHS {
				continue
			}
			ctx.warn(call, "append result not assigned to the same slice")
		}
		return true
	})
}

// argOrder -------------------------------------------------------------

var argOrderFuncs = map[string]bool{
	"Contains": true, "HasPrefix": true, "HasSuffix": true,
	"Split": true, "TrimPrefix": true, "TrimSuffix": true,
}

func isLiteralArg(expr ast.Expr) bool {
	switch e := expr.(type) {
	case *ast.BasicLit:
		return true
	case *ast.ParenExpr:
		return isLiteralArg(e.X)
	case *ast.BinaryExpr:
		return e.Op == token.ADD && isLiteralArg(e.X) && isLiteralArg(e.Y)
	case *ast.CompositeLit:
