package main

import (
	"go/ast"
	"go/token"
	"strings"
)

func init() {
	checkerFactories["dupArg"] = simple(checkDupArg)
	checkerFactories["dupSubExpr"] = simple(checkDupSubExpr)
	checkerFactories["dupBranchBody"] = simple(checkDupBranchBody)
	checkerFactories["dupCase"] = simple(checkDupCase)
}

// dupArg ---------------------------------------------------------------

var dupArgFuncs = map[string]map[string]bool{
	"strings": {
		"Compare": true, "Contains": true, "EqualFold": true, "HasPrefix": true,
		"HasSuffix": true, "Index": true, "LastIndex": true, "Replace": true,
		"ReplaceAll": true, "Split": true, "SplitAfter": true, "SplitAfterN": true, "SplitN": true,
	},
	"bytes": {
		"Compare": true, "Contains": true, "Equal": true, "EqualFold": true, "HasPrefix": true,
		"HasSuffix": true, "Index": true, "LastIndex": true, "Replace": true,
		"ReplaceAll": true, "Split": true, "SplitAfter": true, "SplitAfterN": true, "SplitN": true,
	},
	"math":    {"Max": true, "Min": true, "Dim": true},
	"reflect": {"DeepEqual": true},
	"cmp":     {"Compare": true},
	"slices":  {"Compare": true, "Equal": true},
	"maps":    {"Equal": true},
}

var dupArgMethods = map[string]bool{"Compare": true, "Cmp": true, "Equal": true, "Equals": true}

func checkDupArg(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) == 0 {
			return true
		}
		// Method call form: x.Compare(x), x.Equal(x), ...
		if sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr); ok && dupArgMethods[sel.Sel.Name] {
			if ctx.selectionOf(sel) != nil && exprEqual(sel.X, call.Args[0]) {
				ctx.warn(call, "suspicious method call with the same argument and receiver")
				return true
			}
		}
		isDupFunc := false
		if identName(call.Fun) == "copy" {
			isDupFunc = true
		} else if sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr); ok {
			if path, isImported := ctx.importedPkg(sel); isImported {
				if funcs, ok := dupArgFuncs[path]; ok && funcs[sel.Sel.Name] {
					isDupFunc = true
				}
			} else if ctx.info == nil {
				if funcs, ok := dupArgFuncs[identName(sel.X)]; ok && funcs[sel.Sel.Name] {
					isDupFunc = true
				}
			}
		}
		if !isDupFunc {
			return true
		}
		for i := 0; i+1 < len(call.Args); i++ {
			if exprEqual(call.Args[i], call.Args[i+1]) {
				ctx.warn(call, "suspicious duplicated args in %s", ctx.nodeText(call))
				break
			}
		}
		return true
	})
}

// dupSubExpr -----------------------------------------------------------

func isPureExpr(expr ast.Expr) bool {
	pure := true
	ast.Inspect(expr, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.CallExpr:
			pure = false
			return false
		case *ast.UnaryExpr:
			if node.Op == token.ARROW {
				pure = false
				return false
			}
		}
		return true
	})
	return pure
}

func checkDupSubExpr(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		switch bin.Op {
		case token.ADD, token.MUL, token.SHL, token.SHR:
			return true
		}
		if exprEqual(bin.X, bin.Y) && isPureExpr(bin.X) && isPureExpr(bin.Y) {
			ctx.warn(bin, "suspicious identical LHS and RHS for `%s` operator", bin.Op.String())
		}
		return true
	})
}

// dupBranchBody --------------------------------------------------------

func normalizeWS(s string) string {
	return strings.Join(strings.Fields(s), " ")
}

func checkDupBranchBody(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		stmt, ok := n.(*ast.IfStmt)
		if !ok || stmt.Body == nil {
			return true
		}
		elseBlock, ok := stmt.Else.(*ast.BlockStmt)
		if !ok {
			return true
		}
		if normalizeWS(ctx.prettyText(stmt.Body)) == normalizeWS(ctx.prettyText(elseBlock)) {
			ctx.warn(stmt, "both branches in if statement have same body")
		}
		return true
	})
}

// dupCase --------------------------------------------------------------

func checkDupCase(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.SwitchStmt:
			if node.Body == nil {
				return true
			}
