func init() {
	checkerFactories["regexpMust"] = simple(checkRegexpMust)
	checkerFactories["sloppyLen"] = simple(checkSloppyLen)
	checkerFactories["sloppyTypeAssert"] = simple(checkSloppyTypeAssert)
	checkerFactories["wrapperFunc"] = simple(checkWrapperFunc)
