func checkRegexpMust(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) != 1 {
			return true
		}
		sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
		if !ok || (sel.Sel.Name != "Compile" && sel.Sel.Name != "CompilePOSIX") {
			return true
		}
		if path, imported := ctx.importedPkg(sel); imported {
			if path != "regexp" {
				return true
			}
		} else if identName(sel.X) != "regexp" {
			return true
		}
		if ctx.isConstantExpr(call.Args[0]) {
			suffix := "Compile"
			if sel.Sel.Name == "CompilePOSIX" {
				suffix = "CompilePOSIX"
			}
			ctx.warn(call, "for const patterns like %s, use regexp.Must%s", ctx.nodeText(call.Args[0]), suffix)
		}
		return true
	})
}

func isZeroBasicLit(expr ast.Expr) bool {
	lit, ok := expr.(*ast.BasicLit)
	if !ok || lit.Kind != token.INT {
		return false
	}
	v := constant.MakeFromLiteral(lit.Value, lit.Kind, 0)
	if v.Kind() == constant.Unknown {
		return false
	}
	return constant.Compare(v, token.EQL, constant.MakeInt64(0))
}

func checkSloppyLen(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		call, ok := bin.X.(*ast.CallExpr)
		if !ok || identName(call.Fun) != "len" || !isZeroBasicLit(bin.Y) {
			return true
		}
		text := ctx.nodeText(bin)
		switch bin.Op {
		case token.GEQ:
			ctx.warn(bin, "%s is always true", text)
		case token.LSS:
			ctx.warn(bin, "%s is always false", text)
		case token.LEQ:
