var flagFuncTypes = []string{"Bool", "Int", "Int64", "Uint", "Uint64", "String", "Float64", "Duration"}

func init() {
	checkerFactories["flagDeref"] = simple(checkFlagDeref)
	checkerFactories["flagName"] = simple(checkFlagName)
}

func isFlagFunc(ctx *runCtx, sel *ast.SelectorExpr) bool {
	if path, imported := ctx.importedPkg(sel); imported {
		return path == "flag"
	}
	return identName(sel.X) == "flag" && ctx.info == nil
}

func checkFlagDeref(ctx *runCtx, file *ast.File) {
	known := make(map[string]bool, len(flagFuncTypes))
	for _, name := range flagFuncTypes {
		known[name] = true
	}
	ast.Inspect(file, func(n ast.Node) bool {
		star, ok := n.(*ast.StarExpr)
		if !ok {
			return true
		}
		call, ok := star.X.(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
		if !ok || !known[sel.Sel.Name] || !isFlagFunc(ctx, sel) {
			return true
		}
		ctx.warn(star, "immediate deref in %s is most likely an error; consider using flag.%sVar", ctx.nodeText(star), sel.Sel.Name)
		return true
	})
}

