			if sel.Sel.Name == base {
				nameArgIndex = 0
				break
			}
			if sel.Sel.Name == base+"Var" {
				nameArgIndex = 1
				break
			}
		}
		if nameArgIndex < 0 || len(call.Args) <= nameArgIndex {
			return true
		}
