cat > checkers_misc2.go <<'EOF'
package main

import (
	"go/ast"
	"go/constant"
	"go/token"
	"go/types"
	"strconv"
	"strings"
)

func init() {
	checkerFactories["caseOrder"] = simple(checkCaseOrder)
	checkerFactories["mapKey"] = simple(checkMapKey)
	checkerFactories["offBy1"] = simple(checkOffBy1)
	checkerFactories["badCond"] = simple(checkBadCond)
	checkerFactories["badCall"] = simple(checkBadCall)
	checkerFactories["exitAfterDefer"] = simple(checkExitAfterDefer)
	checkerFactories["ifElseChain"] = func(p *checkerParams) checkerInstance {
		return funcChecker{fn: func(ctx *runCtx, file *ast.File) { checkIfElseChain(ctx, file, p) }}
	}
}

// caseOrder ------------------------------------------------------------

func implementsSafely(t types.Type, iface *types.Interface) (ok bool) {
	defer func() { _ = recover() }()
	return types.Implements(t, iface)
}

func checkCaseOrder(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		stmt, ok := n.(*ast.TypeSwitchStmt)
		if !ok || stmt.Body == nil {
			return true
		}
		type earlier struct {
			expr ast.Expr
			typ  types.Type
		}
		var prev []earlier
		for _, item := range stmt.Body.List {
			clause, ok := item.(*ast.CaseClause)
			if !ok {
				continue
			}
			for _, typeExpr := range clause.List {
				currentType := ctx.typeOf(typeExpr)
				if currentType != nil {
					for _, p := range prev {
						if p.typ == nil {
							continue
						}
						iface, isIface := p.typ.Underlying().(*types.Interface)
						if !isIface {
							continue
						}
						if implementsSafely(currentType, iface) {
							ctx.warn(typeExpr, "case %s must go before the %s case", ctx.nodeText(typeExpr), ctx.nodeText(p.expr))
							break
						}
					}
				}
				prev = append(prev, earlier{typeExpr, currentType})
			}
		}
		return true
	})
}

// mapKey ---------------------------------------------------------------

func checkMapKey(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		lit, ok := n.(*ast.CompositeLit)
		if !ok || len(lit.Elts) < 2 {
			return true
		}
		// Map key type must be (underlying) string.
		isStringMap := false
		if t := ctx.typeOf(lit); t != nil {
			if m, ok := t.Underlying().(*types.Map); ok {
				if b, ok := m.Key().Underlying().(*types.Basic); ok && b.Kind() == types.String {
					isStringMap = true
				}
			}
		} else if mt, ok := lit.Type.(*ast.MapType); ok && identName(mt.Key) == "string" {
			isStringMap = true
		}
		if !isStringMap {
			return true
		}
		type keyInfo struct {
			expr  ast.Expr
			value string
		}
		var spaceKeys []keyInfo
		for _, elt := range lit.Elts {
			kv, ok := elt.(*ast.KeyValueExpr)
			if !ok {
				continue
			}
			litKey, ok := kv.Key.(*ast.BasicLit)
			if !ok || litKey.Kind != token.STRING {
				continue
			}
			value, err := strconv.Unquote(litKey.Value)
			if err != nil {
				continue
			}
			if strings.Contains(value, " ") {
				spaceKeys = append(spaceKeys, keyInfo{kv.Key, value})
			}
		}
		if len(spaceKeys) != 1 {
			return true
		}
		k := spaceKeys[0]
		if (strings.HasPrefix(k.value, " ") || strings.HasSuffix(k.value, " ")) && strings.Trim(k.value, " ") != "" {
			ctx.warn(k.expr, "suspicious whitespace in %s key", ctx.nodeText(k.expr))
		}
		return true
	})
}

// offBy1 ---------------------------------------------------------------

func checkOffBy1(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		idx, ok := n.(*ast.IndexExpr)
		if !ok {
			return true
		}
		if _, isSlice := ctx.typeOf(idx.X).(*types.Slice); !isSlice {
			return true
		}
		call, ok := idx.Index.(*ast.CallExpr)
		if !ok || identName(call.Fun) != "len" || len(call.Args) != 1 {
			return true
		}
		if exprEqual(idx.X, call.Args[0]) {
			text := ctx.nodeText(idx.X)
			ctx.warn(idx, "index expr always panics; maybe you wanted %s[len(%s)-1]?", text, text)
		}
		return true
	})
}

// badCond --------------------------------------------------------------

func initAssignsZeroTo(ctx *runCtx, init ast.Stmt, id *ast.Ident) bool {
	assign, ok := init.(*ast.AssignStmt)
	if !ok || len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
		return false
	}
	lhs, ok := assign.Lhs[0].(*ast.Ident)
	if !ok || lhs.Name != id.Name {
		return false
	}
	return isZeroBasicLit(assign.Rhs[0])
}

func checkBadCond(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		loop, ok := n.(*ast.ForStmt)
		if !ok || loop.Init == nil || loop.Cond == nil || loop.Post == nil {
			return true
		}
		inc, ok := loop.Post.(*ast.IncDecStmt)
		if !ok || inc.Tok != token.INC {
			return true
		}
		bin, ok := loop.Cond.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		// Either i > bound or bound < i.
		var ident *ast.Ident
		var opposite token.Token
		if bin.Op == token.GTR {
			if id, ok := bin.X.(*ast.Ident); ok {
				ident, opposite = id, token.LSS
			}
		} else if bin.Op == token.LSS {
			if id, ok := bin.Y.(*ast.Ident); ok {
				ident, opposite = id, token.GTR
			}
		}
		if ident == nil || !initAssignsZeroTo(ctx, loop.Init, ident) {
			return true
		}
		xText := ctx.nodeText(bin.X)
		yText := ctx.nodeText(bin.Y)
		ctx.warn(loop, "`%s` in loop; probably meant `%s %s %s`?", ctx.nodeText(bin), xText, opposite.String(), yText)
		return true
	})
}

// badCall --------------------------------------------------------------

func isConstZeroInt(ctx *runCtx, expr ast.Expr) bool {
	tv, ok := ctx.typeAndValueOf(expr)
	if !ok || tv.Value == nil || tv.Value.Kind() != constant.Int {
		return false
	}
	return constant.Sign(tv.Value) == 0
}

func checkBadCall(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		if identName(call.Fun) == "append" && len(call.Args) == 1 {
			ctx.warn(call, "no-op append call, probably missing arguments")
			return true
		}
		sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
		if !ok {
			return true
		}
		path, imported := ctx.importedPkg(sel)
		local := identName(sel.X)
		if imported {
			local = path
		}
		if local != "strings" && local != "bytes" {
			return true
		}
		var arg ast.Expr
		switch {
		case sel.Sel.Name == "Replace" && len(call.Args) == 4:
			arg = call.Args[3]
		case sel.Sel.Name == "SplitN" && len(call.Args) == 3:
			arg = call.Args[2]
		default:
			return true
		}
		if isConstZeroInt(ctx, arg) {
			ctx.warn(arg, "suspicious arg 0, probably meant -1")
		}
		return true
	})
}

// exitAfterDefer -------------------------------------------------------

func exitCallName(call *ast.CallExpr) string {
	sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
	if !ok {
