func checkIfElseChain(ctx *runCtx, file *ast.File, p *checkerParams) {
	// Mark if-statements that are the direct else-branch of another.
	elseIfs := make(map[*ast.IfStmt]bool)
	var roots []*ast.IfStmt
	ast.Inspect(file, func(n ast.Node) bool {
		if stmt, ok := n.(*ast.IfStmt); ok {
			roots = append(roots, stmt)
			if child, ok := stmt.Else.(*ast.IfStmt); ok {
				elseIfs[child] = true
			}
		}
		return true
	})
	for _, root := range roots {
		if elseIfs[root] {
			continue
		}
		count := 0
		for cur := root; cur.Else != nil; {
			count++
			if child, ok := cur.Else.(*ast.IfStmt); ok {
				cur = child
				continue
			}
			break
		}
		if count >= p.ifElseChainMinThreshold {
			ctx.warn(root, "rewrite if-else to switch statement")
		}
	}
