package main

import (
	"go/ast"
	"go/types"
)

func init() {
	checkerFactories["underef"] = func(p *checkerParams) checkerInstance {
		return funcChecker{fn: func(ctx *runCtx, file *ast.File) { checkUnderef(ctx, file, p) }}
	}
}

func derefParen(expr ast.Expr) (*ast.StarExpr, bool) {
	paren, ok := expr.(*ast.ParenExpr)
	if !ok {
		return nil, false
	}
	star, ok := paren.X.(*ast.StarExpr)
	return star, ok
}

func selectorBaseText(ctx *runCtx, expr ast.Expr) string {
	text := ctx.nodeText(expr)
	if _, isStar := expr.(*ast.StarExpr); isStar {
		return "(" + text + ")"
	}
	return text
}

func isPointerToNonPointer(t types.Type) bool {
	ptr, ok := t.(*types.Pointer)
	if !ok {
		return false
	}
	_, elemIsPtr := ptr.Elem().(*types.Pointer)
	return !elemIsPtr
}

func checkUnderef(ctx *runCtx, file *ast.File, p *checkerParams) {
	ast.Inspect(file, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.SelectorExpr:
			star, ok := derefParen(node.X)
			if !ok {
				return true
			}
			if !isPointerToNonPointer(ctx.typeOf(star.X)) {
				return true
			}
			if selInfo := ctx.selectionOf(node); selInfo != nil {
				if fn, ok := selInfo.Obj().(*types.Func); ok && p.underefSkipRecvDeref {
					if sig, ok := fn.Type().(*types.Signature); ok && sig.Recv() != nil {
						if _, recvIsPtr := sig.Recv().Type().(*types.Pointer); recvIsPtr {
							return true
						}
					}
				}
			} else {
				return true
			}
			ctx.warn(node, "could simplify %s to %s.%s", ctx.nodeText(node), selectorBaseText(ctx, star.X), node.Sel.Name)
		case *ast.IndexExpr:
			star, ok := derefParen(node.X)
			if !ok {
				return true
			}
			if _, isArray := ctx.typeOf(node.X).(*types.Array); !isArray {
				return true
			}
			ctx.warn(node, "could simplify %s to %s[%s]", ctx.nodeText(node), selectorBaseText(ctx, star.X), ctx.nodeText(node.Index))
		}
		return true
	})
}
