package main

import (
	"go/ast"
	"go/token"
	"go/types"
	"strings"
)

func init() {
	checkerFactories["appendCombine"] = simple(checkAppendCombine)
	checkerFactories["hugeParam"] = func(p *checkerParams) checkerInstance {
		return funcChecker{fn: func(ctx *runCtx, file *ast.File) { checkHugeParam(ctx, file, p) }}
	}
