	checkerFactories["rangeExprCopy"] = func(p *checkerParams) checkerInstance {
		return funcChecker{fn: func(ctx *runCtx, file *ast.File) { checkRangeExprCopy(ctx, file, p) }}
	}
	checkerFactories["rangeValCopy"] = func(p *checkerParams) checkerInstance {
		return funcChecker{fn: func(ctx *runCtx, file *ast.File) { checkRangeValCopy(ctx, file, p) }}
	}
