// zeroByteRepeat -------------------------------------------------------

func checkZeroByteRepeat(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) != 2 {
			return true
		}
		sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
		if !ok || sel.Sel.Name != "Repeat" {
			return true
		}
		if path, imported := ctx.importedPkg(sel); imported {
			if path != "bytes" {
				return true
			}
		} else if identName(sel.X) != "bytes" {
			return true
		}
		lit, ok := unwrapParen(call.Args[0]).(*ast.CompositeLit)
		if !ok || len(lit.Elts) != 1 {
			return true
		}
		elt := lit.Elts[0]
		if kv, ok := elt.(*ast.KeyValueExpr); ok {
			elt = kv.Value
		}
		if !isConstZeroInt(ctx, elt) {
			return true
		}
		countText := ctx.nodeText(call.Args[1])
		if basic, ok := elt.(*ast.BasicLit); ok && basic.Kind == token.INT {
			ctx.warn(call, "avoid bytes.Repeat([]byte{0}, %s); consider using make([]byte, %s) instead", countText, countText)
		} else {
			ctx.warn(call, "avoid bytes.Repeat with a const 0; use make([]byte, %s) instead", countText)
		}
		return true
	})
