// test functions -------------------------------------------------------

func isTestFuncDecl(ctx *runCtx, fn *ast.FuncDecl) bool {
	if fn.Recv != nil && len(fn.Recv.List) > 0 {
		return false
	}
	if !strings.HasPrefix(fn.Name.Name, "Test") || fn.Type == nil || fn.Type.Params == nil {
		return false
	}
	// Signature: exactly one parameter, of type *testing.T.
	obj := ctx.objectOf(fn.Name)
	if obj != nil {
		if sig, ok := obj.Type().(*types.Signature); ok {
			if sig.Params().Len() != 1 {
				return false
			}
			return namedTypeString(sig.Params().At(0).Type()) == "testing.T"
		}
	}
	// Fall back to source shape.
	if len(fn.Type.Params.List) != 1 || len(fn.Type.Params.List[0].Names) > 1 {
		return false
	}
	star, ok := fn.Type.Params.List[0].Type.(*ast.StarExpr)
	if !ok {
		return false
	}
	pkg, name, ok := selectorParts(star.X)
	return ok && pkg == "testing" && name == "T"
}

// rangeExprCopy / rangeValCopy ----------------------------------------

func checkRangeExprCopy(ctx *runCtx, file *ast.File, p *checkerParams) {
	// Process function declarations separately so test functions
	// can be skipped as a whole; ranges outside functions are
	// handled as well.
	var testBodies []*ast.BlockStmt
	if p.rangeExprCopySkipTestFuncs {
		for _, decl := range file.Decls {
			if fn, ok := decl.(*ast.FuncDecl); ok && isTestFuncDecl(ctx, fn) {
				testBodies = append(testBodies, fn.Body)
			}
		}
	}
	ast.Inspect(file, func(n ast.Node) bool {
		if body, ok := n.(*ast.BlockStmt); ok {
			for _, tb := range testBodies {
				if body == tb {
					return false
				}
			}
		}
		rng, ok := n.(*ast.RangeStmt)
		if !ok || rng.Value == nil {
			return true
		}
		t := ctx.typeOf(rng.X)
		if t == nil {
			return true
		}
		if _, isArray := t.Underlying().(*types.Array); !isArray {
			return true
		}
		if tv, ok := ctx.typeAndValueOf(rng.X); ok && !tv.Addressable() {
			return true
		}
		if size := sizeOf(ctx, t); size >= int64(p.rangeExprCopySizeThreshold) {
			text := ctx.nodeText(rng.X)
			ctx.warn(rng, "copy of %s (%d bytes) can be avoided with &%s", text, size, text)
		}
		return true
	})
}

func rangeValueElemType(ctx *runCtx, rng *ast.RangeStmt) types.Type {
	t := ctx.typeOf(rng.X)
	if t == nil {
		return nil
	}
	t = derefType(t)
	switch u := t.Underlying().(type) {
	case *types.Slice:
		return u.Elem()
	case *types.Array:
		return u.Elem()
	case *types.Map:
		return u.Elem()
	case *types.Basic:
		if u.Kind() == types.String {
			return types.Typ[types.Rune]
		}
		if u.Info()&types.IsInteger != 0 {
			return t
		}
	}
	return nil
}

func checkRangeValCopy(ctx *runCtx, file *ast.File, p *checkerParams) {
	var testBodies []*ast.BlockStmt
	if p.rangeValCopySkipTestFuncs {
		for _, decl := range file.Decls {
			if fn, ok := decl.(*ast.FuncDecl); ok && isTestFuncDecl(ctx, fn) {
				testBodies = append(testBodies, fn.Body)
			}
		}
	}
	ast.Inspect(file, func(n ast.Node) bool {
		if body, ok := n.(*ast.BlockStmt); ok {
			for _, tb := range testBodies {
				if body == tb {
					return false
				}
			}
		}
		rng, ok := n.(*ast.RangeStmt)
		if !ok || rng.Value == nil || rng.Tok != token.DEFINE {
			return true
		}
		var elemType types.Type
		if id, ok := rng.Value.(*ast.Ident); ok {
			if obj := ctx.objectOf(id); obj != nil {
				elemType = obj.Type()
			}
		}
		if elemType == nil {
			elemType = rangeValueElemType(ctx, rng)
		}
		if size := sizeOf(ctx, elemType); size >= int64(p.rangeValCopySizeThreshold) {
			ctx.warn(rng, "each iteration copies %d bytes (consider pointers or indexing)", size)
		}
		return true
	})
}
