// appendCombine --------------------------------------------------------

func appendAssignedLHS(stmt ast.Stmt) (ast.Expr, bool) {
	assign, ok := stmt.(*ast.AssignStmt)
	if !ok || assign.Tok != token.ASSIGN || len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
		return nil, false
	}
	call, ok := assign.Rhs[0].(*ast.CallExpr)
	if !ok || identName(call.Fun) != "append" || call.Ellipsis.IsValid() || len(call.Args) < 1 {
		return nil, false
	}
	if !exprEqual(assign.Lhs[0], call.Args[0]) {
		return nil, false
	}
	return assign.Lhs[0], true
}

func checkAppendCombine(ctx *runCtx, file *ast.File) {
	checkList := func(list []ast.Stmt) {
		for i := 0; i < len(list); {
			lhs, ok := appendAssignedLHS(list[i])
			if !ok {
				i++
				continue
			}
			j := i + 1
			for j < len(list) {
				lhs2, ok := appendAssignedLHS(list[j])
				if !ok || !exprEqual(lhs, lhs2) {
					break
				}
				j++
			}
			if j-i >= 2 {
				ctx.warn(list[i], "can combine chain of %d appends into one", j-i)
			}
			i = j
		}
	}
	ast.Inspect(file, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.BlockStmt:
			checkList(node.List)
		case *ast.CaseClause:
			checkList(node.Body)
		case *ast.CommClause:
			checkList(node.Body)
		}
		return true
	})
}

// hugeParam ------------------------------------------------------------

func checkHugeParam(ctx *runCtx, file *ast.File, p *checkerParams) {
	checkFields := func(fields *ast.FieldList) {
		if fields == nil {
			return
		}
		for _, field := range fields.List {
			for _, name := range field.Names {
				var t types.Type
				if obj := ctx.objectOf(name); obj != nil {
					t = obj.Type()
				} else {
					t = ctx.typeOf(field.Type)
				}
				if size := sizeOf(ctx, t); size >= int64(p.hugeParamSizeThreshold) {
					ctx.warn(name, "%s is heavy (%d bytes); consider passing it by pointer", name.Name, size)
				}
			}
		}
	}
	for _, decl := range file.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		checkFields(fn.Recv)
		if fn.Type != nil {
			checkFields(fn.Type.Params)
		}
	}
}

// conversions shared by indexAlloc/stringXbytes ----------------------

func stringConversion(expr ast.Expr) (ast.Expr, bool) {
	call, ok := unwrapParen(expr).(*ast.CallExpr)
	if !ok || len(call.Args) != 1 || identName(call.Fun) != "string" {
		return nil, false
	}
	return call.Args[0], true
}

func byteSliceConversion(expr ast.Expr) (ast.Expr, bool) {
	call, ok := unwrapParen(expr).(*ast.CallExpr)
	if !ok || len(call.Args) != 1 {
		return nil, false
	}
	arr, ok := unwrapParen(call.Fun).(*ast.ArrayType)
	if !ok || arr.Len != nil || identName(arr.Elt) != "byte" {
		return nil, false
	}
	return call.Args[0], true
}

func checkIndexAlloc(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) != 2 {
			return true
		}
		sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
		if !ok || sel.Sel.Name != "Index" {
			return true
		}
		if path, imported := ctx.importedPkg(sel); imported {
			if path != "strings" {
				return true
			}
		} else if identName(sel.X) != "strings" {
			return true
		}
		if inner, ok := stringConversion(call.Args[0]); ok {
			ctx.warn(call, "consider replacing %s with bytes.Index(%s, []byte(%s))", ctx.nodeText(call), ctx.nodeText(inner), ctx.nodeText(call.Args[1]))
		}
		return true
	})
}

func checkStringXbytes(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || identName(call.Fun) != "copy" || len(call.Args) != 2 {
			return true
		}
		if inner, ok := byteSliceConversion(call.Args[1]); ok {
			ctx.warn(call, "can simplify `%s` to `%s`", ctx.nodeText(call.Args[1]), ctx.nodeText(inner))
		}
		return true
	})
}

// zeroByteRepeat -------------------------------------------------------

func checkZeroByteRepeat(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) != 2 {
			return true
		}
		sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
		if !ok || sel.Sel.Name != "Repeat" {
			return true
		}
		if path, imported := ctx.importedPkg(sel); imported {
			if path != "bytes" {
				return true
			}
		} else if identName(sel.X) != "bytes" {
			return true
		}
		lit, ok := unwrapParen(call.Args[0]).(*ast.CompositeLit)
		if !ok || len(lit.Elts) != 1 {
			return true
		}
		elt := lit.Elts[0]
		if kv, ok := elt.(*ast.KeyValueExpr); ok {
			elt = kv.Value
		}
		if !isConstZeroInt(ctx, elt) {
			return true
		}
		countText := ctx.nodeText(call.Args[1])
		if basic, ok := elt.(*ast.BasicLit); ok && basic.Kind == token.INT {
			ctx.warn(call, "avoid bytes.Repeat([]byte{0}, %s); consider using make([]byte, %s) instead", countText, countText)
		} else {
			ctx.warn(call, "avoid bytes.Repeat with a const 0; use make([]byte, %s) instead", countText)
		}
		return true
	})
}

