// shared local-definition traversal ------------------------------------

// forEachLocalDef calls fn for parameter/result/receiver names first
// (in that order, as the reference does), then definitions in each
// function body.  It does not descend into function literals and it
// ignores range variables and type-switch guards, matching the
// reference local-definition walkers.
func forEachLocalDef(file *ast.File, includeParams, includeLocals bool, fn func(*ast.Ident)) {
	var checkNode func(n ast.Node)
	checkNode = func(n ast.Node) {
		switch node := n.(type) {
		case *ast.AssignStmt:
			if node.Tok == token.DEFINE {
				for _, lhs := range node.Lhs {
					if id, ok := lhs.(*ast.Ident); ok {
