					}
				}
			}
		case *ast.ValueSpec:
			for _, name := range node.Names {
				fn(name)
			}
		}
	}
	_ = checkNode
	for _, decl := range file.Decls {
		fnDecl, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		if includeParams {
			if fnDecl.Type != nil {
				for _, fields := range []*ast.FieldList{fnDecl.Type.Params, fnDecl.Type.Results} {
					if fields == nil {
						continue
					}
					for _, field := range fields.List {
						for _, name := range field.Names {
							fn(name)
						}
					}
				}
			}
			if fnDecl.Recv != nil {
				for _, field := range fnDecl.Recv.List {
					for _, name := range field.Names {
						fn(name)
					}
				}
			}
		}
		if !includeLocals || fnDecl.Body == nil {
			continue
		}
		ast.Inspect(fnDecl.Body, func(n ast.Node) bool {
			switch node := n.(type) {
			case *ast.FuncLit:
				return false
			case *ast.TypeSwitchStmt:
				if node.Init != nil {
					ast.Inspect(node.Init, func(m ast.Node) bool { checkNode(m); return true })
				}
				if node.Body != nil {
					ast.Inspect(node.Body, func(m ast.Node) bool {
						if _, isLit := m.(*ast.FuncLit); isLit {
							return false
						}
						checkNode(m)
						return true
					})
				}
				return false
			default:
				checkNode(n)
				return true
			}
		})
	}
}

// builtinShadow --------------------------------------------------------

func checkBuiltinShadow(ctx *runCtx, file *ast.File) {
	forEachLocalDef(file, true, true, func(id *ast.Ident) {
		if types.Universe.Lookup(id.Name) != nil {
			ctx.warn(id, "shadowing of predeclared identifier: %s", id.Name)
		}
	})
}

// importShadow ---------------------------------------------------------

type importInfo struct {
	name string
	from string // non-empty when the "imported from" form is used
}

func checkImportShadow(ctx *runCtx, file *ast.File) {
	imports := make(map[string]importInfo)
	for _, spec := range file.Imports {
		path := ""
		if spec.Path != nil {
			if p, err := strconv.Unquote(spec.Path.Value); err == nil {
				path = p
			}
		}
		if spec.Name != nil {
			name := spec.Name.Name
			if name == "." || name == "_" {
				continue
			}
			imports[name] = importInfo{name: name}
			continue
		}
		name := ""
		if ctx.pkg != nil {
			if imported, ok := ctx.pkg.Imports[path]; ok && imported.Name != "" {
				name = imported.Name
			}
		}
		if name == "" {
			name = guessedPackageName(path)
		}
		if name == "" {
			continue
		}
		info := importInfo{name: name}
		if base := pathBase(path); base != name {
			info.from = path
		}
		imports[name] = info
	}
	if len(imports) == 0 {
		return
	}
	forEachLocalDef(file, true, true, func(id *ast.Ident) {
		if info, ok := imports[id.Name]; ok {
			if info.from != "" {
				ctx.warn(id, "shadow of imported from '%s' package '%s'", info.from, info.name)
			} else {
				ctx.warn(id, "shadow of imported package '%s'", info.name)
			}
		}
	})
}

func pathBase(p string) string {
	if idx := strings.LastIndex(p, "/"); idx >= 0 {
		return p[idx+1:]
	}
	return p
}

func guessedPackageName(path string) string {
	base := pathBase(path)
	// Strip a trailing version segment such as /v2.
	if len(base) > 1 && base[0] == 'v' {
		isVersion := true
		for i := 1; i < len(base); i++ {
			if base[i] < '0' || base[i] > '9' {
				isVersion = false
				break
			}
		}
		if isVersion {
			if idx := strings.LastIndex(strings.TrimSuffix(path, "/"+base), "/"); idx >= 0 {
				return path[idx+1 : len(path)-len(base)-1]
			}
			return ""
		}
	}
	return base
}

// paramTypeCombine -----------------------------------------------------

func canCombineFields(fields *ast.FieldList) bool {
	if fields == nil {
		return false
	}
	for i := 0; i+1 < len(fields.List); i++ {
		a, b := fields.List[i], fields.List[i+1]
		if len(a.Names) == 0 || len(b.Names) == 0 {
			continue
		}
		if types.ExprString(a.Type) == types.ExprString(b.Type) {
			return true
		}
	}
	return false
}

func combinedFieldGroups(ctx *runCtx, fields *ast.FieldList) []string {
	if fields == nil {
		return nil
	}
	var groups []string
	for i := 0; i < len(fields.List); {
		field := fields.List[i]
		names := make([]string, 0, len(field.Names))
		for _, name := range field.Names {
			names = append(names, name.Name)
		}
		typeText := ctx.prettyText(field.Type)
		j := i + 1
		if len(names) > 0 {
			for j < len(fields.List) && len(fields.List[j].Names) > 0 && types.ExprString(fields.List[j].Type) == types.ExprString(field.Type) {
				for _, name := range fields.List[j].Names {
					names = append(names, name.Name)
				}
				j++
			}
		}
		if len(names) == 0 {
			groups = append(groups, typeText)
		} else {
			groups = append(groups, strings.Join(names, ", ")+" "+typeText)
		}
		i = j
	}
	return groups
}

func combinedSignature(ctx *runCtx, fnType *ast.FuncType) string {
	var b strings.Builder
	b.WriteString("func")
	if fnType.TypeParams != nil && len(fnType.TypeParams.List) > 0 {
		b.WriteString("[")
		b.WriteString(strings.Join(combinedFieldGroups(ctx, fnType.TypeParams), ", "))
		b.WriteString("]")
	}
	b.WriteString("(")
	b.WriteString(strings.Join(combinedFieldGroups(ctx, fnType.Params), ", "))
	b.WriteString(")")
	if fnType.Results != nil && len(fnType.Results.List) > 0 {
		groups := combinedFieldGroups(ctx, fnType.Results)
		only := len(fnType.Results.List) == 1 && len(fnType.Results.List[0].Names) == 0
		if only {
			b.WriteString(" ")
			b.WriteString(groups[0])
		} else {
			b.WriteString(" (")
			b.WriteString(strings.Join(groups, ", "))
			b.WriteString(")")
		}
	}
	return b.String()
}

func checkParamTypeCombine(ctx *runCtx, file *ast.File) {
	for _, decl := range file.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok || fn.Type == nil {
			continue
		}
