// typeUnparen ----------------------------------------------------------

func subsumesTypeChild(parent, child ast.Node) bool {
	switch p := parent.(type) {
	case *ast.ParenExpr:
		return child == p.X
	case *ast.StarExpr:
		return child == p.X
	case *ast.ArrayType:
		return child == p.Elt
	case *ast.MapType:
		return child == p.Key || child == p.Value
	case *ast.ChanType:
		return child == p.Value
	case *ast.Ellipsis:
		return child == p.Elt
	case *ast.SelectorExpr:
		return child == p.X
	case *ast.IndexExpr:
		return child == p.X
	case *ast.IndexListExpr:
		return child == p.X
	}
	return false
}

func typeHasParen(node ast.Node) bool {
	found := false
	ast.Inspect(node, func(n ast.Node) bool {
		if found {
			return false
		}
		switch n.(type) {
		case *ast.ParenExpr:
			found = true
			return false
		case *ast.StructType, *ast.InterfaceType:
			if n != node {
				// Field types are separate candidates.  A
				// struct/interface as the node itself cannot
				// contain a paren in its spine either.
				return false
			}
			return false
		case *ast.IndexExpr:
			// Do not descend into the index argument below via
			// generic Inspect; handled by pruning in the
			// wrapper below is hard with Inspect, so fall
			// through: generic args rarely matter here.
		}
		return true
	})
	return found
}

func unparenTypeText(ctx *runCtx, expr ast.Expr) string {
	switch e := expr.(type) {
	case *ast.ParenExpr:
		return unparenTypeText(ctx, e.X)
	case *ast.StarExpr:
		return "*" + unparenTypeText(ctx, e.X)
	case *ast.ArrayType:
		length := ""
		if e.Len != nil {
			length = ctx.nodeText(e.Len)
		}
		return "[" + length + "]" + unparenTypeText(ctx, e.Elt)
	case *ast.MapType:
		return "map[" + unparenTypeText(ctx, e.Key) + "]" + unparenTypeText(ctx, e.Value)
	case *ast.ChanType:
		switch e.Dir {
		case ast.SEND:
			return "chan<- " + unparenTypeText(ctx, e.Value)
		case ast.RECV:
			return "<-chan " + unparenTypeText(ctx, e.Value)
		default:
			return "chan " + unparenTypeText(ctx, e.Value)
		}
	case *ast.Ellipsis:
		return "..." + unparenTypeText(ctx, e.Elt)
	case *ast.FuncType:
		return unparenFuncTypeText(ctx, e)
	case *ast.StructType:
		return "struct{...}"
	case *ast.InterfaceType:
		return "interface{...}"
	case *ast.IndexExpr:
		return unparenTypeText(ctx, e.X) + "[" + unparenTypeText(ctx, e.Index) + "]"
	case *ast.IndexListExpr:
		parts := make([]string, len(e.Indices))
		for i, idx := range e.Indices {
			parts[i] = unparenTypeText(ctx, idx)
		}
		return unparenTypeText(ctx, e.X) + "[" + strings.Join(parts, ", ") + "]"
	case *ast.BinaryExpr:
		return unparenTypeText(ctx, e.X) + " " + e.Op.String() + " " + unparenTypeText(ctx, e.Y)
	case *ast.UnaryExpr:
		return e.Op.String() + unparenTypeText(ctx, e.X)
	default:
		return ctx.prettyText(expr)
	}
}

func unparenFuncTypeText(ctx *runCtx, fnType *ast.FuncType) string {
	groups := func(fields *ast.FieldList) []string {
		if fields == nil {
			return nil
		}
		var out []string
		for _, field := range fields.List {
			text := unparenTypeText(ctx, field.Type)
			if len(field.Names) == 0 {
				out = append(out, text)
			} else {
				names := make([]string, len(field.Names))
				for i, name := range field.Names {
					names[i] = name.Name
				}
				out = append(out, strings.Join(names, ", ")+" "+text)
			}
		}
		return out
	}
	s := "func(" + strings.Join(groups(fnType.Params), ", ") + ")"
	if fnType.Results != nil && len(fnType.Results.List) > 0 {
		resultGroups := groups(fnType.Results)
		if len(fnType.Results.List) == 1 && len(fnType.Results.List[0].Names) == 0 {
			s += " " + resultGroups[0]
		} else {
			s += " (" + strings.Join(resultGroups, ", ") + ")"
		}
	}
	return s
}

func typeDisplayText(ctx *runCtx, expr ast.Expr) string {
	// Count paren layers around a struct/interface type.
	layers := 0
	core := expr
	for {
		if paren, ok := core.(*ast.ParenExpr); ok {
			layers++
			core = paren.X
			continue
		}
		break
	}
	var coreText string
	switch core.(type) {
	case *ast.StructType:
		coreText = "struct{...}"
	case *ast.InterfaceType:
		coreText = "interface{...}"
	default:
		return ctx.prettyText(expr)
	}
	return strings.Repeat("(", layers) + coreText + strings.Repeat(")", layers)
}

func checkTypeUnparen(ctx *runCtx, file *ast.File) {
	if ctx.info == nil {
		return
	}
	var stack []ast.Node
	ast.Inspect(file, func(n ast.Node) bool {
		if n == nil {
			if len(stack) > 0 {
				stack = stack[:len(stack)-1]
			}
			return true
		}
		var parent ast.Node
		if len(stack) > 0 {
			parent = stack[len(stack)-1]
		}
		stack = append(stack, n)
		expr, ok := n.(ast.Expr)
		if !ok {
			return true
		}
		tv, hasType := ctx.info.Types[expr]
		if !hasType || !tv.IsType() {
			return true
		}
		if parent != nil && subsumesTypeChild(parent, n) {
			return true
		}
		// Struct/interface nodes themselves are never warned on
		// for parens inside their fields; their fields are
		// visited separately.  (Parens *around* them are
		// reported through the enclosing ParenExpr.)
		switch expr.(type) {
		case *ast.StructType, *ast.InterfaceType:
			return true
		}
		if typeHasParen(expr) {
			ctx.warn(expr, "could simplify %s to %s", typeDisplayText(ctx, expr), unparenTypeText(ctx, expr))
		}
		return true
	})
}
