package main

import (
	"go/ast"
	"go/types"
)

func init() {
	checkerFactories["badLock"] = simple(checkBadLock)
	checkerFactories["badSorting"] = simple(checkBadSorting)
	checkerFactories["badSyncOnceFunc"] = simple(checkBadSyncOnceFunc)
	checkerFactories["builtinShadowDecl"] = simple(checkBuiltinShadowDecl)
}

// badLock --------------------------------------------------------------

func lockCallName(stmt ast.Stmt) (ast.Expr, string, bool) {
	exprStmt, ok := stmt.(*ast.ExprStmt)
	if !ok {
		return nil, "", false
	}
	call, ok := exprStmt.X.(*ast.CallExpr)
	if !ok || len(call.Args) != 0 {
		return nil, "", false
	}
	sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
	if !ok {
		return nil, "", false
	}
	return sel.X, sel.Sel.Name, true
}

func checkBadLock(ctx *runCtx, file *ast.File) {
	checkList := func(list []ast.Stmt) {
		for i := 0; i+1 < len(list); i++ {
			recv1, name1, ok1 := lockCallName(list[i])
			recv2, name2, ok2 := lockCallName(list[i+1])
			if !ok1 || !ok2 || !exprEqual(recv1, recv2) {
				continue
			}
			if (name1 == "Lock" && name2 == "Unlock") || (name1 == "RLock" && name2 == "RUnlock") {
				// Warning position is the unlock call.
				ctx.warn(list[i+1], "defer is missing, mutex is unlocked immediately")
			}
		}
	}
	ast.Inspect(file, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.BlockStmt:
			checkList(node.List)
		case *ast.CaseClause:
			checkList(node.Body)
		case *ast.CommClause:
			checkList(node.Body)
		}
		return true
	})
}

// badSorting -----------------------------------------------------------

func checkBadSorting(ctx *runCtx, file *ast.File) {
	mapping := map[string]string{"StringSlice": "Strings", "IntSlice": "Ints", "Float64Slice": "Float64s"}
	ast.Inspect(file, func(n ast.Node) bool {
		stmt, ok := n.(*ast.AssignStmt)
		if !ok || len(stmt.Lhs) != 1 || len(stmt.Rhs) != 1 {
			return true
		}
		call, ok := stmt.Rhs[0].(*ast.CallExpr)
		if !ok || len(call.Args) != 1 {
			return true
		}
		sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
		if !ok {
			return true
		}
		wrapper, known := mapping[sel.Sel.Name]
		if !known {
			return true
		}
		if path, imported := ctx.importedPkg(sel); imported {
			if path != "sort" {
				return true
			}
		} else if identName(sel.X) != "sort" {
			return true
		}
		if exprEqual(stmt.Lhs[0], call.Args[0]) {
			ctx.warn(stmt, "suspicious sort.%s usage, maybe sort.%s was intended?", wrapper, wrapper)
		}
		return true
	})
}

// badSyncOnceFunc ------------------------------------------------------

func isSyncOnceFuncCall(ctx *runCtx, call *ast.CallExpr) bool {
	sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
	if !ok || sel.Sel.Name != "OnceFunc" {
		return false
	}
	if path, imported := ctx.importedPkg(sel); imported {
		return path == "sync"
	}
	return identName(sel.X) == "sync"
}

func checkBadSyncOnceFunc(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.CallExpr:
			if inner, ok := unwrapParen(node.Fun).(*ast.CallExpr); ok && isSyncOnceFuncCall(ctx, inner) {
				ctx.warn(inner, "possible sync.OnceFunc misuse, consider to assign %s to a variable", ctx.nodeText(inner))
			}
		case *ast.ExprStmt:
			if call, ok := node.X.(*ast.CallExpr); ok && isSyncOnceFuncCall(ctx, call) {
				ctx.warn(call, "possible sync.OnceFunc misuse, %s result is not used", ctx.nodeText(call))
			}
		}
		return true
	})
}

// builtinShadowDecl ----------------------------------------------------

func checkBuiltinShadowDecl(ctx *runCtx, file *ast.File) {
	for _, decl := range file.Decls {
		switch d := decl.(type) {
		case *ast.GenDecl:
			// Import declarations do not introduce package-level names.
			if d.Tok.String() == "import" {
				continue
			}
			for _, spec := range d.Specs {
				switch sp := spec.(type) {
				case *ast.TypeSpec:
					if types.Universe.Lookup(sp.Name.Name) != nil {
						ctx.warn(sp.Name, "shadowing of predeclared identifier: %s", sp.Name.Name)
					}
				case *ast.ValueSpec:
					for _, name := range sp.Names {
						if types.Universe.Lookup(name.Name) != nil {
							ctx.warn(name, "shadowing of predeclared identifier: %s", name.Name)
						}
					}
				}
			}
		case *ast.FuncDecl:
			if d.Recv == nil && types.Universe.Lookup(d.Name.Name) != nil {
				ctx.warn(d.Name, "shadowing of predeclared identifier: %s", d.Name.Name)
			}
		}
	}
}
