package main

import (
	"go/ast"
	"go/token"
)

func init() {
	checkerFactories["boolExprSimplify"] = simple(checkBoolExprSimplify)
}

var invertedComparison = map[token.Token]token.Token{
	token.EQL: token.NEQ,
	token.NEQ: token.EQL,
	token.LSS: token.GEQ,
	token.LEQ: token.GTR,
	token.GTR: token.LEQ,
	token.GEQ: token.LSS,
}

// negationOperand returns the operand of a ! expression, allowing one
// redundant pair of parentheses around either the negation or its
// operand in the forms the reference checker recognises.
func negationInfo(expr ast.Expr) (ast.Expr, bool) {
	expr = unwrapParen(expr)
	unary, ok := expr.(*ast.UnaryExpr)
	if !ok || unary.Op != token.NOT {
		return nil, false
	}
	return unary.X, true
}

func checkBoolExprSimplify(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.BinaryExpr:
			if node.Op == token.EQL {
				left, lok := negationInfo(node.X)
				right, rok := negationInfo(node.Y)
				if lok && rok {
					ctx.warn(node, "can simplify `%s` to `%s == %s`", ctx.prettyText(node), ctx.nodeText(left), ctx.nodeText(right))
					return false
				}
			}
		case *ast.UnaryExpr:
			if node.Op != token.NOT {
				return true
			}
			operand := node.X
			// !(comparison)
			if paren, ok := operand.(*ast.ParenExpr); ok {
				if bin, ok := paren.X.(*ast.BinaryExpr); ok {
					if inv, ok := invertedComparison[bin.Op]; ok {
						clone := *bin
						clone.Op = inv
						ctx.warn(node, "can simplify `%s` to `%s`", ctx.prettyText(node), ctx.prettyText(&clone))
						return false
					}
				}
			}
			// Double negation, with or without parentheses
			// around the inner negation.
			inner := unwrapParen(operand)
			if innerUnary, ok := inner.(*ast.UnaryExpr); ok && innerUnary.Op == token.NOT {
				ctx.warn(node, "can simplify `%s` to `%s`", ctx.prettyText(node), ctx.prettyText(innerUnary.X))
				return false
			}
		}
		return true
	})
}
