// deferInLoop ----------------------------------------------------------

func checkDeferInLoop(ctx *runCtx, file *ast.File) {
	var walk func(node ast.Node, inLoop bool)
	walk = func(node ast.Node, inLoop bool) {
		if node == nil {
			return
		}
		switch n := node.(type) {
		case *ast.FuncLit:
			// A defer inside a function literal runs when that
			// literal returns, even if it is created in a loop.
			if n.Body != nil {
				walk(n.Body, false)
			}
			return
		case *ast.ForStmt:
			// Init/Cond/Post are not loop-body contexts, but a
			// defer can only appear in the body in valid code.
			if n.Body != nil {
				walk(n.Body, true)
			}
			return
		case *ast.RangeStmt:
			if n.Body != nil {
				walk(n.Body, true)
			}
			return
		case *ast.DeferStmt:
			if inLoop {
				ctx.warn(n, "Possible resource leak, 'defer' is called in the 'for' loop")
			}
			return
		}
		// Generic descent.
		ast.InspectChildren(node, func(child ast.Node) bool {
			walk(child, inLoop)
			return false
		})
	}
	// ast.InspectChildren is not in go/ast for all Go versions this
	// project may be built with; walkDeclarations below replaces it.
	_ = walk
	walkAvoidLoops(ctx, file)
}

// walkAvoidLoops is the actual implementation, expressed with an
// explicit recursive descent using ast.Walk on child lists through
// Inspect with loop-depth tracking.  The helper above is retained
// in a simpler form here to keep the logic in one place.
func walkAvoidLoops(ctx *runCtx, file *ast.File) {
	// We implement loop tracking by walking statements recursively
	// through a small hand-written traversal over the AST using
	// reflection-free child enumeration via ast.Inspect on
	// subtrees, resetting at function literals.
	var visit func(node ast.Node, depth int)
	visit = func(node ast.Node, depth int) {
		ast.Inspect(node, func(n ast.Node) bool {
			switch cur := n.(type) {
			case *ast.FuncLit:
				if cur.Body != nil {
					visit(cur.Body, 0)
				}
				return false
			case *ast.ForStmt:
				if cur.Body != nil {
					visit(cur.Body, depth+1)
				}
				return false
			case *ast.RangeStmt:
				if cur.Body != nil {
					visit(cur.Body, depth+1)
				}
				return false
			case *ast.DeferStmt:
				if depth > 0 {
					ctx.warn(cur, "Possible resource leak, 'defer' is called in the 'for' loop")
				}
				return false
			}
			return true
		})
	}
	visit(file, 0)
}

// deferUnlambda --------------------------------------------------------

func checkDeferUnlambda(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		stmt, ok := n.(*ast.DeferStmt)
		if !ok || stmt.Call == nil || len(stmt.Call.Args) != 0 {
			return true
		}
		lit, ok := unwrapParen(stmt.Call.Fun).(*ast.FuncLit)
		if !ok || lit.Body == nil || len(lit.Body.List) != 1 || lit.Type == nil {
			return true
		}
		if lit.Type.Params != nil && len(lit.Type.Params.List) > 0 {
			return true
		}
		exprStmt, ok := lit.Body.List[0].(*ast.ExprStmt)
		if !ok {
			return true
		}
		call, ok := exprStmt.X.(*ast.CallExpr)
		if !ok {
			return true
		}
		ctx.warn(stmt, "can rewrite as `defer %s`", ctx.nodeText(call))
		return true
	})
}

// docStub --------------------------------------------------------------

func isDocStubText(text, name string) bool {
	text = strings.TrimSpace(text)
	if !strings.HasPrefix(text, name) {
		return false
	}
	rest := strings.TrimSpace(text[len(name):])
	switch rest {
	case ".", "...":
		return true
	}
	lower := strings.ToLower(rest)
	return lower == "xxx" || lower == "xxx."
}

func checkDocStub(ctx *runCtx, file *ast.File) {
	for _, decl := range file.Decls {
		switch d := decl.(type) {
		case *ast.FuncDecl:
			if d.Doc != nil && isDocStubText(d.Doc.Text(), d.Name.Name) {
				ctx.warn(d, "silencing go lint doc-comment warnings is unadvised")
			}
		case *ast.GenDecl:
			if d.Tok.String() != "type" {
				continue
			}
			for _, spec := range d.Specs {
				typeSpec, ok := spec.(*ast.TypeSpec)
				if !ok {
					continue
				}
				doc := typeSpec.Doc
				if doc == nil {
					doc = d.Doc
				}
				if doc != nil && isDocStubText(doc.Text(), typeSpec.Name.Name) {
					// Position is the declaration.  For a
					// non-grouped type declaration the
					// GenDecl position is the "type"
					// keyword; in a group it is the
					// TypeSpec name position — the
					// reference reports the position of
					// the node carrying the doc comment,
					// which we approximate with the spec
					// for grouped cases and GenDecl
					// otherwise.
					if typeSpec.Doc != nil {
						ctx.warn(typeSpec, "silencing go lint doc-comment warnings is unadvised")
					} else {
						ctx.warn(d, "silencing go lint doc-comment warnings is unadvised")
					}
				}
			}
		}
	}
}

// dupImport ------------------------------------------------------------

func formatLineList(lines []int) string {
	parts := make([]string, len(lines))
	for i, line := range lines {
		parts[i] = strconv.Itoa(line)
	}
	if len(parts) == 1 {
		return parts[0]
	}
	return strings.Join(parts[:len(parts)-1], ", ") + " and " + parts[len(parts)-1]
}

func checkDupImport(ctx *runCtx, file *ast.File) {
	type group struct {
		specs []*ast.ImportSpec
	}
	groups := make(map[string]*group)
	var order []string
	for _, spec := range file.Imports {
		if spec.Path == nil {
			continue
		}
		path, err := strconv.Unquote(spec.Path.Value)
		if err != nil {
			continue
		}
		g, ok := groups[path]
		if !ok {
			g = &group{}
			groups[path] = g
			order = append(order, path)
		}
		g.specs = append(g.specs, spec)
	}
	for _, path := range order {
		g := groups[path]
		if len(g.specs) < 2 {
			continue
		}
		lines := make([]int, len(g.specs))
		for i, spec := range g.specs {
			lines[i] = ctx.fset.Position(spec.Pos()).Line
		}
		for _, spec := range g.specs {
			ctx.warn(spec, "package is imported %d times under different aliases on lines %s", len(g.specs), formatLineList(lines))
		}
	}
}

// dynamicFmtString -----------------------------------------------------

func checkDynamicFmtString(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) != 1 {
			return true
		}
		sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
		if !ok || sel.Sel.Name != "Errorf" {
			return true
		}
		if path, imported := ctx.importedPkg(sel); imported {
			if path != "fmt" {
				return true
			}
		} else if identName(sel.X) != "fmt" {
			return true
		}
		if !ctx.isConstantExpr(call.Args[0]) {
			arg := ctx.nodeText(call.Args[0])
			ctx.warn(call, "use errors.New(%s) or fmt.Errorf(\"%%s\", %s) instead", arg, arg)
		}
		return true
	})
}
