package main

import (
	"go/ast"
	"go/token"
	"go/types"
	"strconv"
	"strings"
)

func init() {
	checkerFactories["emptyDecl"] = simple(checkEmptyDecl)
	checkerFactories["emptyFallthrough"] = simple(checkEmptyFallthrough)
	checkerFactories["emptyStringTest"] = simple(checkEmptyStringTest)
	checkerFactories["equalFold"] = simple(checkEqualFold)
