// emptyDecl ------------------------------------------------------------

func checkEmptyDecl(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		decl, ok := n.(*ast.GenDecl)
		if !ok || !decl.Lparen.IsValid() || len(decl.Specs) != 0 {
			return true
		}
		switch decl.Tok {
		case token.VAR, token.CONST, token.TYPE:
			ctx.warn(decl, "empty %s() block", decl.Tok.String())
		}
		return true
	})
}

// emptyFallthrough -----------------------------------------------------

func checkEmptyFallthrough(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		stmt, ok := n.(*ast.SwitchStmt)
		if !ok || stmt.Body == nil {
			return true
		}
		for i, item := range stmt.Body.List {
			clause, ok := item.(*ast.CaseClause)
			if !ok || i+1 >= len(stmt.Body.List) || len(clause.Body) != 1 {
				continue
			}
			branch, ok := clause.Body[0].(*ast.BranchStmt)
			if !ok || branch.Tok != token.FALLTHROUGH {
				continue
			}
			next, ok := stmt.Body.List[i+1].(*ast.CaseClause)
			if !ok {
				continue
			}
			if len(next.List) == 0 {
				ctx.warn(branch, "remove empty case containing only fallthrough to default case")
			} else {
				ctx.warn(branch, "replace empty case containing only fallthrough with expression list")
			}
		}
		return true
	})
}

// emptyStringTest ------------------------------------------------------

func checkEmptyStringTest(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		call, ok := bin.X.(*ast.CallExpr)
		if !ok || identName(call.Fun) != "len" || len(call.Args) != 1 || !isZeroBasicLit(bin.Y) {
			return true
		}
		if basic, ok := ctx.typeOf(call.Args[0]).(*types.Basic); !ok || basic.Kind() != types.String {
			return true
		}
		var op string
		switch bin.Op {
		case token.EQL, token.LEQ:
			op = "=="
		case token.NEQ, token.GTR:
			op = "!="
			_ = op
		default:
			return true
		}
		ctx.warn(bin, "replace `%s` with `%s %s \"\"`", ctx.nodeText(bin), ctx.nodeText(call.Args[0]), op)
		return true
	})
}

// equalFold ------------------------------------------------------------

type foldCall struct {
	fn    string
	inner ast.Expr
