func checkExternalErrorReassign(ctx *runCtx, file *ast.File) {
	errorType := types.Universe.Lookup("error").Type()
	ast.Inspect(file, func(n ast.Node) bool {
		stmt, ok := n.(*ast.AssignStmt)
		if !ok {
