func init() { checkerFactories["evalOrder"] = simple(checkEvalOrder) }

func checkEvalOrder(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		ret, ok := n.(*ast.ReturnStmt)
		if !ok {
			return true
		}
		// Collect identifiers returned as bare results.
		bare := make(map[string]bool)
		for _, result := range ret.Results {
			if id, ok := result.(*ast.Ident); ok {
				bare[id.Name] = true
			}
		}
		if len(bare) == 0 {
			return true
		}
		for _, result := range ret.Results {
			call, ok := result.(*ast.CallExpr)
			if !ok {
				continue
			}
			for _, arg := range call.Args {
				unary, ok := arg.(*ast.UnaryExpr)
				if !ok || unary.Op != token.AND {
					continue
				}
				if id, ok := unary.X.(*ast.Ident); ok && bare[id.Name] {
					ctx.warn(call, "may want to evaluate %s before the return statement", ctx.nodeText(call))
					break
				}
			}
		}
		return true
	})
}
