func checkHexLiteral(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		lit, ok := n.(*ast.BasicLit)
		if !ok || (lit.Kind != token.INT && lit.Kind != token.FLOAT) {
			return true
		}
		text := lit.Value
		if len(text) < 3 || text[0] != '0' || (text[1] != 'x' && text[1] != 'X') {
			return true
		}
		if text[1] == 'X' {
			ctx.warn(lit, "prefer 0x over 0X, s/%s/0x%s/", text, text[2:])
			return true
		}
		digits := text[2:]
		// For hex floats, only the mantissa digits before p/P
		// participate.
		if idx := strings.IndexAny(digits, "pP"); idx >= 0 {
			digits = digits[:idx]
		}
