cat > checkers_exp5.go <<'EOF'
package main

import (
	"go/ast"
	"go/token"
	"go/types"
	"strings"
)

func init() {
	checkerFactories["nilValReturn"] = simple(checkNilValReturn)
	checkerFactories["preferDecodeRune"] = simple(checkPreferDecodeRune)
	checkerFactories["preferFilepathJoin"] = simple(checkPreferFilepathJoin)
	checkerFactories["preferFprint"] = simple(checkPreferFprint)
	checkerFactories["preferStringWriter"] = simple(checkPreferStringWriter)
	checkerFactories["preferWriteByte"] = simple(checkPreferWriteByte)
	checkerFactories["ptrToRefParam"] = simple(checkPtrToRefParam)
	checkerFactories["rangeAppendAll"] = simple(checkRangeAppendAll)
}

// nilValReturn ---------------------------------------------------------

func checkNilValReturn(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		stmt, ok := n.(*ast.IfStmt)
		if !ok || stmt.Body == nil || len(stmt.Body.List) != 1 {
			return true
		}
		bin, ok := stmt.Cond.(*ast.BinaryExpr)
		if !ok || bin.Op != token.EQL {
			return true
		}
		id, ok := bin.X.(*ast.Ident)
		if !ok || identName(bin.Y) != "nil" {
			return true
		}
		ret, ok := stmt.Body.List[0].(*ast.ReturnStmt)
		if !ok {
			return true
		}
		for _, result := range ret.Results {
			if rid, ok := result.(*ast.Ident); ok && rid.Name == id.Name {
				if ctx.objectOf(rid) == ctx.objectOf(id) || ctx.info == nil {
					ctx.warn(result, "returned expr is always nil; replace %s with nil", ctx.nodeText(result))
				}
			}
		}
		return true
	})
}

// preferDecodeRune -----------------------------------------------------

func checkPreferDecodeRune(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		idx, ok := n.(*ast.IndexExpr)
		if !ok || !isZeroBasicLit(idx.Index) {
			return true
		}
		call, ok := unwrapParen(idx.X).(*ast.CallExpr)
		if !ok || len(call.Args) != 1 {
			return true
		}
		arr, ok := unwrapParen(call.Fun).(*ast.ArrayType)
		if !ok || arr.Len != nil || identName(arr.Elt) != "rune" {
			return true
		}
		ctx.warn(idx, "consider replacing %s with utf8.DecodeRuneInString(%s)", ctx.nodeText(idx), ctx.nodeText(call.Args[0]))
		return true
	})
}

// preferFilepathJoin ---------------------------------------------------

func isPathSeparatorStringCall(expr ast.Expr) bool {
	call, ok := unwrapParen(expr).(*ast.CallExpr)
	if !ok || len(call.Args) != 1 || identName(call.Fun) != "string" {
		return false
	}
	sel, ok := unwrapParen(call.Args[0]).(*ast.SelectorExpr)
	return ok && identName(sel.X) == "os" && sel.Sel.Name == "PathSeparator"
}

func checkPreferFilepathJoin(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok || bin.Op != token.ADD {
			return true
		}
		left, ok := bin.X.(*ast.BinaryExpr)
		if !ok || left.Op != token.ADD || !isPathSeparatorStringCall(left.Y) {
			return true
		}
		ctx.warn(bin, "filepath.Join(%s, %s) should be preferred to the %s", ctx.nodeText(left.X), ctx.nodeText(bin.Y), ctx.nodeText(bin))
		return true
	})
}

// fmt Sprint* call helpers --------------------------------------------

func fmtSprintCall(ctx *runCtx, expr ast.Expr) (string, *ast.CallExpr, bool) {
	call, ok := unwrapParen(expr).(*ast.CallExpr)
	if !ok {
		return "", nil, false
	}
	sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
	if !ok {
		return "", nil, false
	}
	switch sel.Sel.Name {
	case "Sprint", "Sprintf", "Sprintln":
	default:
		return "", nil, false
	}
	if path, imported := ctx.importedPkg(sel); imported {
		if path != "fmt" {
			return "", nil, false
		}
	} else if identName(sel.X) != "fmt" {
		return "", nil, false
	}
	return sel.Sel.Name, call, true
}

func sprintToFprint(name string) string { return "F" + strings.TrimPrefix(name, "S") }

func callArgsSourceText(ctx *runCtx, call *ast.CallExpr) string {
	parts := make([]string, len(call.Args))
	for i, arg := range call.Args {
		parts[i] = ctx.nodeText(arg)
	}
	return strings.Join(parts, ",")
}

// preferFprint ---------------------------------------------------------

func checkPreferFprint(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
		if !ok {
			return true
		}
		// w.Write([]byte(fmt.Sprint*(...)))
		if sel.Sel.Name == "Write" && len(call.Args) == 1 {
			if innerExpr, isBytes := byteSliceConversion(call.Args[0]); isBytes {
				if name, sprintCall, ok := fmtSprintCall(ctx, innerExpr); ok {
					recv := ctx.nodeText(sel.X)
					suggestion := "fmt." + sprintToFprint(name) + "(" + recv
					if len(sprintCall.Args) > 0 {
						suggestion += ", " + callArgsSourceText(ctx, sprintCall)
					}
					suggestion += ")"
					ctx.warn(call, "%s should be preferred to the %s", suggestion, ctx.nodeText(call))
					return false
				}
			}
		}
		// io.WriteString(w, fmt.Sprint*(...))
		if sel.Sel.Name == "WriteString" && len(call.Args) == 2 {
			if path, imported := ctx.importedPkg(sel); (!imported && identName(sel.X) == "io") || (imported && path == "io") {
				if name, sprintCall, ok := fmtSprintCall(ctx, call.Args[1]); ok {
					recv := ctx.nodeText(call.Args[0])
					suggestion := "fmt." + sprintToFprint(name) + "(" + recv
					if len(sprintCall.Args) > 0 {
						suggestion += ", " + callArgsSourceText(ctx, sprintCall)
					}
					suggestion += ")"
					ctx.warn(call, "suggestion: %s", suggestion)
					return false
				}
			}
		}
		return true
	})
}

// preferStringWriter ---------------------------------------------------

func typeHasMethodNamed(t types.Type, name string) bool {
	if t == nil {
		return false
	}
	methods := types.NewMethodSet(t)
	for i := 0; i < methods.Len(); i++ {
		if methods.At(i).Obj().Name() == name {
			return true
		}
	}
	return false
}

func checkPreferStringWriter(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
		if !ok {
			return true
		}
		if sel.Sel.Name == "Write" && len(call.Args) == 1 {
			if !typeHasMethodNamed(ctx.typeOf(sel.X), "WriteString") {
				return true
			}
			if inner, ok := byteSliceConversion(call.Args[0]); ok {
				recv := ctx.nodeText(sel.X)
				ctx.warn(call, "%s.WriteString(%s) should be preferred to the %s", recv, ctx.nodeText(inner), ctx.nodeText(call))
				return false
			}
			return true
		}
		if sel.Sel.Name == "WriteString" && len(call.Args) == 2 {
			if path, imported := ctx.importedPkg(sel); (!imported && identName(sel.X) == "io") || (imported && path == "io") {
				w := call.Args[0]
				if !typeHasMethodNamed(ctx.typeOf(w), "WriteString") {
					return true
				}
				recv := w
				if unary, ok := unwrapParen(w).(*ast.UnaryExpr); ok && unary.Op == token.AND {
					recv = unary.X
				}
				ctx.warn(call, "%s.WriteString(%s) should be preferred to the %s", ctx.nodeText(recv), ctx.nodeText(call.Args[1]), ctx.nodeText(call))
