			if inner, ok := byteSliceConversion(call.Args[0]); ok {
				recv := ctx.nodeText(sel.X)
				ctx.warn(call, "%s.WriteString(%s) should be preferred to the %s", recv, ctx.nodeText(inner), ctx.nodeText(call))
				return false
			}
			return true
		}
		if sel.Sel.Name == "WriteString" && len(call.Args) == 2 {
			if path, imported := ctx.importedPkg(sel); (!imported && identName(sel.X) == "io") || (imported && path == "io") {
				w := call.Args[0]
				if !typeHasMethodNamed(ctx.typeOf(w), "WriteString") {
					return true
				}
				recv := w
				if unary, ok := unwrapParen(w).(*ast.UnaryExpr); ok && unary.Op == token.AND {
					recv = unary.X
				}
				ctx.warn(call, "%s.WriteString(%s) should be preferred to the %s", ctx.nodeText(recv), ctx.nodeText(call.Args[1]), ctx.nodeText(call))
				return false
			}
		}
		return true
	})
}

// preferWriteByte ------------------------------------------------------

func checkPreferWriteByte(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) != 1 {
			return true
		}
		sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
		if !ok || sel.Sel.Name != "WriteRune" {
			return true
		}
		if !typeHasMethodNamed(ctx.typeOf(sel.X), "WriteByte") {
			return true
		}
		lit, ok := call.Args[0].(*ast.BasicLit)
		if !ok || lit.Kind != token.CHAR {
			return true
		}
		if tv, ok := ctx.typeAndValueOf(lit); !ok || tv.Value == nil {
			return true
		} else if v, exact := tv.Value.Int64(); !exact || v < 0 || v >= 128 {
			return true
		}
		ctx.warn(call, "consider writing single byte rune %s with %s.WriteByte(%s)", ctx.nodeText(lit), ctx.nodeText(sel.X), ctx.nodeText(lit))
		return true
	})
}

// ptrToRefParam --------------------------------------------------------

func isRefTypeExpr(ctx *runCtx, expr ast.Expr) bool {
	switch unwrapParen(expr).(type) {
	case *ast.MapType, *ast.ChanType, *ast.InterfaceType:
		return true
	}
	if named, ok := ctx.typeOf(expr).(*types.Named); ok {
		_, isIface := named.Underlying().(*types.Interface)
		return isIface
	}
	return false
}

func checkPtrToRefParam(ctx *runCtx, file *ast.File) {
	checkFields := func(fields *ast.FieldList) {
		if fields == nil {
			return
		}
		for _, field := range fields.List {
			star, ok := unwrapParen(field.Type).(*ast.StarExpr)
			if !ok || !isRefTypeExpr(ctx, star.X) {
				continue
			}
			if len(field.Names) == 0 {
				ctx.warn(field.Type, "consider to make non-pointer type for `%s`", ctx.nodeText(field.Type))
				continue
			}
			for _, name := range field.Names {
				ctx.warn(name, "consider `%s' to be of non-pointer type", name.Name)
			}
		}
	}
	for _, decl := range file.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok || fn.Type == nil {
			continue
		}
		checkFields(fn.Type.Params)
		checkFields(fn.Type.Results)
	}
}

// rangeAppendAll -------------------------------------------------------

func checkRangeAppendAll(ctx *runCtx, file *ast.File) {
	var visit func(node ast.Node, ranges []ast.Expr)
	visit = func(node ast.Node, ranges []ast.Expr) {
		ast.Inspect(node, func(n ast.Node) bool {
			switch cur := n.(type) {
			case *ast.FuncLit:
				if cur.Body != nil {
					visit(cur.Body, nil)
				}
				return false
			case *ast.RangeStmt:
				if cur.Body != nil {
					visit(cur.Body, append(append([]ast.Expr{}, ranges...), cur.X))
				}
				return false
			case *ast.CallExpr:
				if identName(cur.Fun) == "append" && cur.Ellipsis.IsValid() && len(cur.Args) >= 2 {
					spread := cur.Args[len(cur.Args)-1]
					for _, r := range ranges {
						if exprEqual(spread, r) {
							ctx.warn(spread, "append all `%s` data while range it", ctx.nodeText(spread))
							break
						}
					}
				}
			}
			return true
		})
	}
	visit(file, nil)
}
