// sortSlice ------------------------------------------------------------

func indexBaseExpr(expr ast.Expr) ast.Expr {
	switch e := unwrapParen(expr).(type) {
	case *ast.IndexExpr:
		return e.X
	case *ast.SelectorExpr:
		return indexBaseExpr(e.X)
	}
	return nil
}

func checkSortSlice(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) != 2 {
			return true
		}
		sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
		if !ok || (sel.Sel.Name != "Slice" && sel.Sel.Name != "SliceStable") {
			return true
		}
		if path, imported := ctx.importedPkg(sel); imported {
			if path != "sort" {
				return true
			}
		} else if identName(sel.X) != "sort" {
			return true
		}
		lit, ok := unwrapParen(call.Args[1]).(*ast.FuncLit)
		if !ok || lit.Body == nil || len(lit.Body.List) != 1 {
			return true
		}
		ret, ok := lit.Body.List[0].(*ast.ReturnStmt)
		if !ok || len(ret.Results) != 1 {
			return true
		}
		bin, ok := ret.Results[0].(*ast.BinaryExpr)
		if !ok {
			return true
		}
		leftBase := indexBaseExpr(bin.X)
		rightBase := indexBaseExpr(bin.Y)
		if leftBase == nil || rightBase == nil {
			return true
		}
		if exprEqual(leftBase, call.Args[0]) || exprEqual(rightBase, call.Args[0]) {
			return true
		}
		ctx.warn(ret, "cmp func must use %s slice in comparison", ctx.nodeText(call.Args[0]))
		return true
	})
}

