func checkSQLQuery(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		stmt, ok := n.(*ast.AssignStmt)
		if !ok || len(stmt.Lhs) == 0 {
			return true
		}
		if id, ok := stmt.Lhs[0].(*ast.Ident); !ok || id.Name != "_" {
			return true
		}
		if len(stmt.Rhs) != 1 {
			return true
		}
		call, ok := stmt.Rhs[0].(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
		if !ok || (sel.Sel.Name != "Query" && sel.Sel.Name != "QueryContext") {
			return true
		}
		switch namedTypeString(ctx.typeOf(sel.X)) {
		case "database/sql.DB", "database/sql.Tx":
			ctx.warn(call, "use %s.Exec() if returned result is not needed", ctx.nodeText(sel.X))
		case "database/sql.Stmt":
			ctx.warn(call, "ignoring Query() rows result may lead to a connection leak")
		}
		return true
	})
}

