func checkStringConcatSimplify(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) != 2 {
			return true
		}
		sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
		if !ok || sel.Sel.Name != "Join" {
			return true
		}
		if path, imported := ctx.importedPkg(sel); imported {
			if path != "strings" {
				return true
			}
		} else if identName(sel.X) != "strings" {
			return true
		}
		lit, ok := unwrapParen(call.Args[0]).(*ast.CompositeLit)
		if !ok || len(lit.Elts) != 2 {
			return true
		}
		left := ctx.nodeText(lit.Elts[0])
		right := ctx.nodeText(lit.Elts[1])
		sep := call.Args[1]
		if tv, ok := ctx.typeAndValueOf(sep); ok && tv.Value != nil && tv.Value.Kind() == constant.String && constant.StringVal(tv.Value) == "" {
			ctx.warn(call, "suggestion: %s + %s", left, right)
		} else {
			ctx.warn(call, "suggestion: %s + %s + %s", left, ctx.nodeText(sep), right)
		}
		return true
	})
}

// stringsCompare -------------------------------------------------------

func constIntValue(ctx *runCtx, expr ast.Expr) (int64, bool) {
	tv, ok := ctx.typeAndValueOf(expr)
	if !ok || tv.Value == nil || tv.Value.Kind() != constant.Int {
		return 0, false
	}
	v, exact := constant.Int64Val(tv.Value)
	return v, exact
}

func checkStringsCompare(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		call, ok := bin.X.(*ast.CallExpr)
		if !ok || len(call.Args) != 2 {
			return true
		}
		sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
		if !ok || sel.Sel.Name != "Compare" {
			return true
		}
		if path, imported := ctx.importedPkg(sel); imported {
			if path != "strings" {
				return true
			}
		} else if identName(sel.X) != "strings" {
			return true
		}
		value, ok := constIntValue(ctx, bin.Y)
		if !ok {
			return true
		}
		var op string
		switch {
		case bin.Op == token.EQL && value == 0:
			op = "=="
		case bin.Op == token.EQL && value == -1, bin.Op == token.LSS && value == 0:
			op = "<"
		case bin.Op == token.EQL && value == 1, bin.Op == token.GTR && value == 0:
			op = ">"
		default:
			return true
		}
		_ = strconv.Itoa
		ctx.warn(bin, "suggestion: %s %s %s", ctx.nodeText(call.Args[0]), op, ctx.nodeText(call.Args[1]))
		return false
	})
}
