// redundantSprint ------------------------------------------------------

func checkRedundantSprint(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
		if !ok {
			return true
		}
		if path, imported := ctx.importedPkg(sel); imported {
			if path != "fmt" {
				return true
			}
		} else if identName(sel.X) != "fmt" {
			return true
		}
		var arg ast.Expr
		switch sel.Sel.Name {
		case "Sprint":
			if len(call.Args) != 1 {
				return true
			}
			arg = call.Args[0]
		case "Sprintf":
			if len(call.Args) != 2 {
				return true
			}
			tv, ok := ctx.typeAndValueOf(call.Args[0])
			if !ok || tv.Value == nil || tv.Value.Kind() != constant.String {
				return true
			}
			format := constant.StringVal(tv.Value)
			if format != "%v" && format != "%s" {
				return true
			}
			arg = call.Args[1]
		default:
			return true
		}
		argType := ctx.typeOf(arg)
		if basic, ok := argType.(*types.Basic); ok && basic.Kind() == types.String {
			ctx.warn(call, "%s is already string", ctx.nodeText(arg))
			return false
		}
		if typeHasMethodNamed(argType, "String") {
			// Verify String() has a string result via the
			// method set lookup in TypesInfo is difficult
			// here; use the same method-set test as the
			// reference-style checkers in this codebase.
			if methods := types.NewMethodSet(argType); methods != nil {
				for i := 0; i < methods.Len(); i++ {
					obj := methods.At(i).Obj()
					if obj.Name() != "String" {
						continue
					}
					if sig, ok := obj.Type().(*types.Signature); ok && sig.Results().Len() == 1 {
						if b, ok := sig.Results().At(0).Type().(*types.Basic); ok && b.Kind() == types.String {
							ctx.warn(call, "use %s.String() instead", ctx.nodeText(arg))
							return false
						}
					}
				}
			}
		}
		return true
	})
}

