func checkSliceClear(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		loop, ok := n.(*ast.ForStmt)
		if !ok || loop.Body == nil || len(loop.Body.List) != 1 {
