		}
		initAssign, ok := loop.Init.(*ast.AssignStmt)
		if !ok || len(initAssign.Lhs) != 1 || len(initAssign.Rhs) != 1 || !isZeroBasicLit(initAssign.Rhs[0]) {
			return true
		}
		loopVar, ok := initAssign.Lhs[0].(*ast.Ident)
		if !ok {
			return true
		}
		cond, ok := loop.Cond.(*ast.BinaryExpr)
		if !ok || cond.Op != token.LSS || identName(cond.X) != loopVar.Name {
			return true
		}
		lenCall, ok := cond.Y.(*ast.CallExpr)
		if !ok || identName(lenCall.Fun) != "len" || len(lenCall.Args) != 1 {
			return true
		}
		// Post: i++ or i += 1.
		postOK := false
		if inc, ok := loop.Post.(*ast.IncDecStmt); ok && inc.Tok == token.INC && identName(inc.X) == loopVar.Name {
			postOK = true
		}
		if postAssign, ok := loop.Post.(*ast.AssignStmt); ok && postAssign.Tok == token.ADD_ASSIGN && len(postAssign.Lhs) == 1 && len(postAssign.Rhs) == 1 && identName(postAssign.Lhs[0]) == loopVar.Name {
			// reuse a constant-1 test through TypesInfo
			if tv, ok := ctx.typeAndValueOf(postAssign.Rhs[0]); ok && tv.Value != nil && tv.Value.Kind() == constant.Int {
				if v, exact := constant.Int64Val(tv.Value); exact && v == 1 {
					if lit, isLit := postAssign.Rhs[0].(*ast.BasicLit); isLit && lit.Kind == token.INT {
						postOK = true
					}
				}
			}
		}
		if !postOK {
			return true
		}
		assign, ok := loop.Body.List[0].(*ast.AssignStmt)
		if !ok || assign.Tok != token.ASSIGN || len(assign.Lhs) != 1 || len(assign.Rhs) != 1 || !isZeroBasicLit(assign.Rhs[0]) {
			return true
		}
		idx, ok := assign.Lhs[0].(*ast.IndexExpr)
		if !ok || !exprEqual(idx.X, lenCall.Args[0]) || identName(idx.Index) != loopVar.Name {
			return true
		}
		ctx.warn(loop, "rewrite as for-range so compiler can recognize this pattern")
		return true
	})
}

