package main

import (
	"go/ast"
	"go/token"
	"go/types"
	"strings"
)

func init() {
	checkerFactories["syncMapLoadAndDelete"] = simple(checkSyncMapLoadAndDelete)
	checkerFactories["timeExprSimplify"] = func(p *checkerParams) checkerInstance {
		// sorted by message via registration in sorted set below
		return funcChecker{fn: checkTimeExprSimplify}
	}
	checkerFactories["todoCommentWithoutDetail"] = simple(checkTodoCommentWithoutDetail)
	checkerFactories["tooManyResultsChecker"] = func(p *checkerParams) checkerInstance {
		return funcChecker{fn: func(ctx *runCtx, file *ast.File) { checkTooManyResults(ctx, file, p) }}
	}
	checkerFactories["truncateCmp"] = func(p *checkerParams) checkerInstance {
		return funcChecker{fn: func(ctx *runCtx, file *ast.File) { checkTruncateCmp(ctx, file, p) }}
	}
	checkerFactories["typeAssertChain"] = simple(checkTypeAssertChain)
	checkerFactories["typeDefFirst"] = simple(checkTypeDefFirst)
	checkerFactories["uncheckedInlineErr"] = simple(checkUncheckedInlineErr)
	checkerFactories["unlabelStmt"] = simple(checkUnlabelStmt)
}

// syncMapLoadAndDelete -------------------------------------------------

func checkSyncMapLoadAndDelete(ctx *runCtx, file *ast.File) {
	checkList := func(list []ast.Stmt) {
		for i := 0; i+1 < len(list); i++ {
			assign, ok := list[i].(*ast.AssignStmt)
			if !ok || len(assign.Lhs) != 2 || len(assign.Rhs) != 1 {
				continue
			}
			loadCall, ok := assign.Rhs[0].(*ast.CallExpr)
			if !ok || len(loadCall.Args) != 1 {
				continue
			}
			loadSel, ok := unwrapParen(loadCall.Fun).(*ast.SelectorExpr)
			if !ok || loadSel.Sel.Name != "Load" {
				continue
			}
			if namedTypeString(ctx.typeOf(loadSel.X)) != "sync.Map" {
				continue
			}
			if _, isPtr := ctx.typeOf(loadSel.X).(*types.Pointer); !isPtr {
				continue
			}
			ifStmt, ok := list[i+1].(*ast.IfStmt)
			if !ok || ifStmt.Body == nil || len(ifStmt.Body.List) == 0 {
				continue
			}
			okIdent, ok := assign.Lhs[1].(*ast.Ident)
			if !ok || identName(ifStmt.Cond) != okIdent.Name {
				continue
			}
			first, ok := ifStmt.Body.List[0].(*ast.ExprStmt)
			if !ok {
				continue
			}
			delCall, ok := first.X.(*ast.CallExpr)
			if !ok || len(delCall.Args) != 1 {
				continue
			}
			delSel, ok := unwrapParen(delCall.Fun).(*ast.SelectorExpr)
			if !ok || delSel.Sel.Name != "Delete" || !exprEqual(loadSel.X, delSel.X) || !exprEqual(loadCall.Args[0], delCall.Args[0]) {
				continue
			}
			ctx.warn(assign, "use %s.LoadAndDelete to perform load+delete operations atomically", ctx.nodeText(loadSel.X))
		}
	}
	ast.Inspect(file, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.BlockStmt:
			checkList(node.List)
		case *ast.CaseClause:
			checkList(node.Body)
		case *ast.CommClause:
			checkList(node.Body)
		}
		return true
	})
}

// timeExprSimplify -----------------------------------------------------

func checkTimeExprSimplify(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok || bin.Op != token.QUO {
			return true
		}
		lit, ok := bin.Y.(*ast.BasicLit)
		if !ok || lit.Kind != token.INT || lit.Value != "1000" {
			return true
		}
		call, ok := unwrapParen(bin.X).(*ast.CallExpr)
		if !ok || len(call.Args) != 0 {
			return true
		}
		sel, ok := unwrapParen(call.Fun).(*ast.SelectorExpr)
		if !ok || sel.Sel.Name != "Unix" {
			return true
		}
		if namedTypeString(ctx.typeOf(sel.X)) != "time.Time" && ctx.info != nil {
			// time.Now() returns Time, so the receiver type
			// check above through namedTypeString on a call
			// expression works because its type is time.Time.
			return true
		}
		recv := ctx.nodeText(sel.X)
		ctx.warn(bin, "use %s.UnixMilli() instead of %s", recv, ctx.nodeText(bin))
		return true
	})
}

// todoCommentWithoutDetail ---------------------------------------------

func checkTodoCommentWithoutDetail(ctx *runCtx, file *ast.File) {
	for _, group := range file.Comments {
		for _, comment := range group.List {
			text := comment.Text
			if strings.HasPrefix(text, "//") {
				text = strings.TrimSpace(text[2:])
			} else if strings.HasPrefix(text, "/*") && strings.HasSuffix(text, "*/") {
				text = strings.TrimSpace(text[2 : len(text)-2])
			} else {
				continue
			}
			if text == "TODO" || text == "FIXME" || text == "BUG" {
				ctx.warnAt(comment.Slash, "may want to add detail/assignee to this TODO/FIXME/BUG comment")
			}
		}
	}
}

// tooManyResultsChecker ------------------------------------------------

func countFieldResults(fields *ast.FieldList) int {
	if fields == nil {
		return 0
	}
	count := 0
	for _, field := range fields.List {
		if len(field.Names) == 0 {
			count++
		} else {
			count += len(field.Names)
		}
	}
	return count
}

func checkTooManyResults(ctx *runCtx, file *ast.File, p *checkerParams) {
	for _, decl := range file.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok || fn.Type == nil {
			continue
		}
		if countFieldResults(fn.Type.Results) > p.tooManyResultsMaxResults {
			ctx.warn(fn, "function has more than %d results, consider to simplify the function", p.tooManyResultsMaxResults)
		}
	}
}

// truncateCmp ----------------------------------------------------------

func integerBasicInfo(t types.Type) (kind types.BasicKind, bits int64, isInt bool) {
	b, ok := t.Underlying().(*types.Basic)
	if !ok || b.Info()&types.IsInteger == 0 {
		return 0, 0, false
	}
	return b.Kind(), 0, true
}

func checkTruncateCmp(ctx *runCtx, file *ast.File, p *checkerParams) {
	ast.Inspect(file, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		switch bin.Op {
		case token.EQL, token.NEQ, token.LSS, token.LEQ, token.GTR, token.GEQ:
		default:
			return true
		}
		for _, side := range []ast.Expr{bin.X, bin.Y} {
			call, ok := side.(*ast.CallExpr)
			if !ok || len(call.Args) != 1 {
				continue
			}
			tv, ok := ctx.typeAndValueOf(call.Fun)
			if !ok || !tv.IsType() {
				continue
			}
			destType := ctx.typeOf(call)
			srcType := ctx.typeOf(call.Args[0])
			if destType == nil || srcType == nil {
				continue
			}
			destKind, _, destIsInt := integerBasicInfo(destType)
			srcKind, _, srcIsInt := integerBasicInfo(srcType)
			if !destIsInt || !srcIsInt {
				continue
			}
			if p.truncateCmpSkipArchDependent {
				isArch := func(k types.BasicKind) bool {
					return k == types.Int || k == types.Uint || k == types.Uintptr
				}
				if isArch(destKind) || isArch(srcKind) {
					continue
				}
			}
			destSize := sizeOf(ctx, destType)
			srcSize := sizeOf(ctx, srcType)
			if destSize < 0 || srcSize < 0 || destSize >= srcSize {
				continue
			}
			ctx.warn(call, "truncation in comparison %d->%d bit; cast the other operand to %s instead", srcSize*8, destSize*8, typeStringLocal(ctx, srcType))
		}
		return true
	})
}

// typeAssertChain ------------------------------------------------------

func typeAssertIfQualifies(stmt *ast.IfStmt) (ast.Expr, bool) {
	assign, ok := stmt.Init.(*ast.AssignStmt)
	if !ok || len(assign.Lhs) != 2 || len(assign.Rhs) != 1 {
		return nil, false
	}
	assert, ok := assign.Rhs[0].(*ast.TypeAssertExpr)
	if !ok || assert.Type == nil {
		return nil, false
	}
	okIdent, ok := assign.Lhs[1].(*ast.Ident)
	if !ok || identName(stmt.Cond) != okIdent.Name {
		return nil, false
	}
	return assert.X, true
}

func checkTypeAssertChain(ctx *runCtx, file *ast.File) {
	elseIfs := make(map[*ast.IfStmt]bool)
	var roots []*ast.IfStmt
	ast.Inspect(file, func(n ast.Node) bool {
		if stmt, ok := n.(*ast.IfStmt); ok {
			roots = append(roots, stmt)
			if child, ok := stmt.Else.(*ast.IfStmt); ok {
				elseIfs[child] = true
			}
		}
		return true
	})
	for _, root := range roots {
		if elseIfs[root] {
			continue
		}
		// Walk the chain in runs of qualifying ifs with the
		// same asserted expression.
		var runStart *ast.IfStmt
		var runTarget ast.Expr
		runLen := 0
		flush := func() {
			if runLen >= 2 && runStart != nil {
				ctx.warn(runStart, "rewrite if-else to type switch statement")
			}
		}
		for cur := root; cur != nil; {
			target, qualifies := typeAssertIfQualifies(cur)
			if qualifies && runLen > 0 && exprEqual(target, runTarget) {
				runLen++
			} else if qualifies {
				flush()
				runStart, runTarget, runLen = cur, target, 1
			} else {
				flush()
				runStart, runTarget, runLen = nil, nil, 0
			}
			if child, ok := cur.Else.(*ast.IfStmt); ok {
				cur = child
			} else {
				break
			}
		}
		flush()
	}
}

// typeDefFirst ---------------------------------------------------------

func receiverBaseName(expr ast.Expr) string {
	switch e := unwrapParen(expr).(type) {
	case *ast.Ident:
		return e.Name
	case *ast.StarExpr:
		return receiverBaseName(e.X)
	case *ast.IndexExpr:
		return receiverBaseName(e.X)
	case *ast.IndexListExpr:
		return receiverBaseName(e.X)
	}
	return ""
}

func checkTypeDefFirst(ctx *runCtx, file *ast.File) {
	// First method position per receiver base type in this file.
	methodPos := make(map[string]token.Pos)
	for _, decl := range file.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok || fn.Recv == nil || len(fn.Recv.List) == 0 {
			continue
		}
		name := receiverBaseName(fn.Recv.List[0].Type)
		if name == "" {
			continue
		}
		if _, exists := methodPos[name]; !exists {
			methodPos[name] = fn.Pos()
		}
	}
	for _, decl := range file.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok != token.TYPE {
			continue
		}
		for _, spec := range gen.Specs {
			typeSpec, ok := spec.(*ast.TypeSpec)
			if !ok {
				continue
			}
			if pos, exists := methodPos[typeSpec.Name.Name]; exists && pos < gen.Pos() {
				ctx.warn(gen, "definition of type '%s' should appear before its methods", typeSpec.Name.Name)
			}
		}
	}
}

// uncheckedInlineErr ---------------------------------------------------

func checkUncheckedInlineErr(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		stmt, ok := n.(*ast.IfStmt)
		if !ok {
			return true
		}
		assign, ok := stmt.Init.(*ast.AssignStmt)
		if !ok || len(assign.Lhs) != 1 {
			return true
		}
		id, ok := assign.Lhs[0].(*ast.Ident)
		if !ok {
			return true
		}
		obj := ctx.objectOf(id)
		if obj == nil || !types.Identical(obj.Type(), types.Universe.Lookup("error").Type()) {
			return true
		}
		cond, ok := stmt.Cond.(*ast.BinaryExpr)
		if !ok || cond.Op != token.NEQ || identName(cond.Y) != "nil" {
			return true
		}
		other, ok := cond.X.(*ast.Ident)
		if !ok || other.Name == id.Name {
			return true
		}
		ctx.warn(id, "%s error is unchecked, maybe intended to check it instead of %s", id.Name, other.Name)
		return true
	})
}

// unlabelStmt ----------------------------------------------------------

func isBranchTargetStmt(n ast.Node) bool {
	switch n.(type) {
	case *ast.ForStmt, *ast.RangeStmt, *ast.SwitchStmt, *ast.TypeSwitchStmt, *ast.SelectStmt:
		return true
	}
	return false
}

func checkUnlabelStmt(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		labeled, ok := n.(*ast.LabeledStmt)
		if !ok {
			return true
		}
		// The labelled statement itself must be a branch target
		// (a loop/switch/select); labels for goto or blocks are
		// not redundant in this sense.
		target := labeled.Stmt
		for {
			if inner, ok := target.(*ast.LabeledStmt); ok {
				target = inner.Stmt
				continue
			}
			break
		}
		if !isBranchTargetStmt(target) {
			return false
		}
		redundant := true
		// Walk the target statement, tracking whether a branch
		// to this label occurs under a nested branch target.
		var walk func(node ast.Node, nested bool)
		walk = func(node ast.Node, nested bool) {
			ast.Inspect(node, func(cur ast.Node) bool {
				switch curNode := cur.(type) {
				case *ast.FuncLit:
					return false
				case *ast.BranchStmt:
					if curNode.Label != nil && curNode.Label.Name == labeled.Label.Name {
						if curNode.Tok == token.GOTO || nested {
							redundant = false
						}
					}
					return true
				}
				if cur != node && isBranchTargetStmt(cur) {
					walkTargetBody(cur)
					return false
				}
				return true
			})
		}
		var walkTargetBody func(node ast.Node)
		walkTargetBody = func(node ast.Node) {
			// Descend into a nested target marking branches
			// within it as nested.
			ast.Inspect(node, func(cur ast.Node) bool {
				if branch, ok := cur.(*ast.BranchStmt); ok && branch.Label != nil && branch.Label.Name == labeled.Label.Name {
					redundant = false
					return false
				}
				if _, ok := cur.(*ast.FuncLit); ok {
					return false
				}
				return true
			})
		}
		_ = walkTargetBody
		walk(target, false)
		if redundant {
			ctx.warn(labeled, "label %s is redundant", labeled.Label.Name)
		}
		return true
	})
}
