package main

import (
	"go/ast"
	"go/token"
	"go/types"
	"strings"
)

func init() {
	checkerFactories["unnamedResult"] = func(p *checkerParams) checkerInstance {
		return funcChecker{fn: func(ctx *runCtx, file *ast.File) { checkUnnamedResult(ctx, file, p) }}
	}
	checkerFactories["unnecessaryBlock"] = simple(checkUnnecessaryBlock)
	checkerFactories["unnecessaryDefer"] = simple(checkUnnecessaryDefer)
	checkerFactories["weakCond"] = simple(checkWeakCond)
	checkerFactories["whyNoLint"] = simple(checkWhyNoLint)
	checkerFactories["yodaStyleExpr"] = simple(checkYodaStyleExpr)
}

// unnamedResult --------------------------------------------------------

func checkUnnamedResult(ctx *runCtx, file *ast.File, p *checkerParams) {
	for _, decl := range file.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok || fn.Type == nil || fn.Type.Results == nil {
			continue
		}
		if p.unnamedResultCheckExported && !ast.IsExported(fn.Name.Name) {
			continue
		}
		seen := make(map[types.Type]bool)
		hasDup := false
		for _, field := range fn.Type.Results.List {
			if len(field.Names) != 0 {
				continue
			}
			t := ctx.typeOf(field.Type)
			if t == nil {
				continue
			}
			if seen[t] {
				hasDup = true
				break
			}
			seen[t] = true
		}
		if hasDup {
			ctx.warn(fn, "consider giving a name to these results")
		}
	}
}

// unnecessaryBlock -----------------------------------------------------

func blockHasImmediateDefinition(block *ast.BlockStmt) bool {
	for _, stmt := range block.List {
		switch node := stmt.(type) {
		case *ast.AssignStmt:
			if node.Tok == token.DEFINE {
				return true
			}
		case *ast.DeclStmt:
			if _, ok := node.Decl.(*ast.GenDecl); ok {
				return true
			}
		}
	}
	return false
}

func checkUnnecessaryBlock(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		block, ok := n.(*ast.BlockStmt)
		if !ok {
			return true
		}
		for _, stmt := range block.List {
			if inner, ok := stmt.(*ast.BlockStmt); ok && !blockHasImmediateDefinition(inner) {
				ctx.warn(inner, "block doesn't have definitions, can be simply deleted")
			}
		}
		return true
	})
}

// unnecessaryDefer -----------------------------------------------------

func checkUnnecessaryDeferInBody(ctx *runCtx, body *ast.BlockStmt) {
	if body == nil || len(body.List) == 0 {
		return
	}
	idx := len(body.List) - 1
	if _, isReturn := body.List[idx].(*ast.ReturnStmt); isReturn {
		idx--
	}
	if idx < 0 {
		return
	}
	if def, ok := body.List[idx].(*ast.DeferStmt); ok {
		ctx.warn(def, "%s is placed just before return", deferCallText(ctx, def))
	}
}

func checkUnnecessaryDefer(ctx *runCtx, file *ast.File) {
	for _, decl := range file.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok || fn.Body == nil {
			continue
		}
		checkUnnecessaryDeferInBody(ctx, fn.Body)
		ast.Inspect(fn.Body, func(n ast.Node) bool {
			if lit, ok := n.(*ast.FuncLit); ok {
				checkUnnecessaryDeferInBody(ctx, lit.Body)
			}
			return true
		})
	}
}

// weakCond -------------------------------------------------------------

func containsIndexOn(expr ast.Expr, target ast.Expr) bool {
	found := false
	ast.Inspect(expr, func(n ast.Node) bool {
		if idx, ok := n.(*ast.IndexExpr); ok && exprEqual(idx.X, target) {
			found = true
			return false
		}
		return !found
	})
	return found
}

func checkWeakCond(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok || (bin.Op != token.LAND && bin.Op != token.LOR) {
			return true
		}
		left, ok := bin.X.(*ast.BinaryExpr)
		if !ok || identName(left.Y) != "nil" {
			return true
		}
		if !((bin.Op == token.LAND && left.Op == token.NEQ) || (bin.Op == token.LOR && left.Op == token.EQL)) {
			return true
		}
		if _, isSlice := ctx.typeOf(left.X).Underlying().(*types.Slice); !isSlice {
			// ctx.typeOf may be nil; Underlying on a nil
			// interface is safe to call through the guard
			// below in real code paths where types resolve.
			if ctx.typeOf(left.X) == nil {
				return true
			}
			return true
		}
		if containsIndexOn(bin.Y, left.X) {
			ctx.warn(bin, "suspicious `%s`; nil check may not be enough, check for len", ctx.nodeText(bin))
		}
		return true
	})
}

// whyNoLint ------------------------------------------------------------

func checkWhyNoLint(ctx *runCtx, file *ast.File) {
	for _, group := range file.Comments {
		for _, comment := range group.List {
			text := comment.Text
			var body string
			if strings.HasPrefix(text, "//") {
				body = strings.TrimLeft(text[2:], " \t")
			} else if strings.HasPrefix(text, "/*") && strings.HasSuffix(text, "*/") {
				body = strings.TrimLeft(text[2:len(text)-2], " \t")
			} else {
				continue
			}
			if !strings.HasPrefix(body, "nolint") {
				continue
			}
			rest := body[len("nolint"):]
			idx := strings.Index(rest, "//")
			if idx < 0 || strings.TrimSpace(rest[idx+2:]) == "" {
				ctx.warnAt(comment.Slash, "include an explanation for nolint directive")
			}
		}
	}
}

