func isYodaConstant(ctx *runCtx, expr ast.Expr) bool {
	if _, ok := expr.(*ast.BasicLit); ok {
		return true
	}
	return identName(expr) == "nil"
}

func checkYodaStyleExpr(ctx *runCtx, file *ast.File) {
	ast.Inspect(file, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok || (bin.Op != token.EQL && bin.Op != token.NEQ) {
			return true
		}
		if isYodaConstant(ctx, bin.X) && !ctx.isConstantExpr(bin.Y) && identName(bin.Y) != "nil" {
			ctx.warn(bin, "consider to change order in expression to %s %s %s", ctx.nodeText(bin.Y), bin.Op.String(), ctx.nodeText(bin.X))
		}
		return true
	})
}
