{"command":"cat > regex_ast.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
	"unicode/utf8"
)

// A small regular-expression AST and parser.  It is deliberately
// tolerant: constructs the RE2 parser would reject (such as a
// repeated quantifier in a**) are represented structurally because
// badRegexp is expected to diagnose them.

type reKind int

const (
	reEmpty reKind = iota
	reLiteralRune // a single literal rune; Text is the source spelling
	reAnyChar
	rePerlClass // Text includes the backslash, e.g. \d ; also \p{...}
	reAnchor    // Text is ^, $, \b, ...
	reCharClass
	reGroup
	reConcat
	reAlt
	reRepeat
	reFlags // (?i) and friends; Text is the full source spelling
)

type reClassElem struct {
	Text   string // source spelling of this element
	Kind   int    // 0 rune, 1 range, 2 perl class, 3 posix class
	Lo, Hi rune
	Perl   byte // d/D/w/W/s/S for perl classes
}

func (e *reClassElem) ranges() [][2]rune {
	switch e.Kind {
	case 0:
		return [][2]rune{{e.Lo, e.Lo}}
	case 1:
		if e.Lo > e.Hi {
			return nil
		}
		return [][2]rune{{e.Lo, e.Hi}}
	case 2:
		return perlClassRanges(e.Perl)
	}
	return nil
}

func perlClassRanges(c byte) [][2]rune {
	var base [][2]rune
	switch c {
	case 'd', 'D':
		base = [][2]rune{{'0', '9'}}
	case 'w', 'W':
		base = [][2]rune{{'0', '9'}, {'A', 'Z'}, {'_', '_'}, {'a', 'z'}}
	case 's', 'S':
		base = [][2]rune{{'\t', '\n'}, {'\f', '\r'}, {' ', ' '}}
	default:
		return nil
	}
	if c == 'D' || c == 'W' || c == 'S' {
		return complementRanges(base)
	}
	return base
}

func complementRanges(in [][2]rune) [][2]rune {
	var out [][2]rune
	next := rune(0)
	for _, r := range in {
		if r[0] > next {
			out = append(out, [2]rune{next, r[0] - 1})
		}
		if r[1] >= next {
			next = r[1] + 1
		}
	}
	if next <= 0x10FFFF {
		out = append(out, [2]rune{next, 0x10FFFF})
	}
	return out
}

func rangesIntersect(a, b [][2]rune) bool {
	for _, x := range a {
		for _, y := range b {
			if x[0] <= y[1] && y[0] <= x[1] {
				return true
			}
		}
	}
	return false
}

type reNode struct {
	Kind     reKind
	Text     string // literal rune spelling, perl class, anchor, flags, named group prefix data
	Rune     rune   // for literal runes (when decodable)
	Children []*reNode
	Sub      *reNode

	// Char class.
	Negated  bool
	Elems    []*reClassElem
	ClassRaw string // full source spelling including brackets

	// Group.
	Capture bool
	Name    string
	Flags   string // e.g. "i" or "i-m" for (?flags:...) groups

	// Repeat.
	Min, Max int  // Max == -1 means unbounded
	Greedy   bool // false covers lazy and possessive as in the reference printer
	Braced   bool // quantifier was written with {..}
	RawQuant string
}

func (n *reNode) String() string {
	if n == nil {
		return ""
	}
	switch n.Kind {
	case reEmpty:
		return ""
	case reLiteralRune, rePerlClass, reAnchor, reFlags:
		return n.Text
	case reAnyChar:
		return "."
	case reCharClass:
		var b strings.Builder
		b.WriteByte('[')
		if n.Negated {
			b.WriteByte('^')
		}
		for _, e := range n.Elems {
			b.WriteString(e.Text)
		}
		b.WriteByte(']')
		return b.String()
	case reGroup:
		if n.Capture {
			if n.Name != "" {
				return "(?P<" + n.Name + ">" + n.Sub.String() + ")"
			}
			return "(" + n.Sub.String() + ")"
		}
		if n.Flags != "" {
			return "(?" + n.Flags + ":" + n.Sub.String() + ")"
		}
		return "(?:" + n.Sub.String() + ")"
	case reConcat:
		var b strings.Builder
		for _, c := range n.Children {
			b.WriteString(c.String())
		}
		return b.String()
	case reAlt:
		parts := make([]string, len(n.Children))
		for i, c := range n.Children {
			parts[i] = c.String()
		}
		return strings.Join(parts, "|")
	case reRepeat:
		inner := n.Sub.String()
		// The operand of a repeat needs grouping unless it is a
		// single atom or a group.
		if needsGroupForRepeat(n.Sub) {
			inner = "(?:" + inner + ")"
		}
		return inner + quantifierString(n)
	}
	return ""
}

func needsGroupForRepeat(n *reNode) bool {
	switch n.Kind {
	case reLiteralRune, reAnyChar, rePerlClass, reCharClass, reGroup:
		return false
	case reAnchor:
		return false
	}
	return true
}

func quantifierString(n *reNode) string {
	if n.Braced {
		if n.RawQuant != "" {
			return n.RawQuant
		}
		if n.Max == -1 {
			return fmt.Sprintf("{%d,}", n.Min)
		}
		if n.Min == n.Max {
			return fmt.Sprintf("{%d}", n.Min)
		}
		return fmt.Sprintf("{%d,%d}", n.Min, n.Max)
	}
	switch {
	case n.Min == 0 && n.Max == -1:
		return "*"
	case n.Min == 1 && n.Max == -1:
		return "+"
	case n.Min == 0 && n.Max == 1:
		return "?"
	default:
		return n.RawQuant
	}
}

type reParser struct {
	src string
	pos int
}

func parseRegexpPattern(src string) (*reNode, error) {
	p := &reParser{src: src}
	node, err := p.parseAlt()
	if err != nil {
		return nil, err
	}
	if p.pos != len(p.src) {
		return nil, fmt.Errorf("unexpected trailing %q", p.src[p.pos:])
	}
	return node, nil
}

func (p *reParser) peek() (byte, bool) {
	if p.pos >= len(p.src) {
		return 0, false
	}
	return p.src[p.pos], true
}

func (p *reParser) parseAlt() (*reNode, error) {
	var branches []*reNode
	for {
		branch, err := p.parseConcat()
		if err != nil {
			return nil, err
		}
		branches = append(branches, branch)
		if c, ok := p.peek(); ok && c == '|' {
			p.pos++
			continue
		}
		break
	}
	if len(branches) == 1 {
		return branches[0], nil
	}
	return &reNode{Kind: reAlt, Children: branches}, nil
}

func (p *reParser) parseConcat() (*reNode, error) {
	var items []*reNode
	for p.pos < len(p.src) {
		if c := p.src[p.pos]; c == '|' || c == ')' {
			break
		}
		atom, err := p.parseAtomWithQuantifiers()
		if err != nil {
			return nil, err
		}
		if atom != nil {
			items = append(items, atom)
		}
	}
	switch len(items) {
	case 0:
		return &reNode{Kind: reEmpty}, nil
	case 1:
		return items[0], nil
	default:
		return &reNode{Kind: reConcat, Children: items}, nil
	}
}

func (p *reParser) parseAtomWithQuantifiers() (*reNode, error) {
	atom, err := p.parseAtom()
	if err != nil {
		return nil, err
	}
	for {
		rep, isRepeat, err := p.tryParseQuantifier(atom)
		if err != nil {
			return nil, err
		}
		if !isRepeat {
			return atom, nil
		}
		atom = rep
	}
}

func (p *reParser) tryParseQuantifier(atom *reNode) (*reNode, bool, error) {
	// Anchors and flag directives do not take quantifiers.
	if atom.Kind == reAnchor || atom.Kind == reFlags {
		return atom, false, nil
	}
	if p.pos >= len(p.src) {
		return atom, false, nil
	}
	start := p.pos
	node := &reNode{Kind: reRepeat, Sub: atom, Greedy: true, Max: -1}
	switch p.src[p.pos] {
	case '*':
		node.Min, node.Max = 0, -1
		p.pos++
	case '+':
		node.Min, node.Max = 1, -1
		p.pos++
	case '?':
		node.Min, node.Max = 0, 1
		p.pos++
	case '{':
		end := strings.IndexByte(p.src[p.pos:], '}')
		if end < 0 {
			return atom, false, nil
		}
		body := p.src[p.pos+1 : p.pos+end]
		min, max, ok := parseBraceQuantifier(body)
		if !ok {
			return atom, false, nil
		}
		node.Min, node.Max, node.Braced = min, max, true
		node.RawQuant = p.src[p.pos : p.pos+end+1]
		p.pos += end + 1
	default:
		return atom, false, nil
	}
	// A following ? or + is the laziness/possessive marker, not a
	// second quantifier — but only when directly attached.
	if p.pos < len(p.src) && (p.src[p.pos] == '?' || p.src[p.pos] == '+') {
		node.Greedy = false
		p.pos++
		// Extend the raw quantifier spelling to include the
		// marker only for braced forms; for */+/? forms our
		// printer derives the quantifier from min/max and
		// (like the reference) drops the marker in messages.
		if node.Braced {
			node.RawQuant = p.src[start:p.pos]
		}
	}
	return node, true, nil
}

func parseBraceQuantifier(body string) (int, int, bool) {
	if idx := strings.IndexByte(body, ','); idx >= 0 {
		lo, hi := body[:idx], body[idx+1:]
		minv := 0
		var err error
		if lo != "" {
			minv, err = strconv.Atoi(lo)
			if err != nil {
				return 0, 0, false
			}
		}
		if hi == "" {
			return minv, -1, true
		}
		maxv, err := strconv.Atoi(hi)
		if err != nil {
			return 0, 0, false
		}
		return minv, maxv, true
	}
	v, err := strconv.Atoi(body)
	if err != nil {
		return 0, 0, false
	}
	return v, v, true
}

func (p *reParser) parseAtom() (*reNode, error) {
	c := p.src[p.pos]
	switch c {
	case '(':
		return p.parseGroup()
	case '[':
		return p.parseCharClassNode()
	case '.':
		p.pos++
		return &reNode{Kind: reAnyChar}, nil
	case '^':
		p.pos++
		return &reNode{Kind: reAnchor, Text: "^"}, nil
	case '$':
		p.pos++
		return &reNode{Kind: reAnchor, Text: "$"}, nil
	case '\\':
		return p.parseEscape(false)
	default:
		r, size := utf8.DecodeRuneInString(p.src[p.pos:])
		text := p.src[p.pos : p.pos+size]
		p.pos += size
		return &reNode{Kind: reLiteralRune, Text: text, Rune: r}, nil
	}
}

func (p *reParser) parseGroup() (*reNode, error) {
	start := p.pos
	p.pos++ // '('
	node := &reNode{Kind: reGroup, Capture: true}
	if p.pos < len(p.src) && p.src[p.pos] == '?' {
		p.pos++
		// Named capture: (?P<name>...) or (?<name>...)
		if p.pos < len(p.src) && (p.src[p.pos] == 'P' || p.src[p.pos] == '<') {
			if p.src[p.pos] == 'P' {
				p.pos++
			}
			if p.pos < len(p.src) && p.src[p.pos] == '<' {
				end := strings.IndexByte(p.src[p.pos:], '>')
				if end < 0 {
					return nil, fmt.Errorf("unterminated group name")
				}
				node.Name = p.src[p.pos+1 : p.pos+end]
				p.pos += end + 1
				inner, err := p.parseAlt()
				if err != nil {
					return nil, err
				}
				if err := p.expectClose(); err != nil {
					return nil, err
				}
				node.Sub = inner
				return node, nil
			}
			return nil, fmt.Errorf("bad named group")
		}
		node.Capture = false
		// Flags: letters and '-' up to ':' or ')'.
		flagStart := p.pos
		for p.pos < len(p.src) {
			ch := p.src[p.pos]
			if ch == ':' || ch == ')' {
				break
			}
			if !(ch >= 'a' && ch <= 'z' || ch == '-') {
				return nil, fmt.Errorf("bad group flags")
			}
			p.pos++
		}
		node.Flags = p.src[flagStart:p.pos]
		if p.pos < len(p.src) && p.src[p.pos] == ')' {
			p.pos++
			return &reNode{Kind: reFlags, Text: p.src[start:p.pos]}, nil
		}
		if p.pos >= len(p.src) || p.src[p.pos] != ':' {
			return nil, fmt.Errorf("bad group")
		}
		p.pos++ // ':'
	}
	inner, err := p.parseAlt()
	if err != nil {
		return nil, err
	}
	if err := p.expectClose(); err != nil {
		return nil, err
	}
	node.Sub = inner
	return node, nil
}

func (p *reParser) expectClose() error {
	if p.pos >= len(p.src) || p.src[p.pos] != ')' {
		return fmt.Errorf("missing closing )")
	}
	p.pos++
	return nil
}

// decodeEscapeRune decodes the rune after a backslash starting at
// p.pos (which must point just past the backslash).  It returns the
// rune, whether it decoded, and the raw source spelling including the
// leading backslash.
func (p *reParser) parseEscape(inClass bool) (*reNode, error) {
	start := p.pos
	p.pos++ // backslash
	if p.pos >= len(p.src) {
		return nil, fmt.Errorf("trailing backslash")
	}
	c := p.src[p.pos]
	switch c {
	case 'd', 'D', 'w', 'W', 's', 'S':
		p.pos++
		return &reNode{Kind: rePerlClass, Text: p.src[start:p.pos]}, nil
	case 'p', 'P':
		p.pos++
		if p.pos < len(p.src) && p.src[p.pos] == '{' {
			if end := strings.IndexByte(p.src[p.pos:], '}'); end >= 0 {
				p.pos += end + 1
			}
		} else if p.pos < len(p.src) {
			p.pos++
		}
		return &reNode{Kind: rePerlClass, Text: p.src[start:p.pos]}, nil
	case 'b':
		p.pos++
		if inClass {
			// Backspace inside a class.
			return &reNode{Kind: reLiteralRune, Text: p.src[start:p.pos], Rune: '\b'}, nil
		}
		return &reNode{Kind: reAnchor, Text: p.src[start:p.pos]}, nil
	case 'B', 'A', 'z':
		p.pos++
		return &reNode{Kind: reAnchor, Text: p.src[start:p.pos]}, nil
	}
	r, raw, ok := p.decodeEscapedRune(start)
	if !ok {
		// Treat any other escaped char as that literal char.
		r2, size := utf8.DecodeRuneInString(p.src[p.pos:])
		p.pos += size
		_ = r2
		return &reNode{Kind: reLiteralRune, Text: p.src[start:p.pos], Rune: r2}, nil
	}
	return &reNode{Kind: reLiteralRune, Text: raw, Rune: r}, nil
}

// decodeEscapedRune is called with p.pos just past the backslash and
// consumes an escape sequence that denotes one rune if it can.
func (p *reParser) decodeEscapedRune(start int) (rune, string, bool) {
	if p.pos >= len(p.src) {
		return 0, "", false
	}
	switch c := p.src[p.pos]; c {
	case 'n':
		p.pos++
		return '\n', p.src[start:p.pos], true
	case 'r':
		p.pos++
		return '\r', p.src[start:p.pos], true
	case 't':
		p.pos++
		return '\t', p.src[start:p.pos], true
	case 'f':
		p.pos++
		return '\f', p.src[start:p.pos], true
	case 'v':
		p.pos++
		return '\v', p.src[start:p.pos], true
	case 'a':
		p.pos++
		return '\a', p.src[start:p.pos], true
	case 'x':
		p.pos++
		if p.pos < len(p.src) && p.src[p.pos] == '{' {
			end := strings.IndexByte(p.src[p.pos:], '}')
			if end < 0 {
				return 0, "", false
			}
			v, err := strconv.ParseInt(p.src[p.pos+1:p.pos+end], 16, 32)
			if err != nil {
				return 0, "", false
			}
			p.pos += end + 1
			return rune(v), p.src[start:p.pos], true
		}
		if p.pos+2 <= len(p.src) {
			v, err := strconv.ParseInt(p.src[p.pos:p.pos+2], 16, 32)
			if err == nil {
				p.pos += 2
				return rune(v), p.src[start:p.pos], true
			}
		}
		return 0, "", false
	case '0', '1', '2', '3', '4', '5', '6', '7':
		end := p.pos
		for end < len(p.src) && end < p.pos+3 && p.src[end] >= '0' && p.src[end] <= '7' {
			end++
		}
		v, err := strconv.ParseInt(p.src[p.pos:end], 8, 32)
		if err != nil {
			return 0, "", false
		}
		p.pos = end
		return rune(v), p.src[start:p.pos], true
	}
	return 0, "", false
}

func (p *reParser) parseCharClassNode() (*reNode, error) {
	start := p.pos
	p.pos++ // '['
	node := &reNode{Kind: reCharClass}
	if p.pos < len(p.src) && p.src[p.pos] == '^' {
		node.Negated = true
		p.pos++
	}
	first := true
	for p.pos < len(p.src) {
		if p.src[p.pos] == ']' && !first {
			p.pos++
			node.ClassRaw = p.src[start:p.pos]
			return node, nil
		}
		first = false
		elem, err := p.parseClassElem()
		if err != nil {
			return nil, err
		}
		// Possible range.
		if elem.Kind == 0 && p.pos < len(p.src) && p.src[p.pos] == '-' && p.pos+1 < len(p.src) && p.src[p.pos+1] != ']' {
			elemStartText := elem.Text
			p.pos++ // '-'
			hi, err := p.parseClassSingleRune()
			if err == nil {
				elem.Kind = 1
				elem.Hi = hi.r
				elem.Text = elemStartText + "-" + hi.text
			} else {
				// Not a valid range endpoint; keep the
				// dash as its own literal element.
				node.Elems = append(node.Elems, elem)
				node.Elems = append(node.Elems, &reClassElem{Text: "-", Kind: 0, Lo: '-'})
				continue
			}
		}
		node.Elems = append(node.Elems, elem)
	}
	return nil, fmt.Errorf("unterminated character class")
}

type classRune struct {
	r    rune
	text string
}

func (p *reParser) parseClassSingleRune() (classRune, error) {
	if p.pos >= len(p.src) {
		return classRune{}, fmt.Errorf("bad class")
	}
	if p.src[p.pos] == '\\' {
		start := p.pos
		p.pos++
		if p.pos < len(p.src) && strings.IndexByte("dDwWsS", p.src[p.pos]) >= 0 {
			return classRune{}, fmt.Errorf("perl class as range endpoint")
		}
		if r, raw, ok := p.decodeEscapedRune(start); ok {
			return classRune{r, raw}, nil
		}
		r, size := utf8.DecodeRuneInString(p.src[p.pos:])
		p.pos += size
		return classRune{r, p.src[start:p.pos]}, nil
	}
	r, size := utf8.DecodeRuneInString(p.src[p.pos:])
	text := p.src[p.pos : p.pos+size]
	p.pos += size
	return classRune{r, text}, nil
}

func (p *reParser) parseClassElem() (*reClassElem, error) {
	// POSIX class [:name:]
	if p.pos+1 < len(p.src) && p.src[p.pos] == '[' && p.src[p.pos+1] == ':' {
		if end := strings.Index(p.src[p.pos:], ":]"); end >= 0 {
			text := p.src[p.pos : p.pos+end+2]
			p.pos += end + 2
			return &reClassElem{Text: text, Kind: 3}, nil
		}
	}
	if p.src[p.pos] == '\\' && p.pos+1 < len(p.src) && strings.IndexByte("dDwWsS", p.src[p.pos+1]) >= 0 {
		text := p.src[p.pos : p.pos+2]
		perl := p.src[p.pos+1]
		p.pos += 2
		return &reClassElem{Text: text, Kind: 2, Perl: perl}, nil
	}
	single, err := p.parseClassSingleRune()
	if err != nil {
		return nil, err
	}
	return &reClassElem{Text: single.text, Kind: 0, Lo: single.r, Hi: single.r}, nil
}
