	if n.Braced {
		if n.RawQuant != "" {
			return n.RawQuant
		}
		if n.Max == -1 {
			return fmt.Sprintf("{%d,}", n.Min)
		}
		if n.Min == n.Max {
			return fmt.Sprintf("{%d}", n.Min)
		}
		return fmt.Sprintf("{%d,%d}", n.Min, n.Max)
