type reParser struct {
	src string
	pos int
}

func parseRegexpPattern(src string) (*reNode, error) {
	p := &reParser{src: src}
	node, err := p.parseAlt()
	if err != nil {
		return nil, err
	}
	if p.pos != len(p.src) {
		return nil, fmt.Errorf("unexpected trailing %q", p.src[p.pos:])
	}
	return node, nil
}

func (p *reParser) peek() (byte, bool) {
	if p.pos >= len(p.src) {
		return 0, false
	}
	return p.src[p.pos], true
