func (p *reParser) parseConcat() (*reNode, error) {
	var items []*reNode
	for p.pos < len(p.src) {
		if c := p.src[p.pos]; c == '|' || c == ')' {
			break
		}
		atom, err := p.parseAtomWithQuantifiers()
		if err != nil {
			return nil, err
		}
		if atom != nil {
			items = append(items, atom)
		}
	}
	switch len(items) {
	case 0:
		return &reNode{Kind: reEmpty}, nil
	case 1:
		return items[0], nil
	default:
