// --- badRegexp --------------------------------------------------------

func concatChildren(node *reNode) []*reNode {
	if node.Kind == reConcat {
		return node.Children
	}
	return []*reNode{node}
}

func checkBadRegexp(ctx *runCtx, file *ast.File) {
	forEachRegexpPattern(ctx, file, func(arg ast.Expr, pattern string, root *reNode) {
		var walk func(node *reNode)
		walk = func(node *reNode) {
			if node == nil {
				return
			}
			switch node.Kind {
			case reAlt:
				// Duplicated alternatives.
				seen := make(map[string]bool)
				for _, branch := range node.Children {
					text := branch.String()
					if seen[text] {
						ctx.warn(arg, "`%s` is duplicated in %s", text, node.String())
					}
					seen[text] = true
				}
				// Anchors applied to only one alternative.
				if len(node.Children) > 1 {
					first := concatChildren(node.Children[0])
					last := concatChildren(node.Children[len(node.Children)-1])
					firstHasCaret := len(first) > 0 && first[0].Kind == reAnchor && first[0].Text == "^"
					lastHasDollar := len(last) > 0 && last[len(last)-1].Kind == reAnchor && last[len(last)-1].Text == "$"
					if firstHasCaret != lastHasDollar {
						if firstHasCaret {
							branchText := (&reNode{Kind: reConcat, Children: first[1:]}).String()
							if len(first) == 1 {
								branchText = ""
							}
							ctx.warn(arg, "^ applied only to `%s` in %s", branchText, node.String())
						}
						if lastHasDollar {
							branchText := (&reNode{Kind: reConcat, Children: last[:len(last)-1]}).String()
							if len(last) == 1 {
								branchText = ""
							}
							ctx.warn(arg, "$ applied only to `%s` in %s", branchText, node.String())
						}
					}
				}
				for _, child := range node.Children {
					walk(child)
				}
			case reConcat:
				for i, child := range node.Children {
					if i > 0 && child.Kind == reAnchor && child.Text == "^" {
						ctx.warn(arg, "dangling or redundant ^, maybe \\^ is intended?")
					}
					walk(child)
				}
			case reCharClass:
				for j := 1; j < len(node.Elems); j++ {
					for i := 0; i < j; i++ {
						a, b := node.Elems[i], node.Elems[j]
						if a.Text == b.Text {
							ctx.warn(arg, "`%s` is duplicated in %s", b.Text, node.String())
							break
						}
						ar, br := a.ranges(), b.ranges()
						if ar != nil && br != nil && rangesIntersect(ar, br) {
							ctx.warn(arg, "`%s` intersects with `%s` in %s", a.Text, b.Text, node.String())
							break
						}
					}
				}
			case reRepeat:
				if isStarPlusRepeat(node) {
					inner := node.Sub
					for inner != nil && inner.Kind == reGroup {
