func isStarPlusRepeat(node *reNode) bool {
	if node.Kind != reRepeat || node.Braced {
		return false
	}
	return (node.Min == 0 && node.Max == -1) || (node.Min == 1 && node.Max == -1)
}

// --- regexpPattern ----------------------------------------------------

var regexpPatternTLDs = []string{"com", "net", "org", "ru", "de", "info"}

func checkRegexpPattern(ctx *runCtx, file *ast.File) {
	forEachRegexpPattern(ctx, file, func(arg ast.Expr, pattern string, root *reNode) {
		found := ""
		var walk func(node *reNode)
		walk = func(node *reNode) {
			if node == nil || found != "" {
				return
			}
			if node.Kind == reConcat || node.Kind == reAlt {
				if node.Kind == reConcat {
					items := node.Children
					for i, item := range items {
						if item.Kind != reAnyChar {
							continue
						}
						// Gather following literal runes.
						var sb strings.Builder
						for j := i + 1; j < len(items) && items[j].Kind == reLiteralRune; j++ {
							sb.WriteRune(items[j].Rune)
						}
						text := sb.String()
						for _, tld := range regexpPatternTLDs {
							if text == tld || strings.HasPrefix(text, tld) && len(text) > len(tld) && !isLetterOrDigit(rune(text[len(tld)])) {
								found = tld
								return
							}
						}
					}
				}
				for _, child := range node.Children {
					walk(child)
				}
				return
			}
			for _, child := range node.Children {
				walk(child)
			}
			if node.Sub != nil {
				walk(node.Sub)
			}
		}
		// Also handle a root that is a bare concatenation in a
		// single node (already covered) and simple wrappers.
		walk(root)
		if found != "" {
			ctx.warn(arg, "'.%s' should probably be '\\.%s'", found, found)
		}
	})
}

func isLetterOrDigit(r rune) bool {
	return r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9'
}

// --- regexpSimplify ---------------------------------------------------

func checkRegexpSimplify(ctx *runCtx, file *ast.File) {
	forEachRegexpPattern(ctx, file, func(arg ast.Expr, pattern string, root *reNode) {
		simplified, changed := simplifyRe(root, false)
		if changed {
			ctx.warn(arg, "can re-write `%s` as `%s`", pattern, simplified.String())
		}
	})
}

func isAtomNode(n *reNode) bool {
	switch n.Kind {
	case reLiteralRune, reAnyChar, rePerlClass, reCharClass:
		return true
	}
	return false
}

func simplifyRe(node *reNode, repeatOperand bool) (*reNode, bool) {
	if node == nil {
		return node, false
	}
	switch node.Kind {
	case reGroup:
		sub, changed := simplifyRe(node.Sub, false)
		if !node.Capture && node.Flags == "" && isAtomNode(sub) {
			return sub, true
		}
		if changed {
			out := *node
			out.Sub = sub
			return &out, true
		}
		return node, false
	case reRepeat:
		sub, changed := simplifyRe(node.Sub, true)
		out := *node
		out.Sub = sub
		if node.Braced {
			switch {
			case node.Min == 1 && node.Max == 1:
				return sub, true
			case node.Min == 1 && node.Max == -1:
				out.Braced, out.RawQuant = false, ""
				return &out, true
			case node.Min == 0 && node.Max == -1:
				out.Braced, out.RawQuant = false, ""
				return &out, true
			case node.Min == 0 && node.Max == 1:
				out.Braced, out.RawQuant = false, ""
				return &out, true
			}
		}
		return &out, changed
	case reAlt:
		changed := false
		children := make([]*reNode, len(node.Children))
		allSingleRunes := len(node.Children) > 0
		for i, child := range node.Children {
			s, c := simplifyRe(child, false)
			children[i] = s
			if c {
				changed = true
			}
			if s.Kind != reLiteralRune {
				allSingleRunes = false
			}
		}
		if allSingleRunes && len(children) >= 2 {
			elems := make([]*reClassElem, len(children))
			for i, child := range children {
				elems[i] = &reClassElem{Text: classRuneText(child.Rune), Kind: 0, Lo: child.Rune, Hi: child.Rune}
			}
			return &reNode{Kind: reCharClass, Elems: elems}, true
		}
		out := *node
		out.Children = children
		return &out, changed
	case reConcat:
		return simplifyConcat(node)
	case reCharClass:
		return simplifyCharClass(node)
	default:
		return node, false
	}
}

func classRuneText(r rune) string {
	switch r {
	case ']', '\\', '-', '^':
		return "\\" + string(r)
	default:
		return string(r)
	}
}

func simplifyCharClass(node *reNode) (*reNode, bool) {
	if len(node.Elems) == 1 {
		elem := node.Elems[0]
		if !node.Negated {
			if elem.Kind == 2 {
				return &reNode{Kind: rePerlClass, Text: elem.Text}, true
			}
			if elem.Kind == 1 && elem.Lo == '0' && elem.Hi == '9' {
				return &reNode{Kind: rePerlClass, Text: "\\d"}, true
			}
		} else if elem.Kind == 2 {
			switch elem.Perl {
			case 'd':
				return &reNode{Kind: rePerlClass, Text: "\\D"}, true
			case 'w':
				return &reNode{Kind: rePerlClass, Text: "\\W"}, true
			case 's':
				return &reNode{Kind: rePerlClass, Text: "\\S"}, true
			}
		}
