		return node, false
	}
	out := *node
	out.Elems = elems
	return &out, true
}

func simplifyConcat(node *reNode) (*reNode, bool) {
	changed := false
	var items []*reNode
	for _, child := range node.Children {
		s, c := simplifyRe(child, false)
		if c {
			changed = true
		}
		items = append(items, s)
