			changed = true
		} else {
			outItems = append(outItems, step1[i:j]...)
		}
		i = j
	}
	if !changed {
		return node, false
	}
	if len(outItems) == 1 {
		return outItems[0], true
	}
	return &reNode{Kind: reConcat, Children: outItems}, true
}
