{"command":"cat > checker_ruleguard.go <<'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

func init() {
	checkerFactories["ruleguard"] = func(p *checkerParams) checkerInstance {
		return &ruleguardChecker{params: p}
	}
}

type rgEngineState int

const (
	rgNoop rgEngineState = iota
	rgLoaded
	rgEmptyFailed
	rgGlobErrorNoop
)

type rgEngine struct {
	state  rgEngineState
	groups []*rgGroup
}

type rgGroup struct {
	name    string
	rules   []*rgRule
	imports map[string]string // local name (or last path element) -> path
	file    string
}

type rgRule struct {
	patternText string
	pattern     ast.Node
	report      string
	hasReport   bool
	atVar       string
	where       []ast.Expr
	group       *rgGroup
	locals      map[string]ast.Expr // rule-function local assignments by name
}

// initRuleguardEngine loads rule files.  A non-nil error is a fatal
// initialization failure whose text already starts with
// "ruleguard init error: ".
func initRuleguardEngine(p *checkerParams) (*rgEngine, error) {
	if p.ruleguardRules == "" {
		return &rgEngine{state: rgNoop}, nil
	}
	failDSL, failImport, err := parseRuleguardFailOn(p)
	_ = failImport
	if err != nil {
		return nil, err
	}
	engine := &rgEngine{state: rgLoaded}
	loadedOK := false
	attempted := false
	for _, pattern := range strings.Split(p.ruleguardRules, ",") {
		matches, globErr := filepath.Glob(pattern)
		if globErr != nil {
			// filepath.Glob only fails for a bad pattern;
			// its error text is "syntax error in pattern".
			fmt.Fprintf(os.Stderr, "ruleguard init error: %s\n", globErr)
			return &rgEngine{state: rgGlobErrorNoop}, nil
		}
		if len(matches) == 0 {
			return nil, fmt.Errorf("ruleguard init error: no file matching '%s'", pattern)
		}
		sort.Strings(matches)
		for _, filename := range matches {
			attempted = true
			groups, loadErr := loadRuleguardFile(filename)
			if loadErr != nil {
				if failDSL {
					return nil, fmt.Errorf("ruleguard init error: %s", loadErr)
				}
