	}
	return nil
}

// A call chain is a sequence of selector calls.  We decompose it
// into (base, [(name,args), ...]) from the inside out.
type chainLink struct {
	name string
	args []ast.Expr
	call *ast.CallExpr
}

func decomposeChain(call *ast.CallExpr) (ast.Expr, []chainLink) {
	var links []chainLink
	cur := ast.Expr(call)
	for {
		c, ok := cur.(*ast.CallExpr)
		if !ok {
			break
		}
		sel, ok := c.Fun.(*ast.SelectorExpr)
		if !ok {
			break
		}
		links = append([]chainLink{{sel.Sel.Name, c.Args, c}}, links...)
		cur = sel.X
	}
	return cur, links
}

