	lit, ok := expr.(*ast.BasicLit)
	if !ok || lit.Kind != token.STRING {
		return "", false
	}
	s, err := strconv.Unquote(lit.Value)
	return s, err == nil
}

func interpretRuleCallChain(group *rgGroup, fn *ast.FuncDecl, matcherName string, call *ast.CallExpr, locals map[string]ast.Expr, fset *token.FileSet) error {
	base, links := decomposeChain(call)
	if identName(base) != matcherName || len(links) == 0 {
		return nil
	}
	first := links[0]
	switch first.name {
	case "Import":
		if len(first.args) == 1 {
			if path, ok := stringLitValue(first.args[0]); ok {
				group.imports[pathBase(path)] = path
			}
		}
		return nil
	case "ImportAs":
		if len(first.args) == 2 {
			if path, ok := stringLitValue(first.args[0]); ok {
				if local, ok := stringLitValue(first.args[1]); ok {
					group.imports[local] = path
				}
			}
		}
		return nil
	case "Match", "MatchAt":
		if len(first.args) == 0 {
			return nil
		}
		patternText, ok := stringLitValue(first.args[0])
		if !ok {
			return nil
		}
		patternNode, err := parseRuleguardPattern(patternText)
		if err != nil {
			line := fset.Position(first.call.Pos()).Line
			return fmt.Errorf("%s:%d: parse match pattern: %s", group.file, line, err)
		}
		rule := &rgRule{patternText: patternText, pattern: patternNode, group: group, locals: copyLocals(locals)}
		for _, link := range links[1:] {
			switch link.name {
			case "Report":
				if len(link.args) == 1 {
					if msg, ok := stringLitValue(link.args[0]); ok {
						rule.report, rule.hasReport = msg, true
					}
				}
			case "Where":
				rule.where = append(rule.where, link.args...)
			case "At":
				if len(link.args) == 1 {
					if name, ok := matcherIndexName(link.args[0], matcherName); ok {
						rule.atVar = name
					}
				}
			case "Suggest":
				// Suggestions are not surfaced in go-critic warnings.
			}
		}
		group.rules = append(group.rules, rule)
		return nil
	}
	return nil
}

func copyLocals(in map[string]ast.Expr) map[string]ast.Expr {
	out := make(map[string]ast.Expr, len(in))
	for k, v := range in {
		out[k] = v
	}
	return out
}

func matcherIndexName(expr ast.Expr, matcherName string) (string, bool) {
	idx, ok := expr.(*ast.IndexExpr)
	if !ok || identName(idx.X) != matcherName {
		return "", false
	}
	return stringLitValue(idx.Index)
}

type ruleguardChecker struct{ params *checkerParams }

func (c *ruleguardChecker) CheckFile(ctx *runCtx, file *ast.File) {
	engine := ctx.prog.ruleguardEngine
	if engine == nil {
		return
	}
	switch engine.state {
	case rgNoop, rgGlobErrorNoop:
		return
	case rgEmptyFailed:
		ctx.warnAt(file.Package, "execution error: used Run() with an empty rule set; forgot to call Load() first?")
		return
	}
	for _, group := range engine.groups {
		applyRuleGroup(ctx, file, group)
	}
}
