		for _, name := range strings.Split(p.ruleguardEnable, ",") {
			enabled[name] = true
		}
	}
	var out []*rgGroup
	for _, g := range groups {
		if disabled[g.name] {
			continue
		}
		if enabled != nil && !enabled[g.name] {
			continue
		}
		out = append(out, g)
	}
	return out
}

func loadRuleguardFile(filename string) ([]*rgGroup, error) {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, filename, nil, parser.ParseComments)
	if err != nil {
		return nil, fmt.Errorf("parse file error: %s", err)
	}
	// Type-check to faithfully surface import and DSL signature
	// errors the same way the reference engine does.
	conf := types.Config{Importer: importer.Default(), FakeImportC: true}
	if _, err := conf.Check(file.Name.Name, fset, []*ast.File{file}, nil); err != nil {
		return nil, fmt.Errorf("typechecker error: %s", err)
	}
	var groups []*rgGroup
	for _, decl := range file.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok || fn.Recv != nil || fn.Body == nil || fn.Type == nil || fn.Type.Params == nil {
			continue
		}
		matcherName, isRule := ruleMatcherParam(fn)
		if !isRule {
			continue
		}
		group := &rgGroup{name: fn.Name.Name, imports: make(map[string]string), file: filename}
		locals := make(map[string]ast.Expr)
		for _, stmt := range fn.Body.List {
			if err := interpretRuleStatement(group, fn, matcherName, stmt, locals, fset); err != nil {
				return nil, err
			}
		}
		groups = append(groups, group)
	}
	return groups, nil
}

func ruleMatcherParam(fn *ast.FuncDecl) (string, bool) {
	if len(fn.Type.Params.List) != 1 {
		return "", false
	}
	field := fn.Type.Params.List[0]
	if len(field.Names) != 1 {
		return "", false
	}
	sel, ok := field.Type.(*ast.SelectorExpr)
	if !ok || sel.Sel.Name != "Matcher" {
		return "", false
	}
	return field.Names[0].Name, true
}

func interpretRuleStatement(group *rgGroup, fn *ast.FuncDecl, matcherName string, stmt ast.Stmt, locals map[string]ast.Expr, fset *token.FileSet) error {
	switch st := stmt.(type) {
	case *ast.AssignStmt:
		// Remember simple local aliases, e.g. x := m["x"].
		if len(st.Lhs) == len(st.Rhs) {
			for i, lhs := range st.Lhs {
				if id, ok := lhs.(*ast.Ident); ok {
					locals[id.Name] = st.Rhs[i]
				}
			}
		}
		return nil
	case *ast.ExprStmt:
		call, ok := st.X.(*ast.CallExpr)
		if !ok {
			return nil
		}
		return interpretRuleCallChain(group, fn, matcherName, call, locals, fset)
	}
	return nil
}

// A call chain is a sequence of selector calls.  We decompose it
// into (base, [(name,args), ...]) from the inside out.
type chainLink struct {
	name string
	args []ast.Expr
	call *ast.CallExpr
}

func decomposeChain(call *ast.CallExpr) (ast.Expr, []chainLink) {
	var links []chainLink
	cur := ast.Expr(call)
	for {
		c, ok := cur.(*ast.CallExpr)
		if !ok {
			break
		}
		sel, ok := c.Fun.(*ast.SelectorExpr)
		if !ok {
			break
		}
		links = append([]chainLink{{sel.Sel.Name, c.Args, c}}, links...)
		cur = sel.X
	}
	return cur, links
}

func stringLitValue(expr ast.Expr) (string, bool) {
	lit, ok := expr.(*ast.BasicLit)
	if !ok || lit.Kind != token.STRING {
		return "", false
	}
	s, err := strconv.Unquote(lit.Value)
	return s, err == nil
}

func interpretRuleCallChain(group *rgGroup, fn *ast.FuncDecl, matcherName string, call *ast.CallExpr, locals map[string]ast.Expr, fset *token.FileSet) error {
	base, links := decomposeChain(call)
	if identName(base) != matcherName || len(links) == 0 {
		return nil
	}
	first := links[0]
	switch first.name {
	case "Import":
		if len(first.args) == 1 {
			if path, ok := stringLitValue(first.args[0]); ok {
				group.imports[pathBase(path)] = path
			}
		}
		return nil
	case "ImportAs":
		if len(first.args) == 2 {
			if path, ok := stringLitValue(first.args[0]); ok {
				if local, ok := stringLitValue(first.args[1]); ok {
					group.imports[local] = path
				}
			}
		}
		return nil
	case "Match", "MatchAt":
		if len(first.args) == 0 {
			return nil
		}
		patternText, ok := stringLitValue(first.args[0])
		if !ok {
			return nil
		}
		patternNode, err := parseRuleguardPattern(patternText)
		if err != nil {
			line := fset.Position(first.call.Pos()).Line
			return fmt.Errorf("%s:%d: parse match pattern: %s", group.file, line, err)
		}
		rule := &rgRule{patternText: patternText, pattern: patternNode, group: group, locals: copyLocals(locals)}
		for _, link := range links[1:] {
			switch link.name {
			case "Report":
				if len(link.args) == 1 {
					if msg, ok := stringLitValue(link.args[0]); ok {
						rule.report, rule.hasReport = msg, true
					}
				}
			case "Where":
				rule.where = append(rule.where, link.args...)
			case "At":
				if len(link.args) == 1 {
					if name, ok := matcherIndexName(link.args[0], matcherName); ok {
						rule.atVar = name
					}
				}
			case "Suggest":
				// Suggestions are not surfaced in go-critic warnings.
			}
		}
		group.rules = append(group.rules, rule)
		return nil
	}
	return nil
}

func copyLocals(in map[string]ast.Expr) map[string]ast.Expr {
	out := make(map[string]ast.Expr, len(in))
	for k, v := range in {
		out[k] = v
	}
	return out
}

func matcherIndexName(expr ast.Expr, matcherName string) (string, bool) {
	idx, ok := expr.(*ast.IndexExpr)
	if !ok || identName(idx.X) != matcherName {
		return "", false
	}
	return stringLitValue(idx.Index)
}

type ruleguardChecker struct{ params *checkerParams }

func (c *ruleguardChecker) CheckFile(ctx *runCtx, file *ast.File) {
	engine := ctx.prog.ruleguardEngine
	if engine == nil {
		return
	}
	switch engine.state {
	case rgNoop, rgGlobErrorNoop:
		return
	case rgEmptyFailed:
		ctx.warnAt(file.Package, "execution error: used Run() with an empty rule set; forgot to call Load() first?")
		return
	}
	for _, group := range engine.groups {
		applyRuleGroup(ctx, file, group)
	}
}
