package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"reflect"
	"strings"
	"unicode"
)

// --- pattern parsing ---------------------------------------------------

func transformRuleguardPattern(src string) string {
	var out strings.Builder
	varCount := 0
	i := 0
	for i < len(src) {
		c := src[i]
		// String / char / raw literals and comments: copy verbatim.
		if c == '"' || c == '\'' {
			quote := c
			out.WriteByte(c)
			i++
			for i < len(src) {
				out.WriteByte(src[i])
				if src[i] == '\\' && i+1 < len(src) {
					i++
					out.WriteByte(src[i])
					i++
					continue
				}
				if src[i] == quote {
					i++
					break
				}
				i++
			}
			continue
		}
		if c == '`' {
			end := strings.IndexByte(src[i+1:], '`')
			if end < 0 {
				out.WriteString(src[i:])
				break
			}
			out.WriteString(src[i : i+end+2])
			i += end + 2
			continue
		}
		if c == '/' && i+1 < len(src) && src[i+1] == '/' {
			end := strings.IndexByte(src[i:], '\n')
			if end < 0 {
				out.WriteString(src[i:])
				break
			}
			out.WriteString(src[i : i+end])
			i += end
			continue
		}
		if c == '/' && i+1 < len(src) && src[i+1] == '*' {
			end := strings.Index(src[i+2:], "*/")
			if end < 0 {
				out.WriteString(src[i:])
				break
			}
			out.WriteString(src[i : i+end+4])
			i += end + 4
			continue
		}
		if c == '$' {
			j := i + 1
			isList := false
			if j < len(src) && src[j] == '*' {
				isList = true
				j++
			}
			start := j
			for j < len(src) {
				r := rune(src[j])
				if r == '_' || unicode.IsLetter(r) || j > start && unicode.IsDigit(r) {
					j++
					continue
				}
				break
			}
			name := src[start:j]
			if name == "" {
				varCount++
				fmt.Fprintf(&out, "__rg_wild_%d", varCount)
				i = j
				continue
			}
			if name == "_" && !isList {
				varCount++
				fmt.Fprintf(&out, "__rg_wild_%d", varCount)
			} else if isList {
				out.WriteString("__rg_list_" + name)
			} else {
				out.WriteString("__rg_var_" + name)
			}
			i = j
			continue
		}
		out.WriteByte(c)
		i++
	}
	return out.String()
}

func parseRuleguardPattern(src string) (ast.Node, error) {
	transformed := transformRuleguardPattern(src)
	fset := token.NewFileSet()
	if expr, err := parser.ParseExprFrom(fset, "pattern", transformed, parser.SkipObjectResolution); err == nil {
		return expr, nil
	} else {
		// Try as statements/declarations inside a function body.
		wrapped := "package _\nfunc _(){\n" + transformed + "\n}"
		file, ferr := parser.ParseFile(fset, "pattern", wrapped, parser.SkipObjectResolution)
		if ferr == nil && len(file.Decls) == 1 {
			if fn, ok := file.Decls[0].(*ast.FuncDecl); ok && fn.Body != nil && len(fn.Body.List) > 0 {
				if len(fn.Body.List) == 1 {
					return fn.Body.List[0], nil
				}
				return fn.Body, nil
			}
		}
		return nil, fmt.Errorf("cannot parse expr: %s", err)
	}
}

// --- matching ----------------------------------------------------------

type rgMatchEnv struct {
	vars  map[string]ast.Node
	lists map[string][]ast.Node
}

func newRgMatchEnv() *rgMatchEnv {
	return &rgMatchEnv{vars: make(map[string]ast.Node), lists: make(map[string][]ast.Node)}
}

func (e *rgMatchEnv) clone() *rgMatchEnv {
	out := newRgMatchEnv()
	for k, v := range e.vars {
		out.vars[k] = v
	}
	for k, v := range e.lists {
		out.lists[k] = append([]ast.Node{}, v...)
	}
	return out
}

func (e *rgMatchEnv) commit(other *rgMatchEnv) {
	e.vars = other.vars
	e.lists = other.lists
}

type rgMatcher struct {
	ctx *runCtx
}

func placeholderKind(name string) (kind, varName string) {
	if strings.HasPrefix(name, "__rg_var_") {
		return "var", strings.TrimPrefix(name, "__rg_var_")
	}
	if strings.HasPrefix(name, "__rg_list_") {
		return "list", strings.TrimPrefix(name, "__rg_list_")
	}
	if strings.HasPrefix(name, "__rg_wild_") {
		return "wild", ""
	}
	return "", ""
}

func (m *rgMatcher) nodesText(node ast.Node) string {
	if node == nil {
		return ""
	}
	// Prefer source text for nodes from the target file.
	if expr, ok := node.(ast.Expr); ok {
		if text := m.ctx.nodeText(expr); text != "" {
			return normalizeWS(text)
		}
	}
	if stmt, ok := node.(ast.Stmt); ok {
		// nodeText only accepts Expr in this codebase through
		// format fallback; use prettyText for statements.
		return normalizeWS(m.ctx.prettyText(stmt))
	}
	return normalizeWS(m.ctx.prettyText(node))
}

func (m *rgMatcher) nodesEqual(a, b ast.Node) bool {
	return m.nodesText(a) == m.nodesText(b)
}

func (m *rgMatcher) match(pattern, target ast.Node, env *rgMatchEnv) bool {
	if pattern == nil || target == nil {
		return pattern == target
	}
	// Placeholder identifiers capture any node.
	if id, ok := pattern.(*ast.Ident); ok {
		if kind, name := placeholderKind(id.Name); kind != "" {
			switch kind {
			case "wild":
				return true
			case "list":
				// A lone list placeholder captures the node
				// as a one-element list.
				if existing, ok := env.lists[name]; ok {
					return len(existing) == 1 && m.nodesEqual(existing[0], target)
				}
				env.lists[name] = []ast.Node{target}
				return true
			default:
				if existing, ok := env.vars[name]; ok {
					return m.nodesEqual(existing, target)
				}
				env.vars[name] = target
				return true
			}
		}
	}
	// Parentheses are transparent.
	if paren, ok := pattern.(*ast.ParenExpr); ok {
		return m.match(paren.X, target, env)
	}
	if paren, ok := target.(*ast.ParenExpr); ok {
		return m.match(pattern, paren.X, env)
	}
	return m.matchValue(reflect.ValueOf(pattern), reflect.ValueOf(target), env)
}

func (m *rgMatcher) matchValue(pv, tv reflect.Value, env *rgMatchEnv) bool {
	if !pv.IsValid() || !tv.IsValid() {
		return pv.IsValid() == tv.IsValid()
	}
	if pv.Type() != tv.Type() {
		return false
	}
	switch pv.Kind() {
	case reflect.Pointer:
		if pv.IsNil() || tv.IsNil() {
			return pv.IsNil() == tv.IsNil()
		}
		// If both are AST nodes, go through match() so
		// placeholder and paren handling applies.
		if pNode, ok := pv.Interface().(ast.Node); ok {
			if tNode, ok := tv.Interface().(ast.Node); ok {
				// Avoid infinite recursion for the
				// identical pointer pair that brought us
				// here from match(): matchValue on the
				// structs is what we want for concrete
				// node types.  Recognise that case by
				// checking whether this is a fresh pair:
				// we simply compare the element structs.
				return m.matchValue(pv.Elem(), tv.Elem(), env)
			}
		}
		return m.matchValue(pv.Elem(), tv.Elem(), env)
	case reflect.Interface:
		if pv.IsNil() || tv.IsNil() {
			return pv.IsNil() == tv.IsNil()
		}
		pNode, pok := pv.Interface().(ast.Node)
		tNode, tok := tv.Interface().(ast.Node)
		if pok && tok {
			return m.match(pNode, tNode, env)
		}
		return m.matchValue(pv.Elem(), tv.Elem(), env)
	case reflect.Struct:
		posType := reflect.TypeOf(token.Pos(0))
		for i := 0; i < pv.NumField(); i++ {
			field := pv.Type().Field(i)
			if field.PkgPath != "" { // unexported
				continue
			}
			if field.Name == "Obj" {
				continue
			}
			if field.Type == posType {
				continue
			}
			if !m.matchValue(pv.Field(i), tv.Field(i), env) {
				return false
			}
		}
		return true
	case reflect.Slice, reflect.Array:
		return m.matchSlice(pv, tv, env)
	case reflect.String:
		return pv.String() == tv.String()
	case reflect.Bool:
		return pv.Bool() == tv.Bool()
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return pv.Int() == tv.Int()
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		return pv.Uint() == tv.Uint()
	case reflect.Float32, reflect.Float64:
		return pv.Float() == tv.Float()
	default:
		return reflect.DeepEqual(pv.Interface(), tv.Interface())
	}
}

func sliceElemNode(v reflect.Value) (ast.Node, bool) {
	if !v.IsValid() {
		return nil, false
	}
	if v.Kind() == reflect.Interface {
		if v.IsNil() {
			return nil, false
		}
		v = v.Elem()
	}
	if v.CanInterface() {
		if node, ok := v.Interface().(ast.Node); ok {
			return node, true
		}
	}
	return nil, false
}

func listPlaceholderName(v reflect.Value) (string, bool) {
	node, ok := sliceElemNode(v)
	if !ok {
		return "", false
	}
	if id, ok := node.(*ast.Ident); ok {
		if kind, name := placeholderKind(id.Name); kind == "list" {
			return name, true
		}
	}
	if stmt, ok := node.(*ast.ExprStmt); ok {
		if id, ok := stmt.X.(*ast.Ident); ok {
			if kind, name := placeholderKind(id.Name); kind == "list" {
				return name, true
			}
		}
	}
	return "", false
}

func (m *rgMatcher) matchSlice(pv, tv reflect.Value, env *rgMatchEnv) bool {
	listAt := -1
	var listName string
	for i := 0; i < pv.Len(); i++ {
		if name, ok := listPlaceholderName(pv.Index(i)); ok {
			if listAt >= 0 {
				return false // multiple list placeholders unsupported
			}
			listAt, listName = i, name
		}
	}
	if listAt < 0 {
		if pv.Len() != tv.Len() {
			return false
		}
		for i := 0; i < pv.Len(); i++ {
			if !m.matchValue(pv.Index(i), tv.Index(i), env) {
				return false
			}
		}
		return true
	}
	fixed := pv.Len() - 1
	if tv.Len() < fixed {
		return false
	}
	captureLen := tv.Len() - fixed
	trial := env.clone()
	for i := 0; i < listAt; i++ {
		if !m.matchValue(pv.Index(i), tv.Index(i), trial) {
			return false
		}
	}
	for i := listAt + 1; i < pv.Len(); i++ {
		tIdx := i - 1 + captureLen
		if !m.matchValue(pv.Index(i), tv.Index(tIdx), trial) {
			return false
		}
	}
	var captured []ast.Node
	for i := 0; i < captureLen; i++ {
		if node, ok := sliceElemNode(tv.Index(listAt + i)); ok {
			captured = append(captured, node)
		}
	}
	if existing, ok := trial.lists[listName]; ok {
		if len(existing) != len(captured) {
			return false
		}
		for i := range existing {
			if !m.nodesEqual(existing[i], captured[i]) {
				return false
			}
		}
	} else {
		trial.lists[listName] = captured
	}
	env.commit(trial)
	return true
}

// --- applying rules ----------------------------------------------------

func applyRuleGroup(ctx *runCtx, file *ast.File, group *rgGroup) {
	matcher := &rgMatcher{ctx: ctx}
	ast.Inspect(file, func(n ast.Node) bool {
		if n == nil {
			return true
		}
		for _, rule := range group.rules {
			if !rule.hasReport {
				continue
			}
			// Only try nodes of a compatible broad kind.
			switch rule.pattern.(type) {
			case ast.Expr:
				if _, ok := n.(ast.Expr); !ok {
					continue
				}
			case ast.Stmt:
				if _, ok := n.(ast.Stmt); !ok {
					continue
				}
			}
			env := newRgMatchEnv()
			if !matcher.match(rule.pattern, n, env) {
				continue
			}
			if !evalRuleWhere(ctx, rule, env) {
				continue
			}
			pos := n.Pos()
			if rule.atVar != "" {
				if captured, ok := env.vars[rule.atVar]; ok {
					pos = captured.Pos()
				}
			}
			ctx.warnAt(pos, "%s", substituteRuleMessage(ctx, rule.report, env))
			break
		}
		return true
	})
}

func substituteRuleMessage(ctx *runCtx, msg string, env *rgMatchEnv) string {
	var out strings.Builder
	for i := 0; i < len(msg); i++ {
		if msg[i] != '$' {
			out.WriteByte(msg[i])
			continue
		}
		j := i + 1
		isList := false
		if j < len(msg) && msg[j] == '*' {
			isList = true
			j++
		}
		start := j
		for j < len(msg) {
			r := rune(msg[j])
			if r == '_' || unicode.IsLetter(r) || j > start && unicode.IsDigit(r) {
				j++
				continue
			}
			break
		}
		name := msg[start:j]
		if name == "" {
			out.WriteByte('$')
			continue
		}
		if isList {
			if nodes, ok := env.lists[name]; ok {
				parts := make([]string, len(nodes))
				for k, node := range nodes {
					parts[k] = ctx.nodeTextForRule(node)
				}
				out.WriteString(strings.Join(parts, ", "))
			}
		} else if node, ok := env.vars[name]; ok {
			out.WriteString(ctx.nodeTextForRule(node))
		} else if nodes, ok := env.lists[name]; ok {
			parts := make([]string, len(nodes))
			for k, node := range nodes {
				parts[k] = ctx.nodeTextForRule(node)
			}
			out.WriteString(strings.Join(parts, ", "))
		}
		i = j - 1
	}
	return out.String()
}

func (ctx *runCtx) nodeTextForRule(node ast.Node) string {
	if expr, ok := node.(ast.Expr); ok {
		return ctx.nodeText(expr)
	}
	return ctx.prettyText(node)
}
