package main

import (
	"go/ast"
	"go/constant"
	"go/parser"
	"go/token"
	"go/types"
	"regexp"
	"strings"
)

type rgValueKind int

const (
	rgValNone rgValueKind = iota
	rgValBool
	rgValString
	rgValInt
	rgValVar
	rgValText
	rgValType
	rgValObject
)

type rgValue struct {
	kind rgValueKind
	b    bool
	s    string
	i    int64
	node ast.Node
}

type rgEvaluator struct {
	ctx    *runCtx
	rule   *rgRule
	env    *rgMatchEnv
	locals map[string]interface{} // evaluated local values by name
}

func evalRuleWhere(ctx *runCtx, rule *rgRule, env *rgMatchEnv) bool {
	if len(rule.where) == 0 {
		return true
	}
	ev := &rgEvaluator{ctx: ctx, rule: rule, env: env, locals: make(map[string]interface{})}
	for _, cond := range rule.where {
		v := ev.eval(cond)
		if v == nil {
			return false
		}
		if bval, ok := v.(rgValue); ok {
			if bval.kind != rgValBool || !bval.b {
				return false
			}
			continue
		}
		if b, ok := v.(bool); ok && b {
			continue
		}
		return false
	}
	return true
}

func boolVal(b bool) rgValue { return rgValue{kind: rgValBool, b: b} }

func (ev *rgEvaluator) eval(expr ast.Expr) interface{} {
	switch e := expr.(type) {
	case *ast.ParenExpr:
		return ev.eval(e.X)
	case *ast.BasicLit:
		switch e.Kind {
		case token.STRING:
			if s, ok := stringLitValue(e); ok {
				return rgValue{kind: rgValString, s: s}
			}
		case token.INT:
			if v, ok := constIntValue(ev.ctx, e); ok {
				return rgValue{kind: rgValInt, i: v}
			}
		case token.CHAR:
			if tv, ok := ev.ctx.typeAndValueOf(e); ok && tv.Value != nil {
				if v, exact := constant.Int64Val(tv.Value); exact {
					return rgValue{kind: rgValInt, i: v}
				}
			}
		}
		return nil
	case *ast.Ident:
		switch e.Name {
		case "true":
			return boolVal(true)
		case "false":
			return boolVal(false)
		case "nil":
			return rgValue{kind: rgValString, s: "\x00nil"}
		}
		if ev.locals != nil {
			if v, ok := ev.locals[e.Name]; ok {
				return v
			}
		}
		if stored, ok := ev.rule.locals[e.Name]; ok {
			return ev.eval(stored)
		}
		return nil
	case *ast.IndexExpr:
		if name, ok := matcherIndexName(e, ev.rule.matcherName); ok {
			if node, captured := ev.env.vars[name]; captured {
				return rgValue{kind: rgValVar, node: node}
			}
			if nodes, captured := ev.env.lists[name]; captured && len(nodes) == 1 {
				return rgValue{kind: rgValVar, node: nodes[0]}
			}
			return rgValue{kind: rgValVar}
		}
		return nil
	case *ast.UnaryExpr:
		v := ev.eval(e.X)
		if e.Op == token.NOT {
			if b, ok := asBool(v); ok {
				return boolVal(!b)
			}
		}
		if e.Op == token.SUB {
			if iv, ok := v.(rgValue); ok && iv.kind == rgValInt {
				return rgValue{kind: rgValInt, i: -iv.i}
			}
		}
		return nil
	case *ast.BinaryExpr:
		return ev.evalBinary(e)
	case *ast.SelectorExpr:
		return ev.evalSelector(e)
	case *ast.CallExpr:
		return ev.evalCall(e)
	}
	return nil
}

func asBool(v interface{}) (bool, bool) {
	if rv, ok := v.(rgValue); ok && rv.kind == rgValBool {
		return rv.b, true
	}
	if b, ok := v.(bool); ok {
		return b, true
	}
	return false, false
}

func asString(v interface{}) (string, bool) {
	if rv, ok := v.(rgValue); ok {
		switch rv.kind {
		case rgValString, rgValText:
			return rv.s, true
		}
	}
	if s, ok := v.(string); ok {
		return s, true
	}
	return "", false
}

func (ev *rgEvaluator) evalBinary(e *ast.BinaryExpr) interface{} {
	// Short-circuit for && and ||.
	if e.Op == token.LAND || e.Op == token.LOR {
		left, lok := asBool(ev.eval(e.X))
		if !lok {
			return nil
		}
		if e.Op == token.LAND && !left {
			return boolVal(false)
		}
		if e.Op == token.LOR && left {
			return boolVal(true)
		}
		right, rok := asBool(ev.eval(e.Y))
		if !rok {
			return nil
		}
		return boolVal(right)
	}
	lv, rv := ev.eval(e.X), ev.eval(e.Y)
	// String comparison (Text values surface as strings).
	if ls, ok := asString(lv); ok {
		if rs, ok := asString(rv); ok {
			switch e.Op {
			case token.EQL:
				return boolVal(ls == rs)
			case token.NEQ:
				return boolVal(ls != rs)
			case token.ADD:
				return rgValue{kind: rgValString, s: ls + rs}
			}
		}
	}
	if ln, ok := lv.(rgValue); ok && ln.kind == rgValInt {
		if rn, ok := rv.(rgValue); ok && rn.kind == rgValInt {
			switch e.Op {
			case token.EQL:
				return boolVal(ln.i == rn.i)
			case token.NEQ:
				return boolVal(ln.i != rn.i)
			case token.LSS:
				return boolVal(ln.i < rn.i)
			case token.LEQ:
				return boolVal(ln.i <= rn.i)
			case token.GTR:
				return boolVal(ln.i > rn.i)
			case token.GEQ:
				return boolVal(ln.i >= rn.i)
			case token.ADD:
				return rgValue{kind: rgValInt, i: ln.i + rn.i}
			case token.SUB:
				return rgValue{kind: rgValInt, i: ln.i - rn.i}
			}
		}
	}
	if lb, ok := asBool(lv); ok {
		if rb, ok := asBool(rv); ok {
			switch e.Op {
			case token.EQL:
				return boolVal(lb == rb)
			case token.NEQ:
				return boolVal(lb != rb)
			}
		}
	}
	return nil
}

func (ev *rgEvaluator) evalSelector(e *ast.SelectorExpr) interface{} {
	base := ev.eval(e.X)
	rv, ok := base.(rgValue)
	if !ok || rv.kind != rgValVar {
		return nil
	}
	node := rv.node
	switch e.Sel.Name {
	case "Pure":
		if expr, ok := node.(ast.Expr); ok {
			return boolVal(isPureExpr(expr))
		}
		return boolVal(false)
	case "Const":
		if expr, ok := node.(ast.Expr); ok {
			return boolVal(ev.ctx.isConstantExpr(expr))
		}
		return boolVal(false)
	case "Addressable":
		if expr, ok := node.(ast.Expr); ok {
			if tv, ok := ev.ctx.typeAndValueOf(expr); ok {
				return boolVal(tv.Addressable())
			}
		}
		return boolVal(false)
	case "Text":
		text := ""
		if node != nil {
			text = ev.ctx.nodeTextForRule(node)
		}
		return rgValue{kind: rgValText, s: text, node: node}
	case "Type":
		return rgValue{kind: rgValType, node: node}
	case "Object":
		return rgValue{kind: rgValObject, node: node}
	case "Value":
		if expr, ok := node.(ast.Expr); ok {
			if tv, ok := ev.ctx.typeAndValueOf(expr); ok && tv.Value != nil && tv.Value.Kind() == constant.Int {
				if v, exact := constant.Int64Val(tv.Value); exact {
					return rgValue{kind: rgValInt, i: v}
				}
			}
		}
		return nil
	}
	return nil
}

func (ev *rgEvaluator) evalCall(e *ast.CallExpr) interface{} {
	// Custom helper functions defined in the rules file.
	if id, ok := e.Fun.(*ast.Ident); ok {
		if ev.rule != nil && ev.rule.group != nil {
			if fn, ok := ev.rule.group.customFuncs[id.Name]; ok {
				return ev.evalCustomFunc(fn, e.Args)
			}
		}
		return nil
	}
	sel, ok := e.Fun.(*ast.SelectorExpr)
	if !ok {
		return nil
	}
	base := ev.eval(sel.X)
	// Var.Text.Method-style chains arrive here with the receiver
	// being a selector result (Text/Type/Object wrappers).
	if rv, ok := base.(rgValue); ok {
		switch rv.kind {
		case rgValText:
			if sel.Sel.Name == "Matches" && len(e.Args) == 1 {
				pattern, ok := asString(ev.eval(e.Args[0]))
				if !ok {
					return nil
				}
				matched, err := regexp.MatchString(pattern, rv.s)
				if err != nil {
					return nil
				}
				return boolVal(matched)
			}
		case rgValType:
			return ev.evalTypeMethod(rv.node, sel.Sel.Name, e.Args)
		case rgValObject:
			if sel.Sel.Name == "Is" && len(e.Args) == 1 {
				want, ok := asString(ev.eval(e.Args[0]))
				if !ok {
					return nil
				}
				return boolVal(ev.objectMatches(rv.node, want))
			}
		case rgValVar:
			// Method-style Var.Text() / Var.Type() spellings.
			switch sel.Sel.Name {
			case "Text":
				text := ""
				if rv.node != nil {
					text = ev.ctx.nodeTextForRule(rv.node)
				}
				return rgValue{kind: rgValText, s: text, node: rv.node}
			case "Type":
				return rgValue{kind: rgValType, node: rv.node}
			}
		}
	}
	return nil
}

func (ev *rgEvaluator) objectMatches(node ast.Node, want string) bool {
	if node == nil {
		return false
	}
	var obj types.Object
	switch n := node.(type) {
	case *ast.Ident:
		obj = ev.ctx.objectOf(n)
	case *ast.SelectorExpr:
		obj = ev.ctx.objectOf(n.Sel)
	}
	if obj == nil {
		return false
	}
	if obj.Pkg() == nil {
		return want == "builtin "+obj.Name() || want == obj.Name()
	}
	full := obj.Pkg().Path() + "." + obj.Name()
	short := obj.Pkg().Name() + "." + obj.Name()
	return want == full || want == short || want == obj.Name()
}

func (ev *rgEvaluator) capturedType(node ast.Node) types.Type {
	if expr, ok := node.(ast.Expr); ok {
		return ev.ctx.typeOf(expr)
	}
	return nil
}

func (ev *rgEvaluator) evalTypeMethod(node ast.Node, method string, args []ast.Expr) interface{} {
	captured := ev.capturedType(node)
	if captured == nil {
		return nil
	}
	if method == "Size" {
		// .Type.Size isn't part of the core surface we model;
		// treat as unsupported.
		return nil
	}
	if len(args) != 1 {
		return nil
	}
	typeText, ok := asString(ev.eval(args[0]))
	if !ok {
		return nil
	}
	wantType := ev.resolveTypeText(typeText)
	switch method {
	case "Is":
		if wantType != nil {
			return boolVal(types.Identical(captured, wantType))
		}
		// String fallback.
		got := types.TypeString(captured, func(p *types.Package) string { return p.Name() })
		return boolVal(got == typeText)
	case "AssignableTo":
		if wantType == nil {
			return nil
		}
		return boolVal(types.AssignableTo(captured, wantType))
	case "ConvertibleTo":
		if wantType == nil {
			return nil
		}
		return boolVal(types.ConvertibleTo(captured, wantType))
	case "Implements":
		if wantType == nil {
			return nil
		}
		iface, ok := wantType.Underlying().(*types.Interface)
		if !ok {
			return nil
		}
		return boolVal(types.Implements(captured, iface) || types.Implements(types.NewPointer(captured), iface))
	case "HasMethod":
		return boolVal(typeHasMethodNamed(captured, typeText) || typeHasMethodNamed(types.NewPointer(captured), typeText))
	}
	return nil
}

// resolveTypeText parses a type expression in text form (as used in
// Type.Is and friends) into a types.Type where it reasonably can.
func (ev *rgEvaluator) resolveTypeText(text string) types.Type {
	expr, err := parser.ParseExpr(text)
	if err != nil {
		return nil
	}
	return ev.resolveTypeExpr(expr)
}

func (ev *rgEvaluator) resolveTypeExpr(expr ast.Expr) types.Type {
	switch e := expr.(type) {
	case *ast.Ident:
		if obj := types.Universe.Lookup(e.Name); obj != nil {
			if tn, ok := obj.(*types.TypeName); ok {
				return tn.Type()
			}
		}
		if ev.ctx.types != nil {
			if obj := ev.ctx.types.Scope().Lookup(e.Name); obj != nil {
				if tn, ok := obj.(*types.TypeName); ok {
					return tn.Type()
				}
			}
		}
		return nil
	case *ast.SelectorExpr:
		pkgName := identName(e.X)
		// Resolve through rule imports first, then the checked
		// package's own imports.
		var pkg *types.Package
		if ev.rule != nil && ev.rule.group != nil {
			if path, ok := ev.rule.group.imports[pkgName]; ok && ev.ctx.pkg != nil {
				if imported, ok2 := ev.ctx.pkg.Imports[path]; ok2 {
					pkg = imported.Types
				}
			}
		}
		if pkg == nil && ev.ctx.pkg != nil {
			for _, imported := range ev.ctx.pkg.Imports {
				if imported.Name == pkgName {
					pkg = imported.Types
					break
				}
			}
		}
		if pkg == nil {
			return nil
		}
		if obj := pkg.Scope().Lookup(e.Sel.Name); obj != nil {
			if tn, ok := obj.(*types.TypeName); ok {
				return tn.Type()
			}
		}
		return nil
	case *ast.StarExpr:
		if inner := ev.resolveTypeExpr(e.X); inner != nil {
			return types.NewPointer(inner)
		}
	case *ast.ArrayType:
		elt := ev.resolveTypeExpr(e.Elt)
		if elt == nil {
			return nil
		}
		if e.Len == nil {
			return types.NewSlice(elt)
		}
		if lit, ok := e.Len.(*ast.BasicLit); ok {
			if n, err := strconvParseInt(lit.Value); err == nil {
				return types.NewArray(elt, n)
			}
		}
	case *ast.MapType:
		k := ev.resolveTypeExpr(e.Key)
		v := ev.resolveTypeExpr(e.Value)
		if k != nil && v != nil {
			return types.NewMap(k, v)
		}
	case *ast.ChanType:
		v := ev.resolveTypeExpr(e.Value)
		if v == nil {
			return nil
		}
		dir := types.SendRecv
		if e.Dir&ast.SEND != 0 && e.Dir&ast.RECV == 0 {
			dir = types.SendOnly
		} else if e.Dir&ast.RECV != 0 && e.Dir&ast.SEND == 0 {
			dir = types.RecvOnly
		}
		return types.NewChan(dir, v)
	case *ast.ParenExpr:
		return ev.resolveTypeExpr(e.X)
	}
	return nil
}

func strconvParseInt(s string) (int64, error) {
	return parseIntLiteral(s)
}

func (ev *rgEvaluator) evalCustomFunc(fn *ast.FuncDecl, args []ast.Expr) interface{} {
	if fn.Body == nil || len(fn.Body.List) != 1 {
		return nil
	}
	ret, ok := fn.Body.List[0].(*ast.ReturnStmt)
	if !ok || len(ret.Results) != 1 {
		return nil
	}
	saved := ev.locals
	ev.locals = make(map[string]interface{})
	defer func() { ev.locals = saved }()
	idx := 0
	if fn.Type != nil && fn.Type.Params != nil {
		for _, field := range fn.Type.Params.List {
			for _, name := range field.Names {
				if idx < len(args) {
					ev.locals[name.Name] = ev.eval(args[idx])
				}
				idx++
			}
		}
	}
	return ev.eval(ret.Results[0])
}
