			case token.SUB:
				return rgValue{kind: rgValInt, i: ln.i - rn.i}
			}
		}
	}
	if lb, ok := asBool(lv); ok {
		if rb, ok := asBool(rv); ok {
			switch e.Op {
			case token.EQL:
				return boolVal(lb == rb)
			case token.NEQ:
				return boolVal(lb != rb)
			}
		}
	}
	return nil
}

