func (ev *rgEvaluator) resolveTypeExpr(expr ast.Expr) types.Type {
	switch e := expr.(type) {
	case *ast.Ident:
		if obj := types.Universe.Lookup(e.Name); obj != nil {
			if tn, ok := obj.(*types.TypeName); ok {
				return tn.Type()
			}
		}
		if ev.ctx.types != nil {
			if obj := ev.ctx.types.Scope().Lookup(e.Name); obj != nil {
				if tn, ok := obj.(*types.TypeName); ok {
					return tn.Type()
				}
			}
		}
		return nil
	case *ast.SelectorExpr:
		pkgName := identName(e.X)
		// Resolve through rule imports first, then the checked
		// package's own imports.
		var pkg *types.Package
		if ev.rule != nil && ev.rule.group != nil {
			if path, ok := ev.rule.group.imports[pkgName]; ok && ev.ctx.pkg != nil {
