new=r'''func parseRuleguardPattern(src string) (ast.Node, error) {
	transformed := transformRuleguardPattern(src)
	// Tokenize first so scanner errors are reported in the same
	// category as the reference implementation.
	{
		fset := token.NewFileSet()
		file := fset.AddFile("", -1, len(transformed))
		var scanErr error
		var sc scanner.Scanner
		sc.Init(file, []byte(transformed), func(pos token.Position, msg string) {
			if scanErr == nil {
				scanErr = fmt.Errorf("%d:%d: %s", pos.Line, pos.Column, msg)
			}
		}, scanner.ScanComments)
		for {
			_, tok, _ := sc.Scan()
			if tok == token.EOF {
				break
			}
		}
		if scanErr != nil {
			return nil, fmt.Errorf("cannot tokenize expr: %s", scanErr)
		}
	}
	fset := token.NewFileSet()
	if expr, err := parser.ParseExprFrom(fset, "", transformed, parser.SkipObjectResolution); err == nil {
		return expr, nil
	} else {
		// Try as statements/declarations inside a function body.
		wrapped := "package _\nfunc _(){\n" + transformed + "\n}"
		file, ferr := parser.ParseFile(fset, "", wrapped, parser.SkipObjectResolution)
