import subprocess, sys, os
O='/workspace/executable';N='/tmp/newbin'
def run(exe,args,cwd='/tmp',timeout=60):
 try:
  p=subprocess.run([exe,'check']+args,cwd=cwd,capture_output=True,text=True,timeout=timeout)
  return p.returncode,p.stdout,p.stderr
 except subprocess.TimeoutExpired as e:
  return 'TIMEOUT','',(e.stderr or b'').decode(errors='replace')
def compare(args,cwd='/tmp',label=''):
 o=run(O,args,cwd);n=run(N,args,cwd)
 if o==n:
  print('MATCH',label,args,'rc',o[0],'lines',len(o[2].splitlines())); return
 print('DIFF',label,args,'orig rc',o[0],len(o[2].splitlines()),'new rc',n[0],len(n[2].splitlines()))
 ol=o[2].splitlines();nl=n[2].splitlines()
 so=set(ol);sn=set(nl)
 print(' only orig sample:')
 for x in sorted(so-sn)[:40]:print('  ',x)
 print(' only new sample:')
 for x in sorted(sn-so)[:40]:print('  ',x)
 if so==sn: print(' same set, order differs')
PY
